    difficulty: 5,
    title: '2008年冰岛金融危机',
    description: '2008年10月，冰岛这个仅有30万人口的北欧岛国经历了人类历史上最严重的银行崩溃之一。冰岛三大银行——Glitnir、Landsbanki和Kaupthing在短短数天内相继倒闭，其合并资产规模达到冰岛GDP的约10倍，使冰岛从全球最富裕的国家之一跌入深渊。 冰岛危机的根源在于其银行体系在2000年代初期的过度扩张。2000年，冰岛对银行业实行了大规模私有化，三大银行从传统的国内储蓄机构迅速转型',
    context: '为国际投资银行。它们利用冰岛较高的利率吸引大量海外存款（特别是通过Landsbanki的Icesave在线储蓄账户在英国和荷兰吸纳了数十亿欧元），并大举进行跨境收购和投资。2003年至2007年间，三大银行的资产规模膨胀了约8倍，从约200亿美元增至超过1700亿美元。 这种扩张模式存在致命缺陷。银行大量借入短期外币债务，投资于长期资产，形成了严重的期限错配和货币错配。当全球金融危机导致国际信贷市场冻结时，冰岛银行无法再融资其短期债务，流动性危机迅速演变为偿付能力危机。冰岛克朗大幅贬值，从2008年初的约60克朗兑1欧元跌至危机高峰时的超过300克朗，进一步加重了外币债务负担。 2008年9月底，冰岛政府被迫接管Glitnir银行。10月6日，冰岛议会通过紧急法案授权政府接管金融机构。次日，Landsbanki和Kaupthing相继被接管。冰岛股市暴跌超过90%，暂停交易数日。冰岛克朗几',
