    id: 'case_7',
    category: '危机',
    difficulty: 5,
    title: '2009年迪拜债务危机',
    description: '2009年11月25日，迪拜政府宣布其旗舰企业迪拜世界（Dubai World）将寻求延迟偿还590亿美元债务，这一消息震惊了全球金融市场，引发了新兴市场资产的大幅抛售。迪拜世界是迪拜政府控股的综合性企业集团，旗下拥有房地产开发商Nakheel（棕榈岛的建造者）和港口运营商DP World等知名企业。 迪拜危机的根源在于其发展模式对债务融资的过度依赖。2000年代，迪拜凭借雄心勃勃的基础设施建设和',
    context: '房地产项目，从沙漠小城迅速崛起为中东的金融和旅游中心。然而，这些宏大项目的资金主要来源于债务融资。迪拜世界及其子公司大量发行债券和获取银团贷款，用于建设棕榈岛、世界岛、迪拜塔等标志性项目。到2009年，迪拜政府及其关联实体的总债务估计超过800亿美元，而迪拜的GDP仅为约750亿美元。 2008年全球金融危机对迪拜造成了严重冲击。国际信贷市场冻结使迪拜无法继续借新还旧，房地产价格从峰值下跌超过50%，大量在建项目被迫停工，外国投资者和居民撤离导致住房需求急剧萎缩。Nakheel的房地产项目销售几乎停滞，现金流严重不足，无法偿还即将到期的伊斯兰债券（Sukuk）。 迪拜世界的债务重组过程漫长而复杂。最初，市场担心迪拜的债务问题会引发主权违约，并波及阿布扎比等其他阿联酋酋长国。阿布扎比最终提供了100亿美元的紧急援助，帮助迪拜世界偿还了Nakheel一笔35亿美元的到期伊斯兰债券。经过多轮谈判',
