    title: '2010年欧洲主权债务危机——希腊',
    description: '2010年，希腊主权债务危机全面爆发，成为欧元区自成立以来面临的最严峻考验。这场危机不仅威胁到希腊的经济稳定，更对欧元区的完整性和欧元的存续构成了根本性挑战。 希腊危机的根源可以追溯到其加入欧元区的过程。1999年欧元启动时，希腊未能满足《马斯特里赫特条约》规定的趋同标准（财政赤字不超过GDP的3%，公共债务不超过GDP的60%）。2001年，希腊在高盛的帮助下通过复杂的货币互换交易掩盖了真实的财',
    context: '政状况，成功加入欧元区。此后，希腊持续低估赤字和债务水平，实际财政状况远比官方数据糟糕。2009年10月，新上任的帕潘德里欧政府披露，希腊2009年财政赤字占GDP的比例将达到12.7%，远超此前预估的6%，随后这一数字又被修正至15.6%。 市场对希腊的信心迅速崩塌。希腊国债收益率飙升，10年期国债收益率从2009年中的约6%升至2010年4月的超过12%，融资成本变得不可持续。信用评级机构连续下调希腊主权评级，从A级一路降至垃圾级。希腊面临无法在国际市场上融资的困境，债务违约风险迫在眉睫。 2010年5月，欧元区国家和IMF联合推出了1100亿欧元的希腊救助方案，条件是希腊实施严厉的财政紧缩和结构性改革。救助方案要求希腊将财政赤字从占GDP的13.6%削减至3%以下，措施包括大幅削减公务员工资和养老金、提高增值税率、改革税收和养老金体系等。这些紧缩措施导致希腊经济陷入严重衰退，GDP在',
