    id: 'case_9',
    category: '危机',
    difficulty: 5,
    title: '2011年美国债务上限危机',
    description: '2011年夏天，美国围绕提高债务上限的政治僵局将国家推至违约边缘，引发了全球金融市场的剧烈震荡。这场危机不仅是对美国政治制度的严峻考验，也对美元的信用和美国国债作为全球最安全资产的地位提出了前所未有的质疑。 美国债务上限是国会设定的联邦政府借款总额上限。2011年5月16日，美国联邦债务触及14.29万亿美元的法定上限。按照惯例，国会应在财政部耗尽所有紧急措施之前投票提高上限。然而，在2010年中',
    context: '期选举后掌控众议院的共和党人坚持，提高债务上限必须以大幅削减政府支出为条件，而民主党则主张增税应成为解决方案的一部分。双方立场尖锐对立，谈判陷入僵局。 随着8月2日的最后期限逼近，市场紧张情绪急剧升温。美国国债的信用违约互换利差大幅扩大，短期国债收益率出现异常波动，货币市场基金开始减少对美国国债的敞口。一些金融机构制定了美国国债违约的应急预案，这在历史上是前所未有的。如果美国真的违约，将导致数百万社会保障和军人薪金支付中断，全球金融市场将遭受灾难性冲击。 7月31日，两党终于在最后时刻达成协议，通过了《2011年预算控制法案》，将债务上限提高2.1万亿美元，同时要求在未来十年削减约2.4万亿美元的支出，并设立减赤"超级委员会"。然而，这一协议被市场认为缺乏实质性的财政改革内容。8月5日，标准普尔做出了历史性的决定，将美国主权信用评级从AAA下调至AA+，这是美国自1941年以来首次失去最高',
