    id: 'case_10',
    category: '危机',
    difficulty: 5,
    title: '2012年塞浦路斯银行业危机',
    description: '2012年至2013年，塞浦路斯这个地中海岛国爆发了严重的银行业危机，其处理方式——对储户实施"存款减记"——在欧元区历史上尚属首次，引发了全球对存款安全性的深刻担忧。 塞浦路斯银行业危机的核心问题在于其银行体系的过度膨胀和对希腊的风险敞口。塞浦路斯银行和大众银行（Laiki Bank）两大银行的总资产达到塞浦路斯GDP的约7倍，远超其经济承受能力。更致命的是，这两家银行持有大量希腊政府债券和希腊',
    context: '企业贷款。2012年希腊债务重组时，私人部门债权人被迫接受了约53.5%的名义减记，塞浦路斯银行因此损失约45亿欧元，资本基础遭到严重侵蚀。 此外，塞浦路斯银行业吸引了大量俄罗斯富人的存款，部分原因在于塞浦路斯较低的企业税率和相对宽松的反洗钱监管。这些非居民存款占银行体系存款的约30%，使塞浦路斯被一些人视为"洗钱天堂"。当危机爆发时，这些资金面临外逃风险，进一步加剧了银行体系的脆弱性。 2013年3月，欧元集团提出了一个前所未有的救助方案：对塞浦路斯银行存款实施"减记"（bail-in），即直接从储户的存款中扣除一部分用于银行资本重组。方案要求对10万欧元以下的存款征收6.75%的税费，对10万欧元以上的存款征收9.9%的税费。这一方案在塞浦路斯议会遭到否决，引发了市场恐慌。 最终方案在3月25日达成。大众银行被拆分，其10万欧元以下的健康存款转移至塞浦路斯银行，10万欧元以上的存款被冻',
