    id: 'case_11',
    category: '金融史',
    difficulty: 3,
    title: '2013年缩减恐慌（Taper Tantrum）',
    description: '2013年5月至6月，全球金融市场经历了一场剧烈震荡，被称为"缩减恐慌"（Taper Tantrum）。这场风波的起因是美联储主席伯南克在国会证词中暗示，美联储可能开始缩减其每月850亿美元的资产购买规模（即第三轮量化宽松，QE3），这标志着超宽松货币政策可能逐步退出。 2013年5月22日，伯南克在国会联合经济委员会作证时表示，如果经济数据持续改善，美联储可能在"接下来的几次会议上"开始缩减资产',
    context: '购买。这一表态虽然措辞谨慎，但市场将其解读为货币政策即将收紧的明确信号，引发了全球债券市场的抛售潮。美国10年期国债收益率从5月初的约1.6%飙升至9月初的约3%，涨幅近140个基点，为数十年来最剧烈的利率波动之一。 新兴市场受到的冲击尤为严重。资本大规模从新兴市场回流美国，导致新兴市场货币大幅贬值、债券利差扩大、股市暴跌。印度卢比在5月至8月间贬值约20%，印尼盾贬值约15%，巴西雷亚尔贬值约15%。这些国家普遍面临经常账户赤字和通胀压力，资本外流使其经济状况雪上加霜。印度央行行长拉詹将缩减恐慌描述为"美联储打喷嚏，新兴市场就感冒"。 缩减恐慌暴露了全球金融体系对美联储政策的深度依赖。在量化宽松期间，大量廉价美元流入新兴市场寻求更高收益，形成了巨大的利差交易头寸。当美联储暗示政策转向时，这些头寸的迅速逆转引发了市场动荡。同时，缩减恐慌也暴露了部分新兴市场国家的结构性弱点——经常账户赤字、',
