    category: '危机',
    difficulty: 5,
    title: '2014年俄罗斯金融危机',
    description: '2014年，俄罗斯遭遇了严重的金融危机，卢布大幅贬值、资本外逃加剧、经济陷入衰退。这场危机是地缘政治冲突和全球大宗商品价格下跌双重冲击的结果，对俄罗斯经济造成了深远影响。 危机的首要触发因素是2014年3月克里米亚事件后西方对俄罗斯实施的制裁。美国和欧盟对俄罗斯的关键部门（能源、金融、国防）实施了多轮制裁，限制了俄罗斯大型银行和能源企业在西方资本市场的融资渠道。俄罗斯国家石油公司（Rosneft）',
    context: '、俄罗斯联邦储蓄银行（Sberbank）等系统重要性机构被禁止在欧美市场发行期限超过30天的债券和股票。这些制裁严重限制了俄罗斯企业和银行的再融资能力。 第二个冲击来自国际油价的暴跌。2014年6月至12月，布伦特原油价格从每桶约115美元跌至约60美元，跌幅近50%。石油和天然气出口占俄罗斯出口收入的约70%和联邦预算收入的约50%，油价暴跌直接导致俄罗斯财政收入锐减和贸易顺差大幅收窄。 双重冲击下，卢布急剧贬值。2014年全年，卢布对美元贬值超过70%，从年初的约33卢布兑1美元跌至年底的约56卢布。12月15日至16日，卢布在两天内暴跌约25%，被称为"黑色周二"。俄罗斯央行紧急将基准利率从10.5%提高至17%，但仍未能阻止卢布跌势。民众恐慌性抢购进口商品和汽车，以对冲卢布贬值风险。 为稳定局势，俄罗斯政府采取了多项措施。央行动用了约880亿美元的外汇储备干预市场，并推出了浮动汇率',
