    description: '2015年6月至8月，中国A股市场经历了剧烈的暴跌，上证综合指数从6月12日的5178点高位在不到两个月内跌至8月26日的2850点，跌幅超过45%。这场股灾不仅造成了巨大的财富损失，也暴露了中国资本市场在制度建设和监管方面的深层次问题。 股灾前的牛市始于2014年下半年，其驱动力包括：货币政策的宽松（央行多次降息降准）、改革预期的升温（混合所有制改革、"一带一路"战略等）、以及杠杆资金的涌入。最',
    context: '关键的因素是场外配资的野蛮生长——大量投资者通过伞形信托、民间配资公司等渠道以高达1:5甚至1:10的杠杆比例借入资金炒股。据估计，场外配资规模达到1万亿至2万亿元人民币，加上券商融资融券的约2.2万亿元，A股市场的杠杆资金总量超过3万亿元。 2015年6月12日，证监会宣布严查场外配资，成为牛市的转折点。随着配资清理的推进，高杠杆投资者被迫平仓，形成"下跌—平仓—进一步下跌"的恶性循环。千股跌停成为常态，市场流动性几乎枯竭——大量股票开盘即跌停，卖单无法成交。 政府的救市措施力度空前。6月27日，央行实施"双降"（降息降准）。7月初，证监会暂停IPO发行，21家券商宣布出资1200亿元购买蓝筹ETF。公安部介入调查"恶意做空"，限制股指期货交易。7月8日，国资委要求央企不得减持股票，证监会限制大股东减持。8月，央行再次降息降准，并实施人民币汇率中间价改革（"811汇改"），但汇改引发的贬',
