    title: '2015年瑞士法郎脱钩欧元',
    description: '2015年1月15日，瑞士国家银行（SNB）突然宣布放弃瑞士法郎对欧元的汇率上限，这一决定引发了外汇市场的剧烈震荡，被称为"瑞士法郎冲击"（Franc Shock）。瑞郎在消息公布后的几分钟内对欧元升值近30%，从1.20瑞郎兑1欧元飙升至约0.85瑞郎，随后稳定在1.0左右。 瑞士法郎汇率上限的设立始于2011年9月。当时欧债危机导致大量避险资金涌入瑞士，瑞郎大幅升值威胁到瑞士的出口竞争力。SN',
    context: 'B设定了1.20瑞郎兑1欧元的最低汇率，并承诺无限量购买外汇以维持这一上限。到2014年底，SNB的外汇储备已膨胀至约4950亿瑞郎，占GDP的比重超过70%。 SNB放弃汇率上限的原因是多方面的。首先，欧洲央行即将推出量化宽松政策，这意味着欧元将进一步贬值，SNB维持汇率上限的成本将急剧增加。其次，瑞郎与欧元的挂钩使瑞士输入了欧元的宽松货币政策，导致瑞士房地产泡沫风险上升。第三，SNB此前一直否认会放弃上限，甚至在2014年12月还重申了承诺，这使得市场对汇率上限的信心较高，大量投资者建立了瑞郎空头头寸。 放弃上限的决定对外汇市场造成了毁灭性冲击。瑞郎的瞬间暴涨导致大量外汇交易者爆仓，多家外汇经纪商遭受严重损失。新西兰外汇经纪商Global Brokers NZ因客户亏损超过其保证金而倒闭。福汇（FXCM）获得3亿美元紧急贷款以弥补客户亏损。花旗银行据报道在当天损失超过1.5亿美元。对冲',
