    title: '2016年英国脱欧公投市场震荡',
    description: '2016年6月23日，英国举行脱欧公投，51.9%的选民投票支持离开欧盟，这一出人意料的结果引发了全球金融市场的剧烈震荡。公投前，大多数民调、博彩赔率和市场定价都预期英国将留在欧盟，因此脱欧结果对市场造成了巨大的冲击。 公投结果公布后，英镑对美元汇率暴跌超过10%，从约1.50跌至1.32，创下31年来最低水平。英镑对欧元也大幅贬值。英国富时100指数在公投次日开盘下跌约8%，银行股遭受重创，巴克',
    context: '莱和劳埃德银行股价暴跌超过20%。欧洲股市同样大幅下挫，法国CAC40指数和德国DAX指数均下跌约8%。全球股市在公投后两天内蒸发约3万亿美元市值。 英国房地产市场受到严重冲击。多家房地产基金因赎回压力而暂停赎回，包括M&G Investments、Standard Life Investments和Aviva Investors等知名机构管理的基金。这是自2008年金融危机以来英国房地产基金首次大规模暂停赎回，加剧了市场恐慌。 英格兰银行迅速采取应对措施。行长卡尼在公投次日发表声明，表示央行已做好提供超过2500亿英镑额外流动性的准备。7月，英格兰银行将基准利率从0.5%降至0.25%的历史新低，并重启了600亿英镑的量化宽松计划，包括购买100亿英镑的公司债。同时推出了定期融资计划（TFS），为银行提供低成本资金以鼓励放贷。 脱欧公投的长期影响更为深远。英镑的持续贬值推高了进口价格和通',
