    title: '2018年土耳其货币危机',
    description: '2018年8月，土耳其里拉遭遇了灾难性的贬值，引发了新兴市场的广泛恐慌。里拉在8月份对美元贬值超过30%，从年初的约3.8里拉兑1美元跌至8月底的约6.9里拉，全年贬值幅度超过40%。这场危机的根源深植于土耳其经济的结构性问题和政治体制的缺陷。 土耳其经济在2010年代经历了高速增长，但这种增长严重依赖信贷扩张和外部融资。企业大量借入美元和欧元债务，形成了严重的货币错配。截至2018年，土耳其外债',
    context: '总额超过4500亿美元，约占GDP的50%，其中短期外债规模庞大。经常账户持续赤字，2017年赤字占GDP的5.5%，意味着土耳其需要持续的外部融资来维持经济运转。 土耳其央行的独立性受到严重侵蚀是危机的关键因素。总统埃尔多安多次公开反对加息，甚至声称"高利率是万恶之源"，并威胁要在选举后赋予自己任命央行行长的权力。这种政治干预严重削弱了市场对土耳其货币政策的信心。当通胀率在2018年突破15%时，央行仍迟迟不敢大幅加息，导致实际利率为负，里拉贬值预期自我强化。 2018年8月10日，特朗普宣布对土耳其钢铁和铝产品加倍征收关税，分别提高至50%和20%，成为危机的导火索。里拉在当天暴跌约16%，创下单日最大跌幅纪录。里拉的暴跌通过"传染效应"波及其他新兴市场，南非兰特、阿根廷比索、印度卢比等货币纷纷承压，市场担忧1997年亚洲金融危机式的连锁反应。 危机的应对充满争议。土耳其政府采取了部分',
