    title: '2020年新冠疫情全球市场崩盘',
    description: '2020年2月至3月，新冠疫情在全球蔓延引发了金融市场的史诗级崩盘。美国股市在3月份经历了四次熔断，仅在3月9日至18日的10天内就触发了四次熔断机制，而此前美股历史上仅有过一次熔断（1997年）。道琼斯指数从2月12日的29568点跌至3月23日的18591点，跌幅超过37%。 疫情对金融市场的冲击是全方位的。股票市场首当其冲，全球股市在2月下旬至3月下旬间蒸发约30万亿美元市值。债券市场也出现',
    context: '异常——甚至美国国债和黄金等传统避险资产也在初期遭到抛售，投资者为获取流动性而出售一切资产。公司债利差飙升，高收益债券利差从约3%扩大至超过10%。商业票据市场冻结，企业短期融资渠道中断。 石油市场的崩盘加剧了金融动荡。3月6日，OPEC与俄罗斯的减产谈判破裂，沙特发动价格战，布伦特原油价格在3月9日暴跌约30%，至约33美元/桶，创下1991年海湾战争以来最大单日跌幅。4月20日，WTI原油5月期货合约更是跌至史无前例的-37.63美元/桶，即卖家需要倒贴买家来接手原油，这一奇观反映了储油设施满载的极端情况。 美联储的应对力度前所未有。3月3日和15日，美联储紧急降息共150个基点至0-0.25%。3月15日，美联储宣布7000亿美元的量化宽松计划。3月23日，美联储推出"无限量QE"，并设立了多项紧急信贷便利工具，包括商业票据融资便利（CPFF）、一级交易商信贷便利（PDCF）、货币市',
