    title: '2021年Archegos爆仓事件',
    description: '2021年3月，家族办公室Archegos资本管理公司的爆仓引发了超过100亿美元的华尔街损失，成为近年来最引人注目的杠杆交易灾难之一。Archegos由前老虎亚洲基金经理比尔·黄（Bill Hwang）管理，管理资产规模从2013年的约2亿美元增长至2021年初的约100亿美元，其激进的投资策略和极高的杠杆率最终导致了灾难性的结局。 Archegos的投资策略核心是高集中度、高杠杆。它集中持有少',
    context: '数几只股票的大额头寸，包括ViacomCBS、Discovery、腾讯音乐、唯品会、跟谁学等。更关键的是，Archegos通过总收益互换（Total Return Swap）和差价合约（CFD）等衍生品工具，将杠杆率提高至约5-8倍，使其名义敞口达到约500亿至600亿美元。这些衍生品合约由多家主要银行作为交易对手方，包括瑞信、野村、摩根士丹利、高盛、瑞银和德意志银行等。 Archegos利用了监管的灰色地带。作为家族办公室，Archegos免于在美国证券交易委员会（SEC）注册为投资顾问，也无需披露其持仓。通过使用总收益互换而非直接持有股票，Archegos避免了触发SEC的大额持仓披露要求（13F报告），使其巨额头寸在市场上几乎不可见。多家银行同时向Archegos提供杠杆，但彼此之间缺乏信息共享，无法了解Archegos的总杠杆水平。 2021年3月，ViacomCBS宣布增发股票，',
