    title: '2022年英国特拉斯迷你预算危机',
    description: '2022年9月，英国首相特拉斯（Liz Truss）政府推出的"迷你预算"方案引发了英国金融市场的历史性动荡，英镑暴跌、国债收益率飙升、养老金体系濒临崩溃，最终导致特拉斯在执政仅45天后辞职，成为英国历史上任期最短的首相。 2022年9月23日，特拉斯政府的财政大臣夸西·克沃滕（Kwasi Kwarteng）宣布了总额约450亿英镑的减税计划，这是自1972年以来最大规模的减税方案。方案包括取消4',
    context: '5%的最高所得税税率、将基本所得税率从20%降至19%、取消银行家奖金上限、取消计划中的企业税上调等。然而，这些减税措施没有相应的支出削减来融资，预计将使政府债务增加约600亿英镑。 市场反应极为负面。英镑对美元汇率在9月26日跌至1.0350的历史新低，接近与美元平价。英国10年期国债收益率从9月22日的3.6%飙升至9月27日的4.5%，30年期国债收益率从3.8%飙升至5.0%，涨幅创历史纪录。英国国债遭遇了前所未有的抛售，收益率在短短几天内的涨幅相当于正常年份数年的波动。 最危险的连锁反应发生在养老金领域。英国定义收益型养老金广泛采用"负债驱动投资"（LDI）策略，通过利率互换和通胀互换等衍生品对冲利率和通胀风险。当国债收益率飙升时，这些互换合约产生了巨额追加保证金要求，养老金被迫出售国债来筹集现金，形成了"收益率上升—追加保证金—抛售国债—收益率进一步上升"的死亡螺旋。英格兰银行',
