    difficulty: 5,
    title: '2023年硅谷银行倒闭引发银行危机',
    description: '2023年3月10日，硅谷银行（Silicon Valley Bank，SVB）被美国联邦存款保险公司（FDIC）接管，成为2008年华盛顿互惠银行倒闭以来美国最大的银行破产案。SVB的倒闭迅速引发连锁反应，签名银行和第一共和银行相继倒闭，瑞士信贷被迫被瑞银收购，全球银行业面临自2008年以来最严峻的信心危机。 SVB倒闭的直接原因是利率风险管理的严重失败。2020年至2021年疫情期间，SVB吸',
    context: '收了大量科技初创企业的存款，存款从2019年底的约610亿美元激增至2022年3月的约1980亿美元。SVB将这些存款投资于长期美国国债和抵押贷款支持证券（MBS），以获取微薄的利差。然而，当美联储从2022年3月开始激进加息时，这些长期债券的市场价值大幅下跌。截至2022年底，SVB持有的可供出售证券（AFS）和持有到期证券（HTM）的未实现亏损分别达到25亿美元和152亿美元。 2023年3月8日，SVB宣布出售约210亿美元的亏损证券组合（亏损约18亿美元），并计划通过增发股票和发行可转换优先股筹集22.5亿美元。这一消息引发了储户的恐慌性挤兑。3月9日，储户发起了约420亿美元的提款请求，占SVB存款总额的约24%。3月10日，SVB因流动性不足被FDIC接管。 社交媒体和数字银行加速了挤兑的传播速度。风险投资公司和初创企业社群在Twitter和WhatsApp上迅速传播恐慌情绪，',
