    id: 'case_23',
    category: '金融史',
    difficulty: 3,
    title: '2006年新兴市场震荡',
    description: '2006年5月至6月，全球新兴市场经历了一次显著的震荡，股市和货币在数周内大幅下跌。这次震荡的触发因素看似微不足道——市场对全球利率上升的担忧——但其背后反映了新兴市场对全球流动性环境的深度依赖。 2006年上半年，全球主要央行开始收紧货币政策。美联储已将联邦基金利率从2004年的1%提高至2006年6月的5.25%，欧洲央行也开始加息，日本央行结束了超宽松的量化宽松政策。全球流动性的收紧使投资者',
    context: '重新评估新兴市场的风险溢价，资本开始从新兴市场回流发达市场。 5月中旬，新兴市场遭遇了集中抛售。MSCI新兴市场指数在5月8日至6月13日期间下跌超过20%。土耳其、巴西、印度等此前表现最好的市场跌幅最大。土耳其伊斯坦布尔100指数下跌超过25%，巴西博维斯帕指数下跌超过15%，印度Sensex指数下跌超过20%。新兴市场货币也普遍贬值，南非兰特、匈牙利福林、土耳其里拉等跌幅居前。 冰岛在此次震荡中成为焦点。冰岛克朗在2006年前几个月大幅贬值，评级机构下调了冰岛的主权展望，市场对冰岛银行体系过度扩张的担忧加剧。冰岛的情况被视为新兴市场脆弱性的极端案例——尽管冰岛是发达国家，但其银行体系的杠杆率和对外部融资的依赖使其表现出新兴市场式的脆弱性。 2006年新兴市场震荡虽然持续时间不长，但它预示了此后更大规模的危机。它表明，全球流动性环境是新兴市场表现的关键驱动因素，而此前的强劲表现部分建立在',
