    id: 'case_25',
    category: '金融史',
    difficulty: 3,
    title: '2019年美国国债收益率倒挂',
    description: '2019年8月14日，美国10年期国债收益率跌破2年期国债收益率，出现了自2007年以来首次显著的收益率曲线倒挂。这一事件引发了市场的广泛关注和担忧，因为收益率曲线倒挂在历史上是经济衰退的可靠先行指标——过去50年中，每次经济衰退前都出现了收益率曲线倒挂。 收益率曲线倒挂意味着短期利率高于长期利率，这看似违反直觉——通常情况下，长期投资需要更高的收益率补偿时间风险。倒挂的出现通常反映了两个因素：一',
    context: '是美联储加息使短期利率上升，二是市场对未来经济增长的悲观预期推动长期利率下降。 2019年的倒挂有其特殊背景。美联储在2015年至2018年间进行了9次加息，将联邦基金利率从0-0.25%提高至2.25-2.50%。同时，全球经济增长放缓、贸易摩擦升级（中美贸易战）、地缘政治不确定性上升，推动投资者涌向美国国债等避险资产，压低了长期收益率。10年期国债收益率从2018年11月的约3.25%降至2019年8月的约1.6%，降幅超过160个基点。 收益率曲线倒挂引发了市场的恐慌性反应。8月14日当天，道琼斯指数下跌超过800点，跌幅约3%。金融股遭受重创，因为银行的传统盈利模式——借短贷长——在收益率曲线倒挂时受到严重挤压。市场对经济衰退的担忧急剧升温，联邦基金期货价格显示市场预期美联储将在2019年底前再降息约100个基点。 美联储在2019年进行了三次"保险性降息"，将利率从2.25-2.',
