    title: '2008年华盛顿互惠银行倒闭',
    description: '2008年9月25日，华盛顿互惠银行（Washington Mutual，WaMu）被美国储蓄机构监理局（OTS）关闭，并由FDIC接管后立即出售给摩根大通。WaMu以约3070亿美元的总资产成为美国历史上最大的银行破产案，这一纪录直到2023年才被硅谷银行打破。 WaMu的倒闭是次贷危机中银行业失败的典型代表。作为美国最大的储蓄贷款协会，WaMu在2000年代初期大举进入次级贷款市场。2003年',
    context: '至2007年间，WaMu通过其子公司长滩抵押贷款公司（Long Beach Mortgage）大量发放次级贷款和Alt-A贷款（介于优质和次级之间的贷款类别）。这些贷款的标准极为宽松——低文件甚至无文件贷款、可调利率、高贷款价值比（LTV）——在房价上涨时看似安全，但一旦房价下跌，违约率急剧上升。 WaMu的风险管理存在严重缺陷。内部审计多次警告次贷组合的质量问题，但管理层为追求短期利润而忽视了这些警告。2005年，WaMu的内部风险评估团队发现其期权ARM贷款（允许借款人选择低于应还利息的月供，差额计入本金）的违约率远高于预期，但公司仍继续大力推广此类产品。到2007年底，WaMu持有的约630亿美元住宅抵押贷款中，约530亿美元为次级和Alt-A贷款。 2008年9月，WaMu经历了大规模的存款挤兑。在9月15日雷曼兄弟倒闭后的10天内，储户从WaMu提取了约167亿美元存款，占存款总',
