    difficulty: 3,
    title: '2008年英国北岩银行国有化',
    description: '2007年9月，英国北岩银行（Northern Rock）遭遇了150年来英国首次银行挤兑，储户在银行门外排起长队提取存款。这一场景震惊了全球，成为次贷危机从美国蔓延至欧洲的标志性事件。北岩银行最终于2008年2月被国有化，成为英国自1984年以来首家被国有化的银行。 北岩银行的商业模式高度依赖批发融资和证券化。传统银行通过吸收存款来发放贷款，但北岩银行将约75%的资金来源依赖于批发市场（即同业拆',
    context: '借和资产证券化），远高于英国银行业的平均水平。它大量发放住宅抵押贷款，然后将这些贷款打包成MBS出售给投资者，用回笼的资金继续放贷。这种"发放—分销"模式在市场流动性充裕时运作良好，但当全球信贷市场冻结时，北岩银行无法再融资其短期债务。 2007年8月，次贷危机导致全球银行间市场流动性枯竭，北岩银行无法在批发市场获得融资。9月13日，BBC报道北岩银行已向英格兰银行申请紧急流动性支持，这一消息引发了储户的恐慌性挤兑。9月14日至15日，约20亿英镑的存款被提取，约占北岩银行零售存款的8%。排队取款的场景在电视上反复播放，进一步加剧了恐慌。 英格兰银行最初不愿提供紧急援助，担心会创造道德风险。但在挤兑持续升级的情况下，9月17日，英国财政大臣达林宣布政府将为北岩银行的所有零售存款提供全额担保，才最终止住了挤兑。此后，北岩银行多次寻求私人买家，但均未成功。2008年2月，英国政府宣布将北岩银行',
