    id: 'case_30',
    category: '并购',
    difficulty: 3,
    title: '2023年瑞士信贷被瑞银收购',
    description: '2023年3月19日，在瑞士政府的斡旋下，瑞银集团（UBS）以约30亿瑞士法郎的价格收购了陷入危机的瑞士信贷（Credit Suisse），这一交易在周末紧急达成，旨在避免瑞士信贷无序倒闭引发的全球金融动荡。此次收购是自2008年金融危机以来欧洲银行业最重要的救助行动。 瑞士信贷的困境并非一朝一夕形成，而是多年管理失误和风险控制失败的累积结果。2021年，Archegos爆仓事件使瑞信损失约55亿',
    context: '美元，Greensill供应链金融基金的倒闭又使其面临声誉和财务双重打击。2022年，瑞信报告了约73亿瑞郎的净亏损，客户大量撤资，存款外流超过1000亿瑞郎。2023年2月，瑞信报告了全年亏损约73亿瑞郎，并承认存在内部控制的"重大缺陷"。 2023年3月，硅谷银行倒闭引发的银行业恐慌蔓延至欧洲。3月15日，沙特国家银行董事长在接受采访时表示"绝对不会"向瑞信提供更多资本支持，这一言论引发了市场恐慌。瑞信股价当日暴跌约30%，信用违约互换利差飙升至危机水平，流动性急剧恶化。 3月16日，瑞士国家银行（SNB）和瑞士金融市场监管局（FINMA）发表联合声明，表示将在必要时向瑞信提供流动性支持。3月17日，SNB向瑞信提供了最高500亿瑞郎的紧急流动性援助。然而，市场信心未能恢复，存款外流加速。 3月18日至19日周末，在瑞士政府、SNB和FINMA的紧急协调下，瑞银同意收购瑞信。为促成交易',
