    description: '2010年，爱尔兰最大的银行之一盎格鲁爱尔兰银行（Anglo Irish Bank）因房地产贷款的巨额损失而崩溃，迫使爱尔兰政府投入约293亿欧元进行救助，这一金额占爱尔兰GDP的约18%，使爱尔兰自身陷入主权债务危机。 盎格鲁爱尔兰银行的问题源于其对房地产开发商的过度放贷。在2000年代爱尔兰房地产泡沫期间，盎格鲁爱尔兰银行大量向房地产开发商提供贷款，其贷款组合中约70%与商业地产相关。银行与开',
    context: '发商之间关系密切，贷款审批标准极为宽松，大量贷款缺乏充分的抵押和信用评估。2008年，该银行向10名最大借款人提供了约5亿欧元的贷款，集中度风险极高。 2008年12月，盎格鲁爱尔兰银行的丑闻进一步曝光。董事长肖恩·菲茨帕特里克被发现将个人从银行获得的约1.22亿欧元贷款暂时转移到其他银行，以在财年报告中隐瞒其真实借款规模。CEO大卫·德拉姆也承认接受了不当贷款。两人被迫辞职，但损害已经造成。 爱尔兰政府分多轮对盎格鲁爱尔兰银行进行了救助。2008年12月，政府宣布向银行体系提供约100亿欧元的资本支持，其中大部分流向盎格鲁爱尔兰银行。2009年1月，政府将盎格鲁爱尔兰银行国有化。此后，救助成本不断攀升，从最初的约40亿欧元增至最终的约293亿欧元。 盎格鲁爱尔兰银行的救助成本之所以如此巨大，部分原因在于爱尔兰政府的决策失误。2008年9月，爱尔兰政府宣布为所有银行的负债（包括存款、债券和',
