    difficulty: 3,
    title: '2012年西班牙Bankia银行救助',
    description: '2012年，西班牙第四大银行Bankia因房地产不良贷款的巨额损失而崩溃，成为西班牙银行业危机的标志性事件。西班牙政府投入约224亿欧元救助Bankia，这一救助最终迫使西班牙向欧盟申请约410亿欧元的银行救助资金。 Bankia的困境源于其特殊的组建方式和房地产贷款的过度集中。Bankia于2010年由七家地区性储蓄银行（Cajas）合并而成，这些储蓄银行在2000年代西班牙房地产泡沫期间大量发',
    context: '放房地产贷款。合并的目的是通过规模效应和资产多元化来增强稳定性，但实际上只是将问题集中到了一起。截至2011年底，Bankia的贷款组合中约60%与房地产相关，不良贷款率超过10%。 2012年5月，Bankia新任董事长何塞·伊格纳西奥·戈里戈萨里披露，银行需要约47亿欧元的资本补充，远超此前的估计。仅仅几天后，这一数字被修正为约190亿欧元，是西班牙银行救助基金（FROB）可用资金的两倍多。更令人震惊的是，Bankia在2011年报告了约3亿欧元的净利润，但重新审计后改为约30亿欧元的净亏损，会计处理的差异之大引发了欺诈调查。 2012年5月，西班牙政府将Bankia国有化，并注入了约47亿欧元的资本。6月，政府宣布将向欧盟申请约1000亿欧元的银行救助资金（最终使用了约410亿欧元）。7月，Bankia的救助方案正式确定，政府注入约224亿欧元，成为欧洲银行业历史上最大规模的单体银行',
