    id: 'case_34',
    category: '银行',
    difficulty: 3,
    title: '2014年葡萄牙圣灵银行倒闭',
    description: '2014年8月，葡萄牙最大的上市银行圣灵银行（Banco Espírito Santo，BES）因母公司圣灵集团（ESG）的财务欺诈和巨额亏损而崩溃，被葡萄牙央行拆分为"好银行"和"坏银行"。这是欧元区在单一监管机制启动前夕面临的一次重大银行危机考验。 圣灵集团是葡萄牙最大的家族企业集团之一，业务涵盖银行、保险、医疗、农业和能源等领域。然而，集团的财务状况长期存在严重问题。2013年底，ESG被发',
    context: '现存在会计违规行为，包括通过关联交易虚增资产和隐瞒负债。2014年，ESG及其子公司陆续违约，最终在7月申请破产保护。 BES作为集团的核心金融机构，与母公司之间存在大量关联交易。BES持有大量ESG及其子公司的商业票据和债券，这些投资在ESG破产后变得一文不值。2014年7月，BES披露上半年亏损约36亿欧元，远超其资本基础。葡萄牙央行认定BES已不具备偿付能力，于8月3日决定将其拆分。 拆分方案将BES分为两部分："好银行"Novo Banco接收了BES的优质资产、存款和大部分业务，由葡萄牙银行处置基金出资49亿欧元注资；"坏银行"保留了与ESG相关的问题资产和次级债务，面临清算。约20亿欧元的次级债券和部分优先债券被留在"坏银行"中，投资者遭受了重大损失。 然而，Novo Banco的处置过程此后出现了争议。2015年12月，葡萄牙央行决定将部分原本属于Novo Banco的优先债',
