    id: 'case_35',
    category: '银行',
    difficulty: 3,
    title: '2017年西班牙人民银行倒闭',
    description: '2017年6月7日，西班牙第六大银行人民银行（Banco Popular Español）被欧洲单一监管机制（SSM）认定"显著恶化或可能违反许可条件"，随后被欧洲单一处置机制（SRM）启动处置程序，以1欧元的名义价格出售给桑坦德银行。这是欧元区银行处置新框架下的首次实践。 人民银行的困境源于其房地产贷款组合的持续恶化。在2008年西班牙房地产泡沫破裂后，人民银行积累了大量不良房地产贷款。尽管其他',
    context: '西班牙银行在2012年至2016年间逐步清理了不良资产，人民银行的清理进度严重滞后。截至2016年底，其不良贷款率仍高达约17%，远高于西班牙银行业的平均水平。银行的资本充足率持续下降，市场信心不断恶化。 2017年初，人民银行的状况急剧恶化。存款开始外流，银行间融资渠道收窄，股价从年初的约2.5欧元跌至6月初的不足0.5欧元。66日，人民银行股价在盘中暴跌超过30%，市场担心银行无法继续经营。欧洲央行银行监管委员会在6月6日认定人民银行"显著恶化"，触发了处置程序。 6月7日凌晨，欧洲单一处置委员会（SRB）决定将人民银行出售给桑坦德银行。桑坦德以1欧元的象征性价格收购了人民银行的所有股份和业务，同时承担了其所有负债。SRB没有动用单一处置基金，也没有对储户和普通债权人实施减记，而是通过"出售"工具完成了处置。股东和次级债券持有人承担了全部损失。 桑坦德随后对人民银行进行了大规模重组，注',
