    description: '2023年3月12日，即硅谷银行倒闭仅两天后，纽约州金融服务局（DFS）关闭了签名银行（Signature Bank），并任命FDIC为接管人。签名银行以约1180亿美元的总资产成为美国历史上第三大银行破产案。与硅谷银行类似，签名银行的倒闭也源于存款挤兑，但其业务模式有独特的特征。 签名银行成立于2001年，以服务中小企业和高端个人客户为特色。然而，使其与众不同的是对加密货币行业的积极拥抱。截至2',
    context: '022年底，签名银行的存款总额约为886亿美元，其中约170亿美元（约19%）来自加密货币相关客户。签名银行是少数几家愿意为加密货币公司提供银行服务的美国银行之一，这使其在加密行业繁荣期间获得了大量存款流入。 签名银行的资产端同样存在问题。与SVB类似，签名银行将大量存款投资于长期固定利率证券，在美联储加息后遭受了严重的未实现亏损。截至2022年底，签名银行持有约260亿美元的持有到期证券，未实现亏损约17亿美元。此外，签名银行的商业地产贷款组合也面临压力，特别是纽约市的写字楼贷款。 3月10日SVB倒闭后，签名银行立即面临存款挤兑。3月10日当天，储户提取了约20%的存款。加密货币行业的客户尤其紧张——此前加密货币友好银行Silvergate Bank已在3月8日宣布自愿清算，签名银行是仅存的少数选择之一。3月11日，挤兑持续加剧。 3月12日，纽约州DFS认定签名银行已无法安全经营，将',
