    description: '2023年5月1日，第一共和银行（First Republic Bank）被FDIC接管并出售给摩根大通，以约2290亿美元的总资产成为美国历史上最大的银行破产案，超过了2008年华盛顿互惠银行的纪录。第一共和银行的倒闭是2023年春季美国银行业危机的最后一幕，也是最具争议的一幕。 第一共和银行成立于1985年，以服务高净值客户为特色，提供优惠的抵押贷款利率和高端的私人银行服务。这种商业模式在低利',
    context: '率环境下运作良好——银行以低成本吸收富裕客户的存款，以略低于市场的利率发放大额抵押贷款，同时通过交叉销售财富管理服务获利。然而，这种模式对利率高度敏感。 当美联储从2022年开始激进加息时，第一共和银行面临双重打击。一方面，其持有的固定利率抵押贷款和证券的市场价值大幅下降，未实现亏损估计超过400亿美元。另一方面，富裕客户对利率最为敏感——当货币市场基金收益率超过4%时，第一共和银行支付接近0%利率的存款变得毫无吸引力，存款大量外流。 2023年3月SVB倒闭后，第一共和银行也遭遇了挤兑。3月份，存款外流超过1000亿美元，约占存款总额的40%。3月16日，以摩根大通为首的11家大型银行联合向第一共和银行存入300亿美元，试图稳定局势。然而，这一"团结展示"只是暂时缓解了压力，并未解决根本问题。 第一共和银行在4月24日公布的一季度财报显示，存款流失约1020亿美元（不包括11家大行的30',
