    description: '2008年秋，比利时-荷兰金融集团富通集团（Fortis）在次贷危机和收购荷兰银行后的流动性危机中崩溃，被比利时、荷兰和卢森堡三国政府拆分救助。富通集团的解体是2008年欧洲金融危机中最引人注目的事件之一，也是跨境金融机构处置的复杂案例。 富通集团原是比利时-荷兰-卢森堡经济联盟（Benelux）地区最大的金融机构之一，业务涵盖银行、保险和资产管理。2007年10月，富通与苏格兰皇家银行和桑坦德银',
