    title: '2015年希腊银行体系重组',
    description: '2015年，希腊银行体系在经历了五年的经济衰退和两轮债务重组后，再次面临全面崩溃的风险。2015年7月，希腊政府实施资本管制、银行关门三周，银行体系被迫进行第三次资本重组，成为欧债危机中最严重的银行危机之一。 希腊银行体系的问题与主权债务危机深度交织。希腊银行持有大量本国政府债券，2012年希腊主权债务重组时，私人部门债权人被迫接受了约53.5%的名义减记，希腊银行因此损失约380亿欧元，资本基础',
    context: '遭到严重侵蚀。此后，希腊经济持续衰退（2009年至2015年GDP萎缩超过25%），企业破产和家庭违约激增，银行不良贷款率飙升至超过40%。 2015年上半年，希腊与国际债权人的谈判陷入僵局。6月底，希腊政府宣布就债权人方案举行全民公投，引发市场恐慌。6月28日，希腊政府实施资本管制，限制银行提款和跨境转账。银行从6月29日至7月20日关闭三周，每人每日提款限额为60欧元。这是欧元区首次有国家实施全面的资本管制。 银行关门期间，希腊经济几乎瘫痪。企业无法支付工资和供应商，进口贸易中断，药品和燃料供应出现短缺。7月5日公投中，61%的选民拒绝了债权人的方案，但政府最终仍接受了更为严厉的条件，以换取第三轮救助。 2015年底至2016年初，希腊四大银行（希腊国家银行、比雷埃夫斯银行、阿尔法银行和欧元银行）进行了第三次资本重组。欧洲银行业管理局（EBA）的压力测试显示，希腊银行在不利情景下需要约',
