    title: '2024年纽约社区银行危机',
    description: '2024年初，纽约社区银行（New York Community Bancorp，NYCB）因商业地产贷款的巨额亏损和分红削减而陷入危机，股价暴跌超过60%，信用评级被降至垃圾级，引发了对美国商业地产贷款风险的广泛担忧。 NYCB的危机与其2023年收购签名银行的资产密切相关。2023年3月签名银行倒闭后，NYCB收购了签名银行约380亿美元的资产，包括约130亿美元的贷款。这一收购使NYCB的资',
    context: '产规模超过1000亿美元，超过了1000亿美元的监管门槛，意味着NYCB被归类为第四类银行，需要遵守更严格的资本和流动性要求。 更根本的问题在于NYCB的商业地产贷款敞口。截至2023年底，NYCB的商业地产贷款组合约占总贷款的约46%，其中大量为纽约市租金管制公寓贷款和写字楼贷款。在远程办公趋势和利率上升的双重压力下，写字楼贷款的违约风险急剧上升。2024年1月31日，NYCB报告了2.6亿美元的季度净亏损（而此前市场预期为盈利），并将分红从每股17美分削减至5美分，同时计提了5.52亿美元的贷款损失准备金。 消息公布后，NYCB股价在2月份暴跌超过60%，信用违约互换利差飙升。2月6日，穆迪将NYCB的信用评级降至垃圾级。市场恐慌蔓延至其他商业地产敞口较大的区域性银行，引发了对2023年银行业危机重演的担忧。 3月初，NYCB宣布获得超过10亿美元的股权投资，由前美国财政部长史蒂文·姆',
