    description: '2008年至2009年，荷兰最大的金融机构之一ING集团接受了荷兰政府约100亿欧元的救助，并被迫进行大规模的业务重组。ING的救助是荷兰政府在金融危机中最大规模的银行救助行动之一。 ING的困境源于其银行和保险混合经营模式的风险暴露。作为全球性的金融集团，ING在2000年代大举扩张国际业务，特别是在美国的在线银行业务（ING Direct）和欧洲的房地产贷款领域。ING Direct在美国吸收',
    context: '了大量存款并投资于抵押贷款支持证券，当次贷市场崩溃时，这些投资遭受了严重损失。2008年第三季度，ING报告了约5亿欧元的净亏损，并预计将进一步减记约20亿欧元。 2008年10月，荷兰政府向ING注入了100亿欧元的核心资本，获得了优先股和认股权证。作为条件，ING被要求加强风险管理、限制高管薪酬和分红。2009年1月，ING又获得了荷兰政府对其约277亿美元美国MBS组合的担保，ING承担最初的损失，政府承担超出部分的90%。 2009年，欧盟委员会认定ING接受的政府援助构成国家补贴，要求ING进行重组以恢复市场竞争的公平性。作为条件，ING被迫进行大规模的业务剥离：出售ING Direct美国业务（后出售给Capital One）、出售ING Direct英国业务、出售ING Direct加拿大业务、出售亚洲保险和资产管理业务，以及将银行和保险业务拆分为两家独立公司。 ING的重组',
