    id: 'case_42',
    category: '银行',
    difficulty: 3,
    title: '2012年德克夏银行救助',
    description: '2011年至2012年，法比合资银行德克夏银行（Dexia）因流动性危机和巨额亏损被迫进行第二次政府救助，成为欧债危机中首批倒下的欧洲银行之一。德克夏的救助凸显了地方政府融资银行在金融危机中的特殊脆弱性。 德克夏银行最初于1996年由法国和比利时的公共部门银行合并而成，核心业务是为法国和比利时的地方政府提供融资服务。这一业务模式在正常时期风险较低——地方政府违约概率极低，且德克夏享有隐性的政府支持',
    context: '。然而，2000年代，德克夏大举进入国际资本市场，通过发行短期债券融资并投资于美国MBS等高风险资产，严重偏离了其核心业务。 2008年金融危机期间，德克夏因持有大量美国MBS而遭受损失，比利时、法国和卢森堡三国政府联合提供了约60亿欧元的资本注入，并为德克夏提供了最高1500亿欧元的债务担保。德克夏被要求大幅缩减资产负债表，退出高风险业务。 然而，德克夏的重组并不彻底。2011年，随着欧债危机加剧，德克夏的融资成本上升，短期债务难以展期。德克夏持有大量希腊、意大利和葡萄牙政府债券，这些债券的市场价值因主权风险上升而大幅下跌。2011年10月，德克夏的董事会承认银行已无法获得市场融资，被迫再次寻求政府救助。 第二次救助方案包括：比利时政府以40亿欧元收购德克夏在比利时的零售银行业务并将其国有化（后成为Belfius银行）；法国和比利时政府继续为德克夏的剩余债务提供担保；德克夏的"残余实体"',
