    title: '2014年黑海银行倒闭潮',
    description: '2014年至2015年，受克里米亚危机和东部冲突影响，乌克兰银行业经历了严重的倒闭潮。超过50家银行被监管机构关闭，约占银行总数的三分之一，存款担保基金支出了大量资金用于储户赔付。这是独立以来乌克兰最严重的银行危机。 乌克兰银行体系在危机前存在严重的结构性问题。许多银行由寡头控制，大量发放关联贷款，将银行作为自身企业的"提款机"。银行治理薄弱，风险管理几乎形同虚设。同时，大量银行持有政府债券，而乌',
    context: '克兰的主权信用在2013年至2014年急剧恶化。2014年初的政治危机——亚努科维奇政府倒台、克里米亚被吞并、东部冲突爆发——使经济陷入深度衰退，GDP在2014年萎缩约7%，2015年继续萎缩约10%。 乌克兰国家银行（NBU）在新行长甘达列娃的领导下实施了激进的银行清理政策。2014年至2015年间，NBU关闭了约50家资不抵债的银行，包括一些大型银行如Delta Bank（乌克兰第三大银行）和Finance and Credit Bank。NBU还引入了更严格的资本要求和关联贷款限制，并推动银行提高透明度。 2015年底至2016年，乌克兰对最大的三家国有银行—— PrivatBank、Oschadbank和Ukreximbank——进行了重组。其中最具争议的是2016年12月将乌克兰最大银行PrivatBank国有化。PrivatBank由寡头科洛莫伊斯基和博戈柳博夫控制，NBU认',
