    id: 'case_44',
    category: '金融史',
    difficulty: 3,
    title: '2008年美国国际集团（AIG）救助',
    description: '2008年9月16日，美联储向美国国际集团（AIG）提供了850亿美元的紧急贷款，以避免这家全球最大保险公司的倒闭引发系统性灾难。AIG救助是2008年金融危机中规模最大的单一机构救助行动之一，最终政府投入的救助资金超过1800亿美元。 AIG的困境源于其金融产品部门（AIG Financial Products，AIGFP）大量出售信用违约互换（CDS）担保的超高级CDO份额。AIGFP总部位于',
    context: '伦敦，由约400名员工组成，通过出售CDS保护为AIG赚取了巨额保费收入。截至2007年底，AIGFP出售的CDS保护名义金额超过5000亿美元，其中约780亿美元与次级贷款支持的CDO相关。 AIG的商业模式存在致命缺陷。AIGFP出售CDS保护时，假设被保护的CDO份额（超高级份额）几乎不可能遭受损失，因此无需预留足够的资本或抵押品。然而，当次贷市场崩溃时，这些CDO份额的价值急剧下降，AIG被要求追加大量抵押品。2008年前三个季度，AIG报告了约250亿美元的亏损，信用评级被下调，触发了更多追加保证金要求。 2008年9月15日雷曼兄弟倒闭后，AIG的处境急剧恶化。9月15日，AIG被要求追加约145亿美元的抵押品，但已无力支付。三大信用评级机构在9月15日晚间下调了AIG的评级，进一步触发了约200亿美元的追加保证金要求。AIG在9月16日上午告知政府，如果无法获得紧急援助，将在',
