    id: 'case_47',
    category: '欺诈',
    difficulty: 4,
    title: '2002年世通公司财务丑闻',
    description: '2002年6月，美国第二大长途电话公司世通公司（WorldCom）承认通过会计造假虚增了约38亿美元的利润，随后申请破产保护，以约1070亿美元的资产创下当时美国最大的企业破产纪录。世通丑闻与安然事件一起，成为推动美国公司治理改革的最重要催化剂。 世通由伯尼·埃伯斯通过一系列并购打造而成。1983年至1999年间，世通完成了超过65次收购，从一家小型长途电话运营商成长为电信巨头。1998年，世通以',
    context: '约370亿美元收购MCI通信公司，成为当时最大的并购交易之一。然而，随着电信行业在2000年后进入衰退，世通的增长停滞，收入下降，埃伯斯面临着维持盈利增长的巨大压力。 世通的造假手段相对简单但规模巨大。CFO斯科特·苏利文指示将本应计入费用的线路成本（即世通向其他电信公司支付的网络使用费）资本化为长期资产，从而虚增利润。从2001年初至2002年第一季度，世通通过这一手段虚增了约38亿美元的利润。此外，世通还通过虚增收入和不当计提准备金等手段操纵财务报表。 2002年3月，世通内部审计师辛西娅·库珀在例行审计中发现了线路成本资本化的异常。尽管面临管理层的阻挠和威胁，库珀坚持深入调查，最终揭露了整个造假规模。6月25日，世通宣布解雇苏利文，并承认虚增了约38亿美元的利润。7月21日，世通申请破产保护。 世通丑闻的后续影响深远。埃伯斯被判处25年监禁（2014年在服刑期间去世），苏利文被判处5',
