    difficulty: 3,
    title: '2003年帕玛拉特财务造假',
    description: '2003年12月，意大利乳业巨头帕玛拉特（Parmalat）曝出约145亿欧元的财务造假丑闻，被称为"欧洲的安然"。帕玛拉特创始人卡利斯托·坦齐承认挪用了约5亿欧元的公司资金，而公司声称在开曼群岛银行账户中持有的约40亿欧元存款实际上根本不存在。 帕玛拉特成立于1961年，从意大利帕尔马地区的一家小型乳制品厂发展成为全球性的食品集团，业务遍及30多个国家，拥有约3.6万名员工。帕玛拉特的成功部分归',
    context: '功于其开发的超高温灭菌（UHT）牛奶技术，使牛奶可以在常温下保存数月。 然而，帕玛拉特的财务状况远不如其表面光鲜。坦齐将公司作为个人提款机，大量挪用公司资金投资于亏损的旅游和足球业务（帕尔马足球俱乐部）。为掩盖资金缺口，帕玛拉特通过复杂的关联交易和虚假文件伪造银行存款。最令人震惊的是，帕玛拉特声称其在开曼群岛的Bank of America账户中持有约39.5亿欧元的存款，而实际上该账户是空的——银行对账单是伪造的。 造假手段还包括通过衍生品交易和关联方交易虚增收入和资产。帕玛拉特利用其设在开曼群岛的子公司Bonlat Financing发行虚假的商业票据和债券，并通过与关联方的循环交易制造虚假收入。审计师德勤和均富（Grant Thornton）未能发现这些造假，均富的意大利合伙人后来被指控参与伪造文件。 2003年12月19日，帕玛拉特无法偿还一笔约1.5亿欧元的到期债券，引发市场质疑',
