    id: 'case_49',
    category: '金融史',
    difficulty: 3,
    title: '2008年麦道夫庞氏骗局',
    description: '2008年12月11日，前纳斯达克主席伯纳德·麦道夫因运营史上最大的庞氏骗局被逮捕。麦道夫的骗局持续了至少20年，涉及金额约650亿美元，受害者包括全球各地的富豪、慈善机构、对冲基金和银行。这一丑闻在2008年金融危机最严重的时刻曝光，进一步打击了市场信心。 麦道夫的骗局运作方式极为简单但极为有效。他承诺稳定且高于市场的回报——每月约1%至2%，年化约10%至12%——且几乎从不出现亏损月份。这种',
    context: '"过于完美"的业绩记录本应引起警觉，但麦道夫利用其纳斯达克主席的声望和华尔街"内圈"的地位，吸引了大量精英投资者。 麦道夫采用"排他性"营销策略，只接受被邀请的投资者，营造出一种稀缺感和特权感。许多犹太慈善机构和犹太社区组织是麦道夫的重要客户来源，麦道夫利用族裔信任网络扩大了骗局的规模。对冲基金"基金的基金"（Feeder Funds）也将大量资金投入麦道夫，从中赚取管理费，而未对麦道夫进行充分的尽职调查。 事实上，麦道夫从未进行过任何真实的投资交易。他用新投资者的资金支付老投资者的"回报"，典型的庞氏骗局模式。他声称使用"分裂转换"（Split-strike Conversion）策略——一种涉及股票和期权的复杂交易策略——但从未有人能独立验证其交易。2005年，分析师哈里·马科波洛斯向SEC提交了详细的举报信，指出麦道夫的回报在数学上不可能实现，但SEC未能采取有效行动。 2008年金',
