    id: 'case_50',
    category: '金融史',
    difficulty: 3,
    title: '2011年奥林巴斯财务造假',
    description: '2011年10月，日本精密仪器巨头奥林巴斯（Olympus）被揭露在过去20年间通过虚假并购和咨询费隐瞒了约1178亿日元（约15亿美元）的投资损失。这一丑闻是日本历史上最大的企业财务造假案之一，也因一位外籍CEO的坚持揭露而备受国际关注。 奥林巴斯的造假始于1990年代。当时，奥林巴斯的财务投资部门在泡沫经济破裂后遭受了巨额投资损失。为避免在财务报表中确认这些损失，管理层采用了"损失推迟"（To',
    context: 'bashi）手法——通过将亏损资产转移至表外基金，然后用高估值的资产替换，使账面看起来没有亏损。这种做法需要不断用新的虚假交易来掩盖旧的亏损，形成了滚雪球式的造假。 2000年代，奥林巴斯通过一系列海外并购来消化这些隐藏的损失。最引人注目的是2008年以约21亿美元收购英国医疗设备公司Gyrus，其中约6.87亿美元被支付给两家不知名的财务顾问公司（AXES和AXAM）作为咨询费——这笔咨询费相当于收购价格的约33%，远超正常水平。此外，奥林巴斯还以高价收购了三家日本公司（News Chef、Humalabo和Altis），随后又以极低价格出售，差价被用于填补投资损失。 2011年4月，英国籍CEO迈克尔·伍德福德被任命为奥林巴斯总裁兼CEO，成为少数领导日本大型企业的外国人。伍德福德在审阅公司财务报表后，对Gyrus收购中的天价咨询费提出质疑，并要求内部调查。10月14日，奥林巴斯董事会',
