    difficulty: 4,
    title: '2016年富国银行虚假账户丑闻',
    description: '2016年9月，美国消费者金融保护局（CFPB）、货币监理署（OCC）和洛杉矶市检察官办公室联合对富国银行处以1.85亿美元的罚款，原因是该银行员工在未经客户授权的情况下开设了约200万个虚假银行账户和信用卡账户。这一丑闻严重损害了富国银行"道德标杆"的声誉，并引发了对其企业文化和激励制度的深刻反思。 虚假账户丑闻的根源在于富国银行极度激进的交叉销售策略。富国银行以"Gr-8"（Great Eig',
    context: 'ht）交叉销售目标著称——即平均每位客户使用8个富国银行产品。管理层将这一目标分解为员工个人的销售配额，并与薪酬和晋升直接挂钩。在巨大的业绩压力下，员工被迫采取各种手段完成配额，包括未经客户同意开设账户、伪造客户签名、将客户资金从已有账户转移到新账户以制造活跃交易的假象。 这些行为给客户造成了实际损害。许多客户因不知情的账户被收取了透支费、年费和滞纳金，信用记录也受到了负面影响。一些客户因不知情的信用卡申请被拒绝贷款，而另一些客户则在发现虚假账户后花费大量时间和精力与银行交涉。 丑闻的曝光源于《洛杉矶时报》2013年的一篇调查报道，揭示了富国银行员工因销售压力而采取的不当行为。然而，富国银行管理层长期否认存在系统性问题，将其归咎于少数"不良员工"。2016年，监管机构的调查发现，富国银行在2011年至2015年间解雇了约5300名与虚假账户相关的员工，但管理层并未改变导致问题的激励制度。 ',
