    title: '2019年Wirecard财务造假',
    description: '2020年6月，德国支付处理公司Wirecard承认其资产负债表上约19亿欧元的现金余额"可能不存在"，随后申请破产。Wirecard曾是德国金融科技的明星企业，市值一度超过240亿欧元，被纳入德国DAX指数。其倒闭是德国自二战以来最大的企业欺诈案，也严重损害了德国金融监管的声誉。 Wirecard成立于1999年，最初是一家处理在线赌博和成人网站支付的公司。在CEO马库斯·布劳恩的领导下，Wir',
    context: 'ecard转型为全球性的支付处理服务商，声称在亚太地区通过第三方合作伙伴处理大量支付业务。2018年，Wirecard取代德国商业银行被纳入DAX蓝筹指数，成为德国30家最重要上市公司之一。 然而，Wirecard的财务数据长期存在疑点。2015年起，多家做空机构（包括Zatarra Research和Viceroy Research）发布报告质疑Wirecard的亚洲业务收入真实性，指出其第三方合作伙伴可能是关联方，收入可能被虚增。《金融时报》也进行了系列调查报道，揭露了Wirecard在新加坡、菲律宾等地的可疑会计操作。 面对质疑，德国监管机构的反应令人震惊。2019年2月，德国联邦金融监管局（BaFin）不仅没有调查Wirecard，反而以"市场操纵"为由禁止了做空Wirecard股票的行为——这在欧盟是极为罕见的举措。BaFin还对《金融时报》记者提起刑事控告，指控其与做空者合谋操',
