    description: '2020年4月2日，在纳斯达克上市仅13个月的中国咖啡连锁企业瑞幸咖啡（Luckin Coffee）宣布，其COO刘剑及部分员工伪造了约22亿元人民币的交易额。这一消息使瑞幸咖啡股价在盘前交易中暴跌超过80%，从约26美元跌至不足5美元，最终被纳斯达克摘牌。 瑞幸咖啡成立于2017年，以"挑战星巴克"的姿态迅速扩张。2019年5月，瑞幸在纳斯达克上市，创下了从成立到IPO最快的中概股纪录。IPO时',
    context: '，瑞幸声称其门店数量已超过星巴克中国，并预测将在2021年实现盈利。然而，瑞幸的商业模式一直备受质疑——其大幅补贴策略（首杯免费、1.8折优惠券）导致每杯咖啡的实际售价远低于成本，持续亏损。 2020年1月，做空机构浑水公司（Muddy Waters）发布了一份89页的做空报告，由匿名作者撰写。报告基于对瑞幸620家门店的11260小时视频监控和7500张小票的收集分析，指控瑞幸大幅虚增了门店日销杯量和客单价。报告估计，瑞幸将日销杯量虚增了约69%，将客单价虚增了约75%。 瑞幸最初否认了所有指控，但4月2日的公告证实了造假的存在。调查发现，瑞幸通过虚构大宗商品交易和虚增门店销售两种方式造假。COO刘剑及其团队通过关联公司虚构了咖啡豆等原材料的采购交易，同时虚增了门店的日销杯量和收入。伪造的交易额涉及约22亿元人民币，约占瑞幸2019年第二至第四季度报告收入的约40%。 丑闻曝光后，瑞幸咖',
