    difficulty: 4,
    title: '2022年FTX加密货币交易所欺诈',
    description: '2022年11月11日，全球第二大加密货币交易所FTX申请破产保护，创始人萨姆·班克曼-弗里德（SBF）被指控犯有电信欺诈、证券欺诈和洗钱等多项罪名。FTX的倒闭涉及约80亿美元的客户资金缺口，是加密货币行业历史上最大的欺诈案。 FTX成立于2019年，迅速成为加密货币交易领域的领军企业。SBF以其"有效利他主义"理念、蓬松的头发和随意的穿着风格成为加密行业的标志性人物。FTX获得了红杉资本、软银',
    context: '、淡马锡等顶级机构的投资，估值在2022年初达到320亿美元。SBF还通过大规模政治捐款和慈善捐赠建立了广泛的影响力。 然而，FTX与其关联交易做市商Alameda Research之间存在严重利益冲突。Alameda由SBF于2017年创立，是FTX的最大做市商。FTX允许Alameda享受特殊待遇，包括超大的交易额度和负余额豁免。更严重的是，FTX将客户资金借给Alameda用于高风险投资和贷款。Alameda的资产负债表显示，其约146亿美元的资产中，约58亿美元为FTX发行的FTT代币——这是一种由FTX自己创造、几乎无内在价值的代币。 2022年11月2日，CoinDesk披露了Alameda的资产负债表细节，引发了市场对FTX流动性的担忧。116日，币安CEO赵长鹏宣布将出售币安持有的约23亿美元FTT代币，触发了FTT价格的暴跌和FTX的挤兑。118日，FTX暂停了客户提款。',
