    id: 'case_57',
    category: '金融史',
    difficulty: 3,
    title: '2005年瑞富公司破产',
    description: '2005年10月，全球最大的非上市衍生品经纪商瑞富公司（Refco）在IPO后仅两个月即宣布CEO菲利普·本内特隐瞒了约4.3亿美元的债务，随后申请破产保护。瑞富的崩溃是华尔街历史上最迅速的IPO后倒闭案例之一，也暴露了审计师和承销商在尽职调查方面的严重疏漏。 瑞富成立于1969年，是全球最大的期货和衍生品经纪商之一，在14个国家设有办事处，管理约40亿美元的客户资产。2005年8月，瑞富以约3.',
    context: '52亿美元的价格在纽约证券交易所上市，IPO由高盛、瑞士信贷第一波士顿和美银证券联合承销。 然而，就在IPO前夕，本内特通过关联公司Refco Group Holdings Inc.（RGHI）向瑞富借入了约4.3亿美元，用于偿还瑞富对第三方的债务。在每个季度末，本内特将这笔债务从瑞富的账簿上暂时转移，使财务报表看起来健康，然后在季度结束后再将债务转回。这种"窗口粉饰"手法使瑞富的财务状况远不如报表所示。 2005年10月10日，瑞富宣布本内特已向公司偿还了4.3亿美元的隐瞒债务，本内特被解职。10月17日，瑞富申请破产保护。从IPO到破产仅用了58天。 瑞富的审计师德勤被指控未能发现本内特的隐瞒债务行为。德勤辩称，本内特的欺诈涉及精心设计的关联方交易，超出了正常审计程序的范围。然而，批评者指出，德勤本应更仔细地审查瑞富与RGHI之间的关联交易，特别是季度末的大额资金流动。 瑞富的承销商也',
