    id: 'case_58',
    category: '金融史',
    difficulty: 3,
    title: '2009年斯坦福金融集团庞氏骗局',
    description: '2009年2月，美国德克萨斯州金融家艾伦·斯坦福被SEC指控运营约70亿美元的庞氏骗局，主要通过其旗下的斯坦福国际银行（Stanford International Bank，SIB）销售高利率存款证（CD）来吸引投资者。斯坦福骗局是继麦道夫之后美国第二大庞氏骗局。 斯坦福的骗局以安提瓜为基地，通过SIB向全球投资者销售存款证，承诺远高于市场水平的利率。SIB声称其高回报来源于"独特的投资策略"，',
    context: '包括投资于全球股票、债券和另类资产。然而，实际上SIB将大部分投资者资金投入了流动性差、价值可疑的资产，包括房地产、私募股权和斯坦福个人的其他业务。 斯坦福利用其"板球赞助商"的身份提升公信力。他斥资约2000万美元赞助了英格兰西印度群岛板球锦标赛（Stanford 20/20），并与英格兰和威尔士板球委员会签署了价值约1亿美元的赞助协议。这些高调的体育赞助使斯坦福获得了社会声望和媒体曝光，帮助他吸引了更多投资者。 SEC在2006年就对SIB进行了调查，但未能采取有效行动。2009年2月，在麦道夫丑闻的压力下，SEC终于对斯坦福提起了民事诉讼，指控其欺诈。2月17日，FBI在弗吉尼亚州找到了斯坦福并送达了法律文书。 斯坦福骗局的受害者遍布全球，特别是拉丁美洲国家。在委内瑞拉、哥伦比亚和厄瓜多尔，大量中产阶级家庭将毕生积蓄投入SIB的存款证，血本无归。安提瓜政府也因SIB的倒闭而遭受了严重',
