    title: '2015年巴西石油公司腐败案',
    description: '2014年至2015年，巴西石油公司（Petrobras）曝出了被称为"洗车行动"（Operação Lava Jato）的大规模腐败丑闻。调查发现，Petrobras高管与建筑承包商之间存在系统性的回扣 scheme，涉及金额超过20亿美元，成为巴西历史上最大的腐败案。 "洗车行动"始于2014年3月，最初调查的是巴西利亚一家洗车店的洗钱活动，但很快扩展到Petrobras的腐败网络。调查发现，',
    context: 'Petrobras的供应链和工程合同中存在系统性的回扣机制：建筑承包商在竞标Petrobras合同时，必须向执政党（劳工党）和Petrobras高管支付约3%的合同金额作为回扣。这些回扣通过离岸公司和虚假咨询合同进行洗钱。 涉及的主要建筑承包商包括Odebrecht、OAS、Camargo Corrêa和Andrade Gutierrez等巴西最大的建筑集团。Odebrecht的腐败规模尤为惊人——该公司建立了一个专门的"结构化运营部"（Departamento de Operações Estruturadas），系统性地向12个国家的官员行贿，涉及金额约7.88亿美元。 Petrobras的腐败造成了巨大的经济损失。公司被迫计提了约170亿雷亚尔（约50亿美元）的资产减值，股价从2013年的约22雷亚尔跌至2015年的约6雷亚尔，市值蒸发超过1000亿美元。Petrobras的信用评级',
