    id: 'case_61',
    category: '金融史',
    difficulty: 3,
    title: '2023年印度阿达尼集团做空事件',
    description: '2023年1月24日，美国做空机构兴登堡研究公司（Hindenburg Research）发布了一份约100页的做空报告，指控印度阿达尼集团（Adani Group）实施了"企业史上最大规模的骗局"，涉及股票操纵和会计欺诈。报告发布后，阿达尼集团旗下公司的市值在数周内蒸发超过1400亿美元，引发了全球对印度企业治理的关注。 阿达尼集团由印度富豪高塔姆·阿达尼创立，业务涵盖港口、电力、煤炭、水泥、机',
    context: '场和绿色能源等领域。阿达尼与印度总理莫迪关系密切，被批评者视为"莫迪的寡头"。2020年至2022年间，阿达尼的财富增长了超过1000亿美元，成为全球第三大富豪，阿达尼集团旗下上市公司的估值也大幅飙升。 兴登堡报告的核心指控包括：阿达尼集团通过离岸实体操纵旗下公司股价，这些离岸实体由阿达尼的兄弟维诺德·阿达尼控制；阿达尼集团的财务状况远比报表所示更为脆弱，债务负担沉重；阿达尼旗下多家上市公司的估值严重脱离基本面，某些公司的市盈率超过800倍。 报告还指控阿达尼集团利用离岸实体规避印度证券法关于最低公众持股比例的要求。印度法律要求上市公司至少25%的股份由公众持有，兴登堡认为阿达尼通过离岸实体持有大量股份，使实际公众持股比例远低于法定要求。 报告发布后，阿达尼集团旗下10家上市公司的股价暴跌。旗舰公司阿达尼企业（Adani Enterprises）的股价在1月27日单日下跌约26%。阿达尼个',
