    difficulty: 3,
    title: '2014年阿尔斯通贿赂案',
    description: '2014年12月，法国工业巨头阿尔斯通（Alstom）同意向美国司法部支付7.72亿美元罚款，了结其在全球多国行贿的指控。这是当时美国《反海外腐败法》（FCPA）历史上最大的刑事罚款之一。此案还因法国高管弗雷德里克·皮耶鲁奇的遭遇而广为人知——他被美国逮捕并监禁数年，其经历被写成了《美国陷阱》一书。 美国司法部指控阿尔斯通在2000年至2011年间，通过贿赂政府官员获得了约40亿美元的合同，涉及印',
    context: '度尼西亚、埃及、沙特阿拉伯、巴哈马和台湾等国家和地区。贿赂通常通过中间人和咨询公司进行，阿尔斯通将贿赂款项伪装成"咨询费"支付给中间人，再由中间人转交给目标国家的官员。 调查始于2008年，当时阿尔斯通的一名前雇员向美国司法部提供了线索。2010年，阿尔斯通副总裁皮耶鲁奇在纽约出差时被FBI逮捕，被指控与印度尼西亚塔拉罕发电站项目的贿赂有关。皮耶鲁奇被拒绝保释，在监狱中等待审判超过两年。美国检察官使用"辩诉交易"制度向皮耶鲁奇施压——如果他认罪，可以获释；如果坚持无罪，可能面临15至20年的监禁。皮耶鲁奇最终认罪，被判处30个月监禁。 皮耶鲁奇在《美国陷阱》中声称，美国司法部对阿尔斯通的调查实际上是为其竞争对手通用电气（GE）收购阿尔斯通能源业务铺路。2014年，GE以约124亿欧元收购了阿尔斯通的电力和电网业务，这一交易在皮耶鲁奇被捕后加速推进。皮耶鲁奇认为，美国利用FCPA作为经济战的',
