    title: '2017年巴西肉企JBS贿赂案',
    description: '2017年5月，全球最大肉类加工企业JBS的控股股东韦斯利·巴蒂斯塔和若德利戈·巴蒂斯塔兄弟与巴西检方达成认罪协议，承认向超过1900名政客行贿，涉及金额约1.5亿美元。JBS贿赂案是"洗车行动"调查的延伸，也是巴西政治腐败的又一重大丑闻。 JBS由巴蒂斯塔家族控制，是全球最大的牛肉和禽肉加工企业，业务遍及美国、澳大利亚和欧洲。巴蒂斯塔兄弟承认，他们通过JBS的控股公司J&F Investimen',
    context: 'tos向政客行贿，以获取政府补贴的廉价贷款（来自巴西国家开发银行BNDES）、获得环境许可和避免监管处罚。 最引人注目的行贿对象包括时任总统特梅尔。巴蒂斯塔兄弟提供了特梅尔收取贿赂的录音证据，导致特梅尔面临刑事指控（后被法院驳回）。他们还承认向2010年和2014年总统竞选提供了非法捐款，涉及前总统罗塞夫和卢拉的竞选团队。 作为认罪协议的一部分，J&F Investimentos同意支付103亿雷亚尔（约33亿美元）的罚款，这是巴西历史上最大的企业罚款。韦斯利和若德利戈·巴蒂斯塔分别被判处近13年和9年监禁，但后来减刑并转为居家监禁。 JBS贿赂案的影响超出了巴西。在美国，JBS的美国子公司JBS USA因涉嫌违反FCPA而面临美国司法部和SEC的调查。2024年，JBS同意向美国司法部支付约2.58亿美元以了结FCPA调查。 JBS案例的教训在于，国有企业（特别是开发银行）的廉价贷款如果',
