    category: '欺诈',
    difficulty: 4,
    title: '2024年恒大会计丑闻',
    description: '2024年3月，中国证监会查明恒大地产集团在2019年至2020年间通过提前确认收入等方式虚增收入约5641亿元人民币，虚增利润约920亿元，构成中国资本市场历史上规模最大的财务造假案。恒大创始人许家印被罚款4700万元人民币并终身禁入证券市场。 恒大集团曾是中国最大的房地产开发商，2020年销售额超过7000亿元。然而，恒大长期依赖高杠杆、高周转的商业模式，通过预售制度提前收取购房款，再用这些资',
    context: '金投资新项目，形成了庞大的债务链条。到2021年，恒大总负债超过2.4万亿元人民币，最终在2021年9月爆发债务危机。 恒大的财务造假手段主要包括：通过提前确认房地产销售收入虚增收入和利润。根据中国会计准则，房地产销售收入应在房屋交付后确认，但恒大在房屋尚未完工甚至尚未开工的情况下就确认了收入。此外，恒大还通过关联交易和虚假交易虚增收入，以及通过少计提减值准备虚增利润。 恒大的审计师德勤被指控在2019年和2020年的审计中存在严重失职。中国财政部对德勤处以2.12亿元人民币的罚款，并暂停其北京分所的审计业务3个月。这是中国对审计机构处以的最大罚款之一。 恒大事件的影响远超资本市场。数百万购房者因恒大项目停工而面临"烂尾楼"风险，大量供应商和承包商无法收回货款，理财产品投资者无法兑付。中国政府为稳定房地产市场，推出了"保交楼"政策，确保已售出的住房能够完工交付。 2024年1月，香港高等法',
