    category: '欺诈',
    difficulty: 4,
    title: '2004年AIG会计丑闻',
    description: '2004年至2005年，美国国际集团（AIG）曝出会计丑闻，被指控通过虚假再保险交易虚增约5亿美元的准备金。这一丑闻导致AIG支付了16亿美元的和解金，"保险业传奇"CEO莫里斯·格林伯格被迫辞职，AIG的声誉遭受了严重损害。 AIG的会计丑闻核心涉及与通用再保险（General Reinsurance，巴菲特的伯克希尔·哈撒韦旗下公司）之间的一笔再保险交易。2000年底，AIG的损失准备金低于分',
    context: '析师预期，格林伯格联系巴菲特，请求通用再保险与AIG进行一笔再保险交易以增加准备金。双方达成了一笔约5亿美元的再保险合同，但这笔交易缺乏实质性的风险转移——AIG实际上并未将风险转移给通用再保险，而是通过交易结构的设计使AIG能够虚增约5亿美元的损失准备金。 根据美国会计准则，再保险合同只有在发生实质性风险转移时才能确认再保险收入。由于这笔交易缺乏风险转移，AIG不应确认相关收入。SEC和纽约州总检察长斯皮策对AIG提起了调查。 2005年3月，AIG承认了会计违规，并同意重新编制此前五年的财务报表。格林伯格在3月被董事会免去CEO职务，4月又辞去了董事长职务。格林伯格在AIG工作了近40年，将AIG从一家小保险公司打造为全球最大的保险集团，他的离职标志着AIG一个时代的结束。 2006年，AIG与SEC和纽约州总检察长办公室达成和解，支付了16亿美元的罚款和和解金。AIG还同意实施一系列',
