    id: 'case_67',
    category: '危机',
    difficulty: 5,
    title: '2008年冰岛主权违约危机',
    description: '2008年10月，冰岛这个仅有32万人口的北欧岛国经历了人类历史上最严重的银行倒闭事件之一，三大银行——Glitnir、Landsbanki和Kaupthing在短短数日内相继崩溃，导致冰岛货币克朗暴跌、股市归零、国家濒临主权违约。这场危机的规模与冰岛的经济体量形成了令人震惊的对比：三大银行的资产规模在危机前达到冰岛GDP的近10倍，约1400亿欧元，而冰岛的GDP仅约130亿欧元。 冰岛银行体系',
    context: '的膨胀始于2000年代初的金融自由化。政府放松了对银行的监管，允许它们在国际市场上大量借入外币资金，然后投资于高风险资产。三大银行在英国、荷兰等欧洲国家积极吸收存款，Landsbanki旗下的Icesave账户尤其活跃，吸引了数十万英国和荷兰储户的资金。银行利用这些资金大量购买海外资产，包括房地产、对冲基金份额和复杂金融产品，杠杆率极高。 2008年9月雷曼兄弟倒闭后，全球信贷市场冻结，冰岛银行无法再获得短期融资。9月29日，政府被迫接管Glitnir银行；10月6日，Landsbanki被接管；10月9日，Kaupthing也宣告破产。冰岛克朗在一周内对欧元贬值超过50%，股市暂停交易后重新开盘时暴跌77%。冰岛成为自1976年以来第一个向IMF求援的西欧国家，获得了21亿美元的紧急贷款。 Icesave存款纠纷成为危机后最棘手的问题。英国和荷兰政府为补偿本国储户损失，向冰岛提供约39亿',
