    title: '2010年爱尔兰债务危机',
    description: '2010年11月，爱尔兰在希腊之后成为第二个向欧盟和IMF求援的欧元区国家，接受了850亿欧元的救助方案。与希腊不同，爱尔兰在危机前被誉为"凯尔特之虎"，是欧洲经济增长的明星，其危机根源不在于财政挥霍，而在于房地产泡沫和银行体系的失控。爱尔兰的案例证明，即使财政状况良好的国家，如果放任银行体系过度扩张和房地产泡沫膨胀，也可能陷入严重的主权债务危机。 爱尔兰危机的核心在于其银行体系对房地产市场的过度',
