    id: 'case_70',
    category: '危机',
    difficulty: 5,
    title: '2011年葡萄牙债务危机',
    description: '2011年4月，葡萄牙成为欧元区第三个寻求国际救助的国家，接受了780亿欧元的援助方案。葡萄牙的危机虽然不如希腊那样戏剧性，但同样揭示了欧元区边缘国家在货币联盟中面临的结构性困境。与希腊的财政造假和爱尔兰的房地产泡沫不同，葡萄牙的问题更多源于长期的经济停滞、竞争力下降和私人部门过度负债，是"温水煮青蛙"式的缓慢积累。 葡萄牙在加入欧元区后经历了短暂的繁荣，但很快暴露出竞争力不足的问题。低利率环境刺',
    context: '激了信贷扩张，但资金主要流向了非贸易部门——房地产和消费，而非生产性投资。葡萄牙的储蓄率持续下降，外债不断攀升，经常账户长期逆差。2000年至2010年间，葡萄牙的GDP年均增长率仅为0.6%，在欧元区排名垫底。公共部门效率低下，司法体系迟缓，劳动力市场僵化，教育和创新投入不足，这些结构性问题严重制约了经济增长潜力。 2010年希腊危机爆发后，市场开始重新评估欧元区边缘国家的风险。葡萄牙的国债收益率持续攀升，2011年初10年期国债收益率突破7%的"不可持续"水平。2月，总理苏格拉底政府提出的第四套紧缩方案在议会遭否决，政府被迫辞职，提前举行大选。6月，社会民主党领导人科埃略当选总理，新政府接受了救助方案并承诺实施更严格的紧缩措施。 救助方案要求葡萄牙在2014年前将财政赤字占GDP的比例降至3%以下，实施结构性改革包括劳动力市场灵活化、国有企业私有化、公共行政改革等。葡萄牙的调整过程虽然',
