    title: '2012年西班牙银行业危机',
    description: '2012年6月，西班牙向欧盟申请了最高1000亿欧元的银行业救助资金，成为欧元区第四个寻求援助的国家。西班牙的危机具有独特性——在危机爆发前，西班牙的政府债务水平相对较低，财政状况在欧元区属于中等偏上，但其银行体系因房地产泡沫破裂而遭受重创，最终迫使政府出手救助，导致主权信用受损。西班牙案例的核心教训是：银行体系的健康与否直接关系到主权信用，而地方储蓄银行（Cajas）的治理缺陷是危机的重要根源。',
    context: ' 西班牙的房地产泡沫在2000年代初期至中期急剧膨胀。加入欧元区后，西班牙享受了历史最低的利率水平，信贷大规模扩张。2000年至2007年间，西班牙新建住宅数量超过德国、法国和英国的总和，房价累计上涨约200%。银行，尤其是地方储蓄银行（Cajas），大量向房地产开发商提供贷款。Cajas的治理结构存在严重缺陷——董事会由地方政府和社区代表组成，缺乏专业性和独立性，容易受到政治干预，风险管理形同虚设。 2008年全球金融危机后，西班牙房地产市场急剧降温，大量新建住宅无人问津，开发商纷纷破产。银行的不良贷款率从2007年的不到1%飙升至2012年的超过10%，部分Cajas的不良贷款率甚至超过20%。2010年至2012年，政府被迫多次对银行体系进行重组和注资，合并了多家Cajas，但市场信心持续恶化。2012年7月，西班牙10年期国债收益率突破7.5%，融资成本达到不可持续的水平。 欧盟的',
