    description: '2011年至2012年，意大利这个欧元区第三大经济体陷入了严重的主权债务危机，国债收益率飙升，市场一度担心意大利可能寻求救助，而意大利的经济体量之大使得现有的救助机制根本无力应对。意大利的危机虽然最终没有演变为全面违约，但暴露了欧元区最大的系统性风险——一个债务规模超过2万亿欧元的国家如果倒下，将可能拖垮整个欧元区。 意大利的债务问题具有长期性。自1980年代以来，意大利的公共债务占GDP的比例就',
