    title: '2014年乌克兰债务危机',
    description: '2014年至2015年，乌克兰陷入了严重的主权债务危机，其根源既有长期的经济治理问题，也有地缘政治冲突的急剧恶化。乌克兰的危机是经济脆弱性与政治危机交织的典型案例，展示了地缘政治风险如何迅速转化为金融灾难。2013年底，乌克兰总统亚努科维奇在俄罗斯压力下拒绝签署与欧盟的联系国协定，引发了基辅独立广场（Maidan）的大规模抗议，最终导致亚努科维奇出逃俄罗斯、亲西方政府上台。 政治剧变迅速引发了经济',
    context: '和金融连锁反应。首先，俄罗斯对乌克兰实施经济制裁，贸易大幅萎缩。其次，克里米亚被俄罗斯吞并，东部顿巴斯地区爆发武装冲突，工业产出急剧下降。第三，乌克兰外汇储备从2013年的约200亿美元骤降至2014年底的不足70亿美元，仅够支付约两个月的进口。格里夫纳对美元汇率从2013年的约8:1贬值至2015年初的约30:1，通胀率飙升至超过40%。 2014年4月，IMF批准了对乌克兰170亿美元的扩展基金设施（EFF）救助方案，总援助规模（包括其他国际机构）约270亿美元。救助条件包括：实施浮动汇率制度、大幅提高能源价格（减少补贴）、改革国有企业（特别是能源部门Naftogaz）、改善税收征管、整顿银行体系。2015年，乌克兰对约150亿美元的外债进行了重组，包括要求俄罗斯持有的30亿美元欧元债券接受减记，引发了法律纠纷。 乌克兰的银行体系在危机中遭受重创。2014年至2016年间，超过70家银',
