    id: 'case_74',
    category: '债务',
    difficulty: 4,
    title: '2015年波多黎各债务违约',
    description: '2015年8月，美国领地波多黎各对其公共金融公司（PFC）的5800万美元债券违约，这是波多黎各债务危机的正式开端。此后，波多黎各陆续对超过700亿美元的债务违约，成为美国历史上最大的地方政府破产案。波多黎各的危机是长期经济衰退、人口流失、财政管理不善和特殊政治地位共同作用的结果，其债务规模远超底特律2013年约180亿美元的破产记录。 波多黎各危机的根源可以追溯到2006年，当时一项联邦税收优惠',
    context: '（第936条）到期，导致大量制药和制造业企业撤离，经济开始持续衰退。从2006年到2015年，波多黎各的GDP萎缩了约15%，就业人口减少了近20%。人口大量外流，特别是年轻受过教育的劳动力迁往美国本土，导致税基不断萎缩。同时，政府维持了庞大的公共部门，养老金体系严重负债，财政赤字依靠不断举债弥补。 波多黎各的债务结构极其复杂，涉及18种不同类型的债券发行主体，包括一般义务债券、公共建筑债券、电力公司债券、高速公路债券等。由于波多黎各是美国领地而非州，其市政债券不受各州债务限制规则的约束，也缺乏联邦破产法第九章的保护（直到2016年国会通过PROMESA法案才改变）。债券持有人包括大量美国本土的共同基金和对冲基金，后者在危机期间大量折价买入波多黎各债券，试图通过法律手段获得全额偿付。 2016年6月，美国国会通过PROMESA法案，建立了联邦监督委员会（Oversight Board）来管',
