    difficulty: 5,
    title: '2015年希腊二次债务危机与公投',
    description: '2015年7月5日，希腊举行全民公投，以61.3%的压倒性多数否决了国际债权人提出的紧缩方案，这一戏剧性事件将希腊债务危机推向了最高潮。然而，公投结果并未如反紧缩阵营所愿带来更有利的谈判地位，反而在短短一周内，希腊被迫接受了比此前更为苛刻的条件。这一事件是欧元区危机中最具政治戏剧性的篇章，深刻揭示了民主政治与货币联盟规则之间的张力。 2015年1月，激进左翼联盟（Syriza）在选举中获胜，齐普拉',
    context: '斯出任总理，其竞选承诺是结束紧缩、重新谈判救助条件。财政部长瓦鲁法基斯采取了强硬的谈判姿态，要求债务减记和紧缩条件放松。然而，欧元区其他成员国，特别是德国和芬兰，坚决反对任何形式的债务减记，认为这将创造不良先例。谈判陷入僵局，希腊银行存款大量外流，欧洲央行维持对希腊银行的紧急流动性援助（ELA）上限不变，实际上是在施加压力。 6月底，救助协议到期，希腊无法偿还IMF约16亿欧元的贷款，成为第一个对IMF违约的发达国家。齐普拉斯宣布举行公投，让人民决定是否接受债权人的条件。公投期间，银行关闭三周，实施资本管制，每人每日取款限额60欧元。公投的"否决"结果令市场震惊，但齐普拉斯在公投后迅速转向，接受了比此前更严格的救助方案——三年内实施相当于GDP约4%的财政紧缩，改革养老金、增值税和劳动力市场。 瓦鲁法基斯在公投后辞职，他后来透露，政府在公投期间曾准备了退出欧元区的应急方案，包括印制新货币和',
