    description: '2016年至2017年，蒙古这个资源丰富的中亚国家陷入了严重的外债危机，其外债占GDP的比例一度接近200%，外汇储备仅能覆盖不到两个月的进口。蒙古的危机是典型的"资源诅咒"与经济管理不善相结合的产物，也是新兴市场在全球大宗商品价格下跌时脆弱性的缩影。 蒙古的经济高度依赖矿产出口，特别是铜和煤炭。2010年至2012年间，全球大宗商品价格高企，蒙古经济年均增长率超过15%，一度成为全球增长最快的经',
    context: '济体之一。然而，这种繁荣掩盖了严重的结构性问题：政府支出随收入增长而大幅扩张，财政纪律松弛；大量以美元计价的债务被用于非生产性支出；经济多元化进展缓慢。2014年至2016年，大宗商品价格暴跌，铜价从2011年的高点下跌超过50%，蒙古的出口收入锐减，财政状况急剧恶化。 2016年，蒙古图格里克对美元贬值超过20%，央行大幅加息以稳定汇率，但进一步抑制了经济活动。政府债务占GDP的比例从2011年的约40%飙升至2016年的近90%。国际评级机构连续下调蒙古的主权信用评级，融资成本大幅上升。2017年初，蒙古面临约5亿美元的到期债务，而外汇储备不足3亿美元，违约风险迫在眉睫。 2017年2月，蒙古与国际货币基金组织达成55亿美元的救助协议，其中IMF提供4.4亿美元，其余来自亚洲开发银行、世界银行以及中国、日本等双边伙伴。救助条件包括：实施财政紧缩，逐步减少预算赤字；改革税收体系，提高矿业',
