    id: 'case_77',
    category: '债务',
    difficulty: 4,
    title: '2017年委内瑞拉债务违约',
    description: '2017年11月，委内瑞拉及其国有石油公司PDVSA正式宣布债务违约，结束了多年来以"技术性手段"维持偿付的艰难努力。委内瑞拉的违约是经济管理全面失败的终局，也是"石油诅咒"最极端的案例之一——坐拥全球最大已探明石油储量的国家，却无法按时偿还外债，其国民甚至面临食品和药品短缺的生存危机。 委内瑞拉的悲剧始于查韦斯时代的民粹主义经济政策。2000年代石油价格飙升带来了巨额收入，查韦斯政府将这些收入大',
    context: '量用于社会支出和补贴，而非投资于基础设施和经济多元化。政府实施了严格的价格管制和外汇管制，导致生产活动萎缩，进口依赖加剧。PDVSA被当作政府的"提款机"，大量资金被抽走用于社会项目，石油产量从1990年代末的约320万桶/日下降到2015年的约240万桶/日。同时，政府大量举借外债，以石油出口收入作为偿债保障。 2014年石油价格暴跌后，委内瑞拉的偿债能力急剧恶化。政府采取了极端措施维持偿付：削减进口（导致国内严重短缺）、动用外汇储备、向中国和俄罗斯借款（以未来石油交付为抵押）。外汇储备从2009年的约340亿美元降至2017年的不足100亿美元。恶性通胀开始蔓延，2017年通胀率超过4000%，2018年更飙升至约130000%。经济全面崩溃，GDP从2013年到2017年萎缩超过35%，超过200万人逃离该国。 违约后，委内瑞拉的债务重组陷入僵局。马杜罗政府在国际上不被美国等主要国家',
