    id: 'case_79',
    category: '债务',
    difficulty: 4,
    title: '2022年斯里兰卡债务违约',
    description: '2022年4月12日，斯里兰卡宣布对所有外债违约，暂停偿还约510亿美元的外债，成为亚太地区20年来第一个主权违约的国家。斯里兰卡的违约是经济管理失误与民粹主义政策相结合的典型后果，其导火索可以追溯到2019年的恐怖袭击、2020年的新冠疫情以及一系列政策失误，特别是突然禁止化肥进口导致的农业危机。 斯里兰卡危机的核心在于外汇储备的枯竭和债务结构的不可持续。2019年，斯里兰卡的外债约为约350亿',
    context: '美元，外汇储备约76亿美元。拉贾帕克萨政府在2019年实施了大规模减税，使财政收入减少约25%，财政赤字急剧扩大。2021年4月，政府突然宣布禁止化肥和农用化学品进口，推行"有机农业"政策，导致水稻产量下降约40%，茶叶产量大幅下滑，食品价格飙升，农民抗议不断。这一政策在六个月后被撤销，但损害已经造成。 2022年初，斯里兰卡外汇储备降至不足20亿美元，而未来一年到期的外债约70亿美元。政府被迫实施严格的外汇管制，限制进口，导致燃料、药品等必需品严重短缺。每天长达十多小时的停电引发大规模抗议，4月至5月间，抗议者占领了总统官邸，拉贾帕克萨被迫出逃并辞职。斯里兰卡卢比对美元贬值超过80%，通胀率一度超过70%。 IMF于2022年9月提供了29亿美元的扩展基金设施救助，条件包括：实施财政改革，增加税收；恢复财政纪律；重组债务；加强社会保障网；改革国有企业（特别是斯里兰卡航空和锡兰电力公司）。',
