    difficulty: 3,
    title: '2022年赞比亚债务重组',
    description: '2020年11月，赞比亚成为非洲首个在新冠疫情中违约的国家，对其30亿美元的欧洲债券违约。赞比亚的债务危机是非洲国家在"一带一路"融资和商业借款快速扩张后面临困境的缩影，也是G20共同框架（Common Framework）下债务重组的首个测试案例。赞比亚的违约和后续重组过程，揭示了新兴市场债务格局的深刻变化——传统巴黎俱乐部债权国不再是唯一的主要债权人，中国和商业债券持有人的角色日益重要。 赞比',
    context: '亚的债务问题在2010年代急剧恶化。铜价高企时期，赞比亚大量举借外债用于基础设施建设，外债从2011年的约20亿美元飙升至2019年的约120亿美元。中国成为赞比亚最大的单一债权国，持有约30亿美元的双边债务，主要用于公路、机场等基础设施项目。这些项目的经济效益存疑，部分项目成本远高于市场水平。同时，赞比亚还发行了多笔欧洲债券，利率较高。 2019年，赞比亚的债务占GDP的比例已超过90%，债务偿还支出占政府收入的比例超过30%。2020年新冠疫情冲击铜价和财政收入，政府无力偿还到期债务。违约后，赞比亚与债权人的谈判进展缓慢。主要障碍在于：中国作为非巴黎俱乐部成员，对债务透明度和减记方式有不同立场；欧洲债券持有人要求获得与双边债权人同等的待遇；赞比亚国内政治变化（2021年反对党上台）也影响了谈判节奏。 2023年6月，赞比亚终于与官方债权人（包括中国和法国等）达成协议，同意将约63亿美元',
