    title: '2003年日本量化宽松政策',
    description: '2003年，日本银行（BOJ）在行长福井俊彦的领导下，正式实施了量化宽松政策（Quantitative Easing, QE），这是主要央行首次采用这一非常规货币政策工具。日本量化宽松的背景是经济长期陷入通缩困境，传统货币政策已经失效——利率已降至零，但物价仍在下跌，经济停滞不前。日本的开创性实践为2008年后全球主要央行大规模实施QE提供了重要参考。 日本通缩的根源可以追溯到1990年代资产泡沫',
    context: '破裂后的"失去的十年"。1990年代，日本股市和房地产市值蒸发了超过1500万亿日元，银行体系积累了巨额不良贷款，信贷紧缩持续多年。尽管日本银行在1999年就实施了零利率政策，但通缩预期已经根深蒂固，企业不愿投资，消费者推迟消费，形成了"通缩心理"的恶性循环。2001年3月，日本银行在行长速水优任内就开始了初步的量化宽松，主要通过购买长期国债向市场注入流动性，但力度有限。 2003年，日本银行加大了QE力度，将商业银行在央行的准备金余额目标从约5万亿日元逐步提高至约30万亿日元，并承诺在核心CPI稳定在零或以上之前维持这一政策。日本银行还扩大了购买资产的范围，包括长期国债、短期证券和股票ETF。这一政策的核心逻辑是：通过大量购买资产向市场注入基础货币，压低长期利率，改善金融机构的资产负债表，从而刺激信贷和投资。 日本QE的效果存在争议。积极方面，它帮助稳定了金融体系，长期利率被压至极低水平',
