    id: 'case_83',
    category: '金融史',
    difficulty: 3,
    title: '2008年美联储零利率政策',
    description: '2008年12月16日，美联储将联邦基金利率目标区间下调至0-0.25%，这是美联储历史上首次将利率降至接近零的水平，标志着美国货币政策进入了前所未有的"零利率下限"时代。这一决策是在全球金融危机最严峻的时刻做出的——雷曼兄弟已经倒闭，信贷市场冻结，经济自由落体式下滑，传统货币政策工具已经耗尽，美联储不得不转向非常规手段。 2008年的降息速度之快前所未有。1月，联邦基金利率还在4.25%的水平；',
    context: '1月至4月，美联储连续大幅降息；9月雷曼倒闭后，降息步伐进一步加快；10月8日，美联储与欧洲央行、英格兰银行等全球主要央行联合降息，这是历史上首次协调降息行动；12月，利率降至零附近。美联储在声明中表示："经济活动大幅减弱，金融市场仍处于相当大的压力之下，信贷条件对企业和家庭仍然紧张"，并承诺"将利用所有可用工具来促进经济恢复可持续增长和价格稳定"。 零利率政策的实施对金融市场产生了深远影响。短期国债收益率降至接近零，货币市场基金面临"清盘"风险——因为扣除管理费后投资者实际收益为负。美联储不得不设立临时工具支持货币市场基金。银行净息差被压缩，传统银行业务模式受到挑战。同时，零利率推动投资者追求更高收益，资金大量流入高收益债券、新兴市场等风险资产，为未来的金融稳定埋下隐患。 零利率政策持续了整整七年，直到2015年12月美联储才首次加息。这七年间，美国经济经历了缓慢复苏，失业率从2009年',
