    id: 'case_84',
    category: '金融史',
    difficulty: 3,
    title: '2008年全球央行联合降息',
    description: '2008年10月8日，美联储、欧洲央行、英格兰银行、加拿大央行、瑞典央行和瑞士央行同时宣布降息，中国央行和澳大利亚央行也在同日降息，这是人类历史上规模最大的央行协调行动。六家主要央行同时降息50个基点，在金融史上尚属首次，这一前所未有的举措反映了全球金融危机的极端严重性和各国央行对系统性崩溃的深切担忧。 联合降息的背景是2008年9月雷曼兄弟倒闭后全球金融体系的急剧恶化。信贷市场几乎完全冻结，银行',
    context: '间同业拆借市场停摆，TED利差（3个月LIBOR与3个月国债收益率之差）从正常时期的约30个基点飙升至超过460个基点。全球股市在10月第一周暴跌超过20%，新兴市场货币大幅贬值，资本大规模外逃。各国央行意识到，在高度互联的全球金融体系中，单边行动不足以恢复市场信心，必须通过协调行动传递"全球共同应对"的信号。 美联储在声明中表示："由于经济活动减弱和通胀压力缓解，央行采取了协调行动。一些央行近期的政策举措反映了对通胀压力减弱的共同判断。"英格兰银行行长默文·金恩强调："我们面对的是自一战以来最严重的银行危机，需要前所未有的应对。"中国央行同时下调一年期存贷款基准利率27个基点，并下调存款准备金率50个基点，这是中国自2002年以来首次降息。 联合降息的即时市场效果有限——股市在短暂反弹后继续下跌，信贷市场紧张状况并未立即缓解。然而，从更长远的视角看，联合行动具有重要的象征意义和实质效果。',
