    id: 'case_85',
    category: '金融史',
    difficulty: 3,
    title: '2009年美联储量化宽松（QE1）',
    description: '2009年3月18日，美联储宣布将购买最多1.25万亿美元的抵押贷款支持证券（MBS）、2000亿美元的机构债券和3000亿美元的长期国债，标志着第一轮量化宽松（QE1）的全面展开。这是美联储自成立以来最大规模的资产购买计划，标志着央行货币政策从利率工具向资产负债表工具的根本性转变。QE1的核心目标是压低长期利率、稳定住房市场和恢复信贷流动。 QE1的推出背景极为严峻。2008年12月利率已降至零',
    context: '，但金融市场仍在恶化。住房市场持续下跌，MBS市场功能严重受损，房贷利率居高不下，与国债的利差处于历史高位。银行间市场冻结，企业融资困难，经济衰退加深。美联储意识到，仅靠零利率不足以应对危机，必须直接干预特定市场以恢复其功能。2008年11月，伯南克首次宣布了购买MBS和机构债券的计划，2009年3月又大幅扩大了购买规模并加入了国债购买。 QE1的运作机制是通过大规模购买特定资产来压低其收益率，进而影响整个利率体系。美联储购买MBS直接推高了MBS价格、压低了MBS收益率，使房贷利率从2008年底的约5.5%降至2009年底的约4.7%，为住房市场提供了关键支撑。购买长期国债则压低了长期无风险利率，降低了整个经济的融资成本。美联储的资产负债表从2008年8月的约9000亿美元膨胀至2010年6月的约2.3万亿美元。 QE1的效果总体上是积极的。住房市场在2009年中期开始企稳，房价跌幅收窄',
