    description: '2010年11月3日，美联储宣布实施第二轮量化宽松（QE2），将在2011年6月前购买6000亿美元的长期国债，每月购买约750亿美元。同时，美联储将用到期MBS的本金再投资于国债，以维持资产负债表规模。QE2的推出背景是2010年中期美国经济复苏明显放缓，通胀率持续低于美联储目标，通缩风险上升，而利率已经为零，传统货币政策工具已经耗尽。 2010年春夏之交，美国经济数据令人失望。GDP增长率从2',
    context: '009年第四季度的5.4%放缓至2010年第二季度的1.7%，失业率仍高达9.6%。核心通胀率从年初的约1.5%降至1%以下，接近通缩边缘。伯南克在8月杰克逊霍尔年会上暗示将采取进一步行动，引发了市场的广泛预期。11月3日FOMC会议后，QE2正式宣布，规模略高于市场预期的5000亿美元。 QE2的传导机制与QE1有所不同。QE1主要针对功能失调的特定市场（MBS），而QE2主要通过"投资组合再平衡效应"起作用——美联储购买长期国债推低其收益率，迫使投资者转向风险更高的资产（股票、公司债券、新兴市场等），从而降低整体融资成本、推高资产价格、刺激财富效应和投资。QE2宣布后，美国10年期国债收益率反而从约2.5%上升至约3.5%，这被解读为市场对经济前景和通胀预期改善的信号。 QE2在国际上引发了激烈争议。新兴市场国家批评美联储的宽松政策导致大量"热钱"流入，推高其货币汇率和资产价格，输入了',
