    category: '金融史',
    difficulty: 3,
    title: '2011年欧洲央行长期再融资操作（LTRO）',
    description: '2011年12月和2012年2月，欧洲央行连续实施了两轮三年期长期再融资操作（LTRO），向欧元区银行体系注入了超过1万亿欧元的超低成本流动性，这是欧洲央行在欧债危机最严峻时刻采取的标志性干预措施。LTRO的核心目标是缓解银行融资困境、防止信贷紧缩恶化，并通过银行渠道间接支持主权债券市场。 LTRO推出的背景是2011年下半年欧元区银行面临的严重融资危机。随着希腊、爱尔兰、葡萄牙等国主权债务危机蔓',
    context: '延，持有大量这些国家国债的银行遭受损失，市场对银行体系的信心急剧恶化。美国货币市场基金大规模撤出对欧洲银行的融资，银行间同业拆借市场几乎冻结，银行无法获得美元流动性。2011年第四季度，欧元区信贷标准急剧收紧，贷款发放量大幅下降，实体经济面临严重的信贷紧缩威胁。 2011年12月21日，第一轮LTRO向523家银行提供了4890亿欧元的三年期贷款，利率仅为1%，远低于市场融资成本。2012年2月29日，第二轮LTRO向800家银行提供了5295亿欧元的贷款。两轮合计超过1万亿欧元，相当于欧元区GDP的约10%。LTRO的创新之处在于期限长达三年（此前LTRO期限通常为3个月至1年），且抵押品要求大幅放宽，使更多银行能够获得融资。 LTRO的短期效果显著。银行融资压力缓解，同业拆借利率下降，主权债券市场也间接受益——南欧银行利用LTRO的廉价资金大量购买本国国债（所谓的"桑蒂交易"或"利差交',
