    description: '2012年7月26日，欧洲央行行长德拉吉在伦敦的一次投资者会议上发表了改变欧元区命运的一句话："在我们的职权范围内，欧洲央行准备不惜一切代价保卫欧元。相信我，这就够了。"（Within our mandate, the ECB is ready to do whatever it takes to preserve the euro. And believe me, it will be enou',
