    id: 'case_92',
    category: '金融史',
    difficulty: 3,
    title: '2015年欧洲央行量化宽松',
    description: '2015年1月22日，欧洲央行宣布将实施大规模资产购买计划（APP），每月购买600亿欧元的国债和私人部门资产，持续至2016年9月，总规模预计超过1.1万亿欧元。这是欧洲央行在多年犹豫后最终采取的"大炮"级措施，也标志着欧元区加入了美英日等国的QE阵营。欧洲央行QE的推出比美联储晚了整整六年，这一延迟反映了欧元区独特的制度约束和政治分歧。 欧洲央行迟迟未推出QE的原因是多方面的。首先，欧元区缺乏',
    context: '统一的财政政策，QE购买各国国债涉及风险分担问题——如果某国违约，损失由谁承担？德国等北欧国家坚决反对"货币化"政府债务，认为这违反了欧盟条约的"不救助"条款。其次，欧洲央行内部存在严重分歧，德国央行行长魏德曼始终反对QE，认为它削弱了改革动力。第三，法律不确定性——欧洲法院尚未裁定QE是否合法。 2014年下半年，通缩压力加剧，欧元区通胀率降至0.2%，油价暴跌进一步压低通胀预期。德拉吉在2014年9月表示将"扩大资产负债表规模"，但市场认为他行动不够果断。2015年1月的QE决定是在德拉吉强力推动下做出的，理事会以多数票通过（魏德曼等两人投了反对票）。QE的设计采取了"风险共担"与"风险自担"的折中方案：80%的购买按各国央行出资比例分配，风险由各国央行自行承担；20%的购买由欧洲央行承担，实行风险共担。 QE实施后，欧元区金融市场出现了显著变化。国债收益率大幅下降，德国10年期国债收',
