    id: 'case_93',
    category: '金融史',
    difficulty: 3,
    title: '2016年日本负利率政策',
    description: '2016年1月29日，日本银行行长黑田东彦出人意料地宣布实施负利率政策，将对金融机构在央行存放的部分超额准备金适用-0.1%的利率。这一决定以5:4的微弱多数通过，是日本银行在对抗通缩方面采取的又一激进举措。负利率政策的推出令市场震惊，因为黑田此前多次表示不会实施负利率，这一"政策意外"本身就反映了日本通缩问题的顽固性和央行政策空间的日益收窄。 日本负利率政策的背景是2015年下半年以来通胀预期的',
    context: '再度恶化。尽管日本银行自2013年4月起实施了"质化量化宽松"（QQE），基础货币大幅扩张，但核心通胀率在2014年消费税上调效应消退后再次回落，2015年底降至约0.5%，远低于2%的目标。油价下跌进一步压低了通胀预期。黑田认为，必须采取额外措施来防止通缩预期重新根深蒂固，打破"通缩心理"的恶性循环。 日本银行的负利率采用了"三层体系"设计：第一层是"基本余额"（Basic Balance），即金融机构现有的超额准备金，适用0%利率；第二层是"宏观附加余额"（Macro Add-on)，即按一定比例新增的准备金，适用0%利率；第三层是超出前两层的"政策利率余额"，适用-0.1%利率。这一设计的目的是减轻负利率对银行盈利的冲击，避免银行将负利率成本转嫁给储户。 负利率政策的效果令人失望。日元在政策宣布后不贬反升——市场将负利率解读为日本银行政策工具耗尽的信号，反而增加了对日本经济前景的担忧',
