    id: 'case_94',
    category: '金融史',
    difficulty: 3,
    title: '2016年日本收益率曲线控制',
    description: '2016年9月21日，日本银行宣布实施"收益率曲线控制"（Yield Curve Control, YCC）政策，将10年期日本国债（JGB）收益率目标设为"0%左右"，同时承诺在必要时无限量购买国债以实现这一目标。YCC取代了此前以基础货币增长为目标的QQE框架，标志着日本银行货币政策操作理念的重大转变——从控制"量"（基础货币）转向控制"价"（利率曲线）。 YCC推出的直接原因是此前负利率政策',
    context: '的负面效果。2016年1月实施负利率后，日本国债收益率曲线整体下移并趋于平坦，10年期JGB收益率降至-0.3%。收益率曲线过度平坦对银行经营造成严重困难——银行传统的"借短贷长"模式依赖于收益率曲线的正斜率，曲线平坦意味着长期贷款与短期存款之间的利差缩小，侵蚀银行利润。银行股大幅下跌，市场对负利率政策的批评日益增多。黑田东彦承认，负利率对金融中介功能产生了"超出预期的副作用"。 YCC的核心设计是将10年期JGB收益率锚定在0%附近，同时将短期利率维持在-0.1%。这一框架意味着日本银行不再追求固定的基础货币增长目标（此前为每年80万亿日元），而是根据市场情况灵活调整购买量。理论上，如果10年期收益率偏离0%目标，日本银行将无限量购买或出售国债来维持目标。在实际操作中，由于日本银行已经持有约45%的JGB存量，市场参与者很少挑战央行的目标，因此日本银行实际需要的购买量远低于此前QQE时期',
