    id: 'case_95',
    category: '金融史',
    difficulty: 3,
    title: '2019年美联储回购市场干预',
    description: '2019年9月17日，美国隔夜回购利率从正常的2%左右突然飙升至10%，创下了自2008年金融危机以来的最高水平。面对货币市场的剧烈动荡，美联储紧急介入，通过隔夜回购操作向市场注入流动性，随后重启了定期回购操作和国债购买计划。这一事件暴露了后QE时代美国货币市场的结构性脆弱性，也迫使美联储重新审视其流动性管理框架。 回购利率飙升的直接原因是银行体系准备金不足。在QE期间，美联储通过资产购买向银行体',
    context: '系注入了大量准备金，峰值时超过2.8万亿美元。然而，2017年至2019年的量化紧缩（QT）使准备金逐步减少，到2019年9月已降至约1.4万亿美元。9月16日，企业季度缴税导致约830亿美元从银行体系流向财政部，同时785亿美元的国债拍卖结算需要付款，两重因素叠加使准备金骤然紧张。银行不愿在回购市场出借资金，导致利率飙升。 美联储的应对迅速而果断。9月17日，纽约联储进行了750亿美元的隔夜回购操作；此后，每日回购操作成为常态，规模逐步扩大。10月11日，美联储宣布将每月购买约600亿美元的短期国债，至少持续到2020年第二季度，以增加银行体系的准备金。美联储强调这不是QE——购买的是短期国债而非长期国债，目的是改善准备金供给而非压低长期利率。然而，市场仍将其解读为事实上的QE，股市在消息公布后上涨。 2019年回购危机暴露了美联储流动性管理框架的几个关键问题。首先，美联储对"充足准备金',
