    title: '2020年美联储无限量QE',
    description: '2020年3月23日，美联储宣布将实施"不限量"的资产购买计划，购买"支持市场平稳运行所需的"国债和抵押贷款支持证券，同时推出了一系列紧急信贷工具支持企业、地方政府和消费者。这是美联储在新冠疫情冲击下采取的最激进措施，其规模和速度远超2008年金融危机时期的应对，标志着央行干预进入了新纪元——从"不惜一切代价"的口头承诺升级为"不限量"的实际行动。 无限量QE的背景是新冠疫情引发的全球金融市场恐慌',
    context: '。2020年2月下旬至3月，全球股市暴跌，美国标普500指数在33天内下跌34%，创下史上最快熊市纪录。国债市场也出现异常——10年期国债收益率在3月9日降至0.54%的历史低位后，因投资者抛售一切资产换取现金，收益率反而反弹至1.18%。公司债券市场冻结，高收益债券利差飙升至超过1000个基点。商业票据市场停摆，货币市场基金面临赎回压力。 美联储的应对速度和力度前所未有。3月3日和3月15日，美联储两次紧急降息共150个基点至0-0.25%；3月15日宣布7000亿美元的资产购买计划；3月17日重启商业票据融资工具（CPFF）；3月18日推出货币市场共同基金流动性工具（MMLF）；3月23日宣布无限量QE，并首次推出企业信用工具（PMCCF和SMCCF），直接购买公司债券（包括高收益债券ETF）；3月31日推出临时回购工具（FIMA），允许外国央行用美国国债换取美元。4月至5月，又推出了',
