    id: 'case_97',
    category: '金融史',
    difficulty: 3,
    title: '2021年美联储通胀\'暂时性\'误判',
    description: '2021年，美联储做出了一个代价高昂的判断失误——将持续上升的通胀定性为"暂时性"（transitory），从而推迟了货币政策正常化的步伐。这一误判导致美联储在通胀已经明显加速的情况下仍维持超宽松政策，最终不得不在2022年以40年来最激进的加息速度追赶，对全球经济和金融市场产生了深远影响。 2021年初，美国通胀开始加速。1月CPI同比上涨1.4%，6月已升至5.4%，11月达到6.8%。然而，',
    context: '美联储官员反复强调通胀是"暂时性"的，主要反映了基数效应、供应链瓶颈和能源价格波动等短期因素。3月FOMC会议的预测显示，2021年核心PCE通胀仅为2.2%，2022年将回落至2.0%。鲍威尔在多个场合表示，通胀将在中期回归2%目标，不需要政策回应。 美联储的判断基于几个逻辑。首先，通胀主要由少数受疫情影响的类别驱动（二手车、能源等），而非广泛的价格上涨。其次，长期通胀预期仍锚定在2%附近，5年5年远期通胀预期仅约2.2%。第三，劳动力市场尚未完全恢复，失业率仍高于疫情前水平，菲利普斯曲线关系表明通胀缺乏持续动力。第四，全球化和技术进步等结构性因素仍在压制通胀。 然而，这些判断逐一被证伪。供应链瓶颈比预期更持久，俄乌冲突进一步推高能源和食品价格。劳动力市场紧张程度超出预期——职位空缺数远超失业人数，工资增长加速，形成了"工资-价格"螺旋。通胀从商品扩展到服务，从生产者价格传导至消费者价格',
