    id: 'case_98',
    category: '金融史',
    difficulty: 3,
    title: '2022年全球央行激进加息',
    description: '2022年，全球主要央行以数十年来未见的速度和力度同步加息，标志着超宽松货币时代的终结和对抗通胀新纪元的开始。美联储全年加息425个基点，欧洲央行加息250个基点，英格兰银行加息325个基点，加拿大央行加息400个基点——这是自1980年代沃尔克时代以来最激进的全球货币紧缩周期。这一政策转向对全球经济和金融市场产生了深远影响，从房地产市场到科技股估值，从新兴市场资本流动到主权债务可持续性，无一不受',
    context: '波及。 全球加息潮的导火索是2022年2月俄乌冲突爆发后能源和食品价格飙升，叠加2021年已经高企的通胀，使全球通胀率达到了40年来的最高水平。美国CPI在2022年6月达到9.1%的峰值，欧元区通胀在10月达到10.6%，英国通胀在10月达到11.1%。央行官员们意识到，通胀已经不再是"暂时性"的，必须采取果断行动防止高通胀预期根深蒂固。 美联储在2022年3月16日启动加息，首次加息25个基点；5月加息50个基点；6月、7月、9月、11月连续四次加息75个基点，这是自1994年以来首次单次加息75个基点；12月加息50个基点。全年累计加息425个基点，联邦基金利率从0-0.25%升至4.25-4.50%。欧洲央行在7月才启动十年来首次加息，但此后连续大幅加息，10月加息75个基点，全年加息250个基点，存款便利利率从-0.50%升至2.00%，正式结束了负利率时代。 激进加息的全球影响',
