    id: 'case_99',
    category: '并购',
    difficulty: 3,
    title: '2023年瑞士央行紧急促成瑞信收购',
    description: '2023年3月19日，在瑞士政府的强力推动下，瑞银集团（UBS）同意以30亿瑞士法郎收购陷入危机的瑞士信贷（Credit Suisse），这是一场在48小时内完成的紧急并购，旨在防止瑞士信贷的倒闭引发全球金融系统性风险。瑞士央行提供了超过2000亿瑞士法郎的流动性支持，瑞士政府提供了90亿瑞郎的损失担保。然而，最引发争议的是，160亿瑞郎的额外一级资本（AT1）债券被全额减记，债券持有人血本无归，',
    context: '而股东却仍获得了少量补偿，这颠覆了传统的偿付顺序，对全球AT1债券市场造成了巨大冲击。 瑞士信贷的危机是长期管理失败和近期信心崩溃的结合。多年来，瑞士信贷因一系列丑闻和亏损而元气大伤：2021年Greensill Capital和Archegos爆仓导致损失超过100亿美元；2022年泄露的账户数据显示其持续为受制裁的客户提供服务；2022年全年净亏损73亿瑞郎。2022年10月，沙特国家银行董事长在接受采访时表示"绝对不会"向瑞信提供更多资本，引发市场恐慌，存款单日流出超过100亿瑞郎。 2023年3月硅谷银行倒闭后，市场对银行体系的紧张情绪蔓延至瑞士信贷。3月15日，瑞信股价暴跌24%，CDS利差飙升至1000个基点以上。瑞士央行和FINMA发表联合声明表示将提供流动性支持，但市场信心未能恢复。3月17日至18日周末，瑞士政府、央行和监管机构紧急磋商，最终决定促成瑞银收购瑞信，而非让其',
