    id: 'case_100',
    category: '金融史',
    difficulty: 3,
    title: '2024年日本央行退出负利率',
    description: '2024年3月19日，日本银行以7:2的投票结果决定结束长达八年的负利率政策，将短期利率从-0.1%上调至0-0.1%的区间，同时终止收益率曲线控制（YCC）政策和交易所交易基金（ETF）的购买计划。这是日本银行自2007年2月以来首次加息，标志着日本终于走出了长达数十年的通缩阴影，也意味着全球最后一个实施负利率的主要经济体回归正常化。 日本央行政策转向的背景是通胀和工资增长出现了可持续的迹象。2',
    context: '024年春季的"春斗"工资谈判结果超出预期，大企业平均加薪5.28%，创下33年来最大涨幅。核心CPI已连续多月维持在2%以上，服务价格也在上涨，表明通胀正在从成本推动型转向需求拉动型。日本银行认为，实现2%通胀目标的"确定性"已经提高，具备了政策正常化的条件。 政策转向的具体措施包括：取消负利率政策，将无担保隔夜拆借利率目标设为0-0.1%；终止YCC政策，不再设10年期国债收益率目标，但将继续购买国债（每月约6万亿日元）以维护市场稳定；停止购买ETF和房地产投资信托（J-REIT），逐步减少购买公司债券和商业票据；取消100%利率上限适用激励制度。 然而，日本央行的转向极为谨慎。政策声明强调"金融宽松条件将暂时维持"，暗示不会连续加息。行长植田和男在记者会上表示，将"暂时"维持宽松的金融环境，未来加息的步伐将取决于经济和通胀的发展。市场预期日本央行在2024年内仅会再加息1-2次，每次',
