    title: '2006年Amaranth Advisors天然气交易巨亏',
    description: '2006年9月，总部位于康涅狄格州的对冲基金Amaranth Advisors在天然气期货交易中损失约65亿美元，基金净值在一个月内蒸发约70%，成为当时对冲基金历史上最大的交易亏损之一。Amaranth的崩溃是杠杆交易、集中持仓和市场流动性不足相结合的灾难性后果，也是商品市场操纵争议的焦点案例。 Amaranth的明星交易员布莱恩·亨特（Brian Hunter）采用了一种基于天然气期货价差的策',
    context: '略。他大量做多冬季天然气期货合约、做空夏季合约，赌的是冬季和夏季天然气价格之间的价差会扩大——这一策略在2005年卡特里娜飓风后为他带来了巨额利润，使Amaranth在2005年回报率超过100%，亨特也因此获得了约1亿美元的奖金。2006年，亨特加倍押注同一策略，管理的头寸规模如此庞大，以至于据估计他控制了NYMEX天然气期货冬季合约约70%的未平仓量。 然而，2006年的天然气市场并未如亨特预期般发展。温和的冬季天气减少了取暖需求，天然气库存充裕，冬季-夏季价差不升反降。9月中旬，价差急剧收窄，Amaranth的巨额头寸开始产生巨额亏损。更糟糕的是，由于持仓过于集中，亨特无法在不进一步压低价格的情况下平仓——市场参与者知道Amaranth被迫卖出，纷纷抢先抛售，形成了"踩踏"效应。Amaranth试图通过场外交易和与投行协商来有序平仓，最终将整个天然气组合以约25亿美元的折扣转让给Ci',
