    difficulty: 3,
    title: '2008年兴业银行热罗姆·凯维埃尔案',
    description: '2008年1月24日，法国兴业银行披露其旗下一名31岁的初级交易员热罗姆·凯维埃尔（Jérôme Kerviel）通过未经授权的欧洲股指期货交易，造成了49亿欧元（约71亿美元）的损失，这是当时银行业历史上最大的流氓交易员案件。这一事件在全球金融界引起巨大震动，尤其是因为它发生在以风险控制严格著称的法国最大银行之一。 凯维埃尔于2000年加入兴业银行，最初在中后台部门工作，负责处理和监控交易数据。',
    context: '2005年，他转至前台，成为Delta One交易员，负责欧洲股指期货的套利交易。正是其中后台的工作经验，使他深谙银行的风险控制系统和检查流程。凯维埃尔的手法极为精密：他利用对银行监控系统的了解，在真实交易之外伪造了对冲交易，使风险管理系统显示其净头寸在限额之内。他还利用了银行内部多个系统之间的数据延迟，在检查期间暂时建立虚假对冲头寸，检查过后再撤销。此外，他选择在流动性最高的欧洲股指期货（Euro Stoxx 50、DAX、FTSE 100）市场进行交易，以避免因流动性不足而引起注意。 凯维埃尔的未授权头寸规模惊人——在2007年底至2008年初的高峰期，他的名义头寸总额达到约500亿欧元，接近兴业银行总市值的1.5倍。2008年1月，随着全球股市大幅下跌，凯维埃尔的头寸开始产生巨额亏损。1月18日，银行的监控系统终于发现了异常，1月21日至23日，银行在市场下跌时被迫紧急平仓，最终确认',
