    id: 'case_104',
    category: '金融史',
    difficulty: 3,
    title: '2011年瑞银阿多博利案',
    description: '2011年9月15日，瑞银（UBS）披露其旗下Delta One交易台的一名31岁交易员基库·阿多博利（Kweku Adoboli）通过未经授权的交易造成了23亿美元的交易损失。这一事件发生在凯维埃尔案仅三年后，令人震惊的是，瑞银似乎没有从兴业银行的教训中吸取足够的经验。阿多博利案再次暴露了银行风险管理的系统性缺陷，也加速了瑞银战略方向的重大调整。 阿多博利2006年加入瑞银，最初在后台运营部门工',
    context: '作，2007年转入Delta One交易台担任交易员。与凯维埃尔类似，阿多博利的后台经验使他深谙银行的风险控制流程。Delta One交易台主要进行ETF套利和股指期货交易，理论上这些交易应该是低风险的——通过买入低估的ETF份额、卖出高估的期货合约来获取微小价差。然而，阿多博利逐渐偏离了套利策略，开始进行方向性押注，赌欧洲股市的走势。 阿多博利的手法包括：使用虚构的ETF交易来对冲真实期货头寸，使风险管理系统显示净头寸为零；利用内部账户之间的转账来掩盖真实盈亏；在接近报告日期时临时建立虚假对冲头寸以通过检查。2011年夏季，全球股市因欧债危机而剧烈波动，阿多博利的方向性押注开始产生巨额亏损。8月，他加倍押注市场反弹，但市场继续下跌。9月初，他的亏损已超过20亿美元，无法继续掩盖。 2011年9月14日，阿多博利向银行合规部门发送了一封告白邮件，详细描述了自己的未授权交易行为。瑞银在9月1',
