    id: 'case_105',
    category: '金融史',
    difficulty: 3,
    title: '2012年摩根大通\'伦敦鲸\'事件',
    description: '2012年5月，摩根大通披露其首席投资办公室（CIO）在信用衍生品交易中损失约62亿美元，这一事件因交易头寸规模巨大而被市场称为"伦敦鲸"（London Whale）。"伦敦鲸"事件之所以特别引人注目，是因为摩根大通一直以风险管理卓越著称，其CEO杰米·戴蒙（Jamie Dimon）被视为银行业最优秀的管理者之一。这一事件不仅重创了摩根大通的声誉，也对沃尔克规则（Volcker Rule）的实施产',
    context: '生了重要影响。 CIO的职能是管理摩根大通约3500亿美元的超额存款，通过投资高评级证券来产生收益，同时对冲银行的整体信用风险。CIO的交易员布鲁诺·伊克西尔（Bruno Iksil）在CDX.NA.IG（北美投资级企业信用违约互换指数）市场上建立了巨额头寸——他大量卖出IG9指数的信用保护（即赌该指数不会大幅下跌），头寸规模如此庞大，以至于市场参与者给他起了"伦敦鲸"的绰号。 2012年初，随着企业信用市场利差扩大，伊克西尔的头寸开始产生亏损。为了减少损失，CIO采取了"风险再平衡"策略——增加更长期限的信用保护卖出，试图通过曲线交易（curve trade）来降低风险敞口。然而，这一策略实际上加大了头寸规模和风险，使损失进一步扩大。4月初，对冲基金开始意识到CIO的困境，纷纷买入信用保护，与摩根大通对赌，迫使IG9指数利差进一步扩大。 4月13日，戴蒙在分析师电话会议上将媒体报道的CI',
