    id: 'case_107',
    category: '金融史',
    difficulty: 3,
    title: '2020年WTI原油期货负油价事件',
    description: '2020年4月20日，美国西德克萨斯中质原油（WTI）5月期货合约在到期日暴跌至每桶-37.63美元，这是自1983年NYMEX开始原油期货交易以来首次出现负油价。这一史无前例的事件震惊了全球金融市场，也深刻揭示了期货市场交割机制在极端供需失衡下的运行逻辑。 负油价的直接原因是新冠疫情导致的全球石油需求骤降与储油能力不足之间的矛盾。2020年3月至4月，全球多国实施封锁措施，航空停飞、工厂停工、汽',
    context: '车停驶，全球石油日需求从约1亿桶骤降至约8000万桶。与此同时，沙特和俄罗斯之间的价格战导致产量不降反增。供给过剩使原油库存迅速填满，特别是WTI期货的交割地——俄克拉荷马州库欣（Cushing）的储油设施在4月中旬已接近满负荷。 WTI期货采用实物交割制度，持有到期合约的多头必须在库欣接收原油。4月20日是5月合约的最后交易日，持有多头头寸的交易者面临一个严峻选择：要么在到期前平仓，要么安排在库欣接收原油。由于库欣的储油空间已基本耗尽，租赁储油罐的成本飙升，甚至出现"无处可放油"的局面。多头被迫不惜代价平仓，而空头则利用这一机会大幅压低价格，最终将5月合约推至-37.63美元的负值——这意味着卖方需要向买方支付费用才能完成交割。 负油价对市场参与者造成了严重冲击。中国银行旗下的"原油宝"产品因挂钩WTI期货，在负油价中遭受巨额损失，投资者不仅本金全部亏损，还面临倒欠银行的局面，引发了广泛',
