    id: 'case_108',
    category: '交易',
    difficulty: 3,
    title: '2021年Archegos资本管理爆仓',
    description: '2021年3月，家族办公室Archegos资本管理在短短数日内爆仓，造成全球多家投资银行超过100亿美元的损失，其中瑞信损失约55亿美元，野村损失约29亿美元，摩根士丹利损失约10亿美元。Archegos事件是华尔街十年来最大的爆仓事件，暴露了家族办公室监管空白、银行风险管理缺陷和总收益互换（TRS）等衍生品的系统性风险。 Archegos的创始人比尔·黄（Bill Hwang）曾是老虎基金朱利安',
    context: '·罗伯逊的门徒，后因内幕交易被SEC处罚而自立门户。他通过总收益互换（Total Return Swap, TRS）建立了高达约1000亿美元的股票头寸，而Archegos的实际资本仅约100亿美元，杠杆率高达10倍。TRS是一种场外衍生品，银行买入标的股票并持有，将股票的收益和损失转移给Archegos，Archegos只需支付少量保证金。这种安排使Archegos无需直接持有股票就能获得经济敞口，同时规避了5%持股需披露的监管要求。 Archegos集中押注了少数几只股票，包括ViacomCBS、Discovery、腾讯音乐、百度和跟谁学等。2021年3月，ViacomCBS宣布增发股票，股价开始下跌。Archegos的高杠杆头寸迅速进入亏损状态，保证金要求增加。3月25日，Archegos无法满足追加保证金要求，多家银行开始强制平仓。由于多家银行同时抛售相同的股票，形成了"踩踏"效应',
