    id: 'case_109',
    category: '交易',
    difficulty: 3,
    title: '2022年伦敦金属交易所镍期货逼空事件',
    description: '2022年3月8日，伦敦金属交易所（LME）在镍价在数小时内翻倍至超过10万美元/吨后，做出了一个史无前例的决定——暂停镍交易，并取消了当日所有已执行的交易。这一决定引发了巨大争议，也暴露了LME在应对极端市场波动时的治理困境。镍期货逼空事件的中心人物是中国青山控股集团，这家全球最大的不锈钢和镍生产商持有大量镍空头头寸，用于对冲其产量风险。 事件背景是俄乌冲突爆发后，全球大宗商品市场剧烈波动。俄罗',
    context: '斯是全球第三大镍生产国，供应了全球约7%的镍和约17%的高品位镍。市场担忧俄罗斯镍供应中断，镍价从2月初的约22000美元/吨开始上涨。3月初，价格加速攀升，3月7日从29000美元/吨飙升至50000美元/吨以上。 3月8日，镍价在开盘后数小时内从50000美元/吨飙升至101365美元/吨，日内涨幅超过100%。青山控股持有约20万吨的镍空头头寸，用于对冲其产量。按照10万美元/吨的价格计算，青山的浮亏可能超过80亿美元，远超其承受能力。LME在3月8日0815 GMT暂停了镍交易，随后宣布取消当日0000 GMT之后的所有交易，将价格回滚至50300美元/吨。 LME的决定引发了激烈争议。一方面，如果不暂停交易和取消交易，青山控股的巨额亏损可能引发系统性风险——多家经纪商和银行作为青山的交易对手方，也面临巨额保证金要求，可能引发连锁违约。另一方面，LME取消已执行交易的做法严重损害了',
