    id: 'case_110',
    category: '银行',
    difficulty: 4,
    title: '2004年澳大利亚国民银行外汇交易丑闻',
    description: '2004年1月，澳大利亚国民银行（NAB）披露其外汇期权交易台的四名交易员通过虚构交易和操纵估值，累计造成了3.6亿澳元的损失。这一事件虽然规模不及后来的凯维埃尔案，但同样揭示了银行交易台风险管理的系统性缺陷，也促使澳大利亚银行业加强了监管和内部控制。 四名交易员——Luke Duffy、David Bullen、Vince Ficarra和Gianni Gray——在2001年至2003年间，通',
    context: '过系统性地虚构外汇期权交易来掩盖实际交易亏损。他们的手法包括：在银行系统中录入虚假的期权交易来对冲真实头寸，使风险管理系统显示净头寸为零；在月末和季末调整虚假交易的估值来美化盈亏报告；利用银行内部不同系统之间的数据不一致来规避检查。 丑闻的暴露源于一次内部审计。2003年10月，NAB的内部审计团队在例行检查中发现了外汇交易台的异常交易模式，随后展开了深入调查。2004年1月，银行公开披露了损失规模，四名交易员被解雇并面临刑事指控。Duffy被判处两年半监禁，Bullen被判处两年半监禁（缓刑），Ficarra和Gray也受到了法律制裁。 NAB外汇交易丑闻的深层原因包括：交易台文化鼓励冒险和短期利润；风险管理系统存在漏洞，未能有效识别虚假交易；中后台人员缺乏足够的专业知识来验证期权估值；管理层对异常盈利缺乏质疑。丑闻还暴露了NAB更广泛的治理问题——在丑闻曝光前后，NAB还面临了其他治理',
