    difficulty: 4,
    title: '2014年外汇市场操纵丑闻',
    description: '2014年11月，美国、英国和瑞士的监管机构对六家大型银行处以总计约43亿美元的罚款，原因是其交易员在外汇市场操纵汇率。这是继LIBOR操纵丑闻之后，全球银行业面临的又一大规模市场操纵案件，涉及的银行包括花旗、摩根大通、巴克莱、苏格兰皇家银行、瑞银和美银美林。外汇市场日均交易量超过5万亿美元，是全球最大的金融市场，其操纵丑闻对市场信心造成了严重打击。 操纵的核心机制围绕WM/Reuters 4pm',
    context: '定盘价（即"伦敦定盘价"）展开。这一价格基于伦敦时间下午4点前后30秒内的交易数据计算，被全球大量基金和机构用作外汇交易的基准价格。交易员们通过一个名为"The Cartel"（卡特尔）和"The Bandits Bank"（强盗银行）的私密聊天室，在定盘价计算窗口前后协调交易，推动汇率朝有利于其头寸的方向移动。 交易员的操纵手法包括：在定盘价窗口前大量买入或卖出，以推动汇率朝特定方向移动（"banging the close"）；共享客户订单信息，提前了解大额订单的方向，从而进行"前置交易"（front-running）；在聊天室中协调行动，共同推动汇率突破特定水平以触发止损单或期权障碍。聊天记录显示，交易员们对操纵行为毫无顾忌，甚至开玩笑说"如果你不作弊，你就不够努力"。 监管调查始于2013年10月，当时彭博新闻社报道了交易员在私密聊天室中共享信息的行为。此后，多个司法管辖区的监管机',
