    difficulty: 4,
    title: '2018年马来西亚1MDB丑闻',
    description: '2018年7月，马来西亚总理马哈蒂尔重新上台后，揭露了1MDB（一马发展公司）丑闻的全貌——这个由前总理纳吉布于2009年设立的主权财富基金，被系统性侵吞了约45亿美元资金，涉及全球多家金融机构和中间人。1MDB丑闻是21世纪最大规模的政府腐败案件之一，也是金融合规失败的标志性案例，高盛因协助1MDB发行债券而深陷其中。 1MDB的运作模式堪称"教科书式"的洗钱和挪用。基金通过发行债券筹集资金，名',
    context: '义上用于能源、房地产和旅游项目，但大量资金被转入由纳吉布亲信刘特佐（Jho Low）控制的离岸账户。资金经过多层转移和伪装后，被用于购买豪华房地产、艺术品、游艇和私人飞机，甚至被用于资助好莱坞电影《华尔街之狼》的制作。约7亿美元流入了纳吉布的个人银行账户。 高盛在1MDB债券发行中扮演了关键角色。2012年至2013年，高盛为1MDB安排了三笔总计约65亿美元的债券发行，收取了约6亿美元的费用——远超正常债券承销费率。高盛声称其尽职调查未发现异常，但美国司法部的调查显示，高盛的某些员工明知1MDB的运作存在可疑之处，仍然推进了交易。高盛东南亚区董事长蒂姆·莱斯纳（Tim Leissner）承认共谋洗钱，被没收4370万美元并禁止从事证券业务。 1MDB丑闻的金融影响广泛而深远。高盛在2020年与美国司法部达成和解，支付超过29亿美元的罚款，并在马来西亚支付25亿美元赔偿。马来西亚对高盛提起',
