    difficulty: 3,
    title: '2021年GameStop逼空事件',
    description: '2021年1月，美国电子游戏零售商GameStop（GME）的股价在数周内从约20美元飙升至483美元，涨幅超过2400%，这场由散户投资者发起的"逼空"行动震惊了华尔街，也深刻改变了人们对金融市场力量格局的认知。GameStop事件不仅是金融史上的标志性时刻，也是社交媒体时代市场动态的全新范式。 GameStop逼空的核心机制是"空头挤压"（short squeeze）。在事件发生前，GameS',
    context: 'top的空头头寸占流通股的比例超过140%（因存在借入股票再卖空的情况），是美股被做空最严重的股票之一。华尔街的对冲基金，特别是梅尔文资本（Melvin Capital）和西托恩资本（Citron Research），大量做空GameStop，赌其股价会因实体零售业衰退而继续下跌。 然而，Reddit论坛WallStreetBets（WSB）上的散户投资者发现了这一机会。他们认为GameStop被过度做空，如果大量买入推高股价，空头将被迫回补（买入股票平仓），进一步推高股价，形成"逼空"循环。1月中旬，散户投资者开始大量买入GME股票和看涨期权，期权做市商的对冲操作（gamma squeeze）进一步放大了买入压力。1月28日，GME股价达到483美元的盘中高点。 1月28日，Robinhood等券商突然限制用户买入GME等"迷因股票"（meme stocks），只允许卖出，这一决定引发了',
