    id: 'case_115',
    category: '危机',
    difficulty: 5,
    title: '2010年美股闪电崩盘（Flash Crash）',
    description: '2010年5月6日，美国股市在短短约5分钟内经历了剧烈下跌和反弹——道琼斯指数在14:42至14:47之间暴跌约1000点（跌幅约9%），随后在约15分钟内收复了大部分失地。这一事件被称为"闪电崩盘"（Flash Crash），是高频交易和自动化交易时代市场脆弱性的标志性案例。部分个股的价格在崩盘期间出现了极端异常，如埃森哲的股价从约40美元跌至1美分，而苹果的股价则飙升至10万美元。 闪电崩盘的',
    context: '触发因素是一家共同基金公司Waddell & Reed通过算法交易程序卖出了约7.5万份E-mini S&P 500期货合约，名义价值约41亿美元，以对冲其投资组合风险。这一卖出订单本身规模并不算特别大，但在当时的市场环境下，高频交易算法的反应使价格下跌被急剧放大。高频交易公司检测到大量卖出订单后，也加入了卖出行列，但它们的持仓时间极短（通常不到1秒），在买入后迅速卖出，形成了"热土豆"效应——同样的合约在交易者之间快速传递，但净买入量并未增加。 更严重的是，许多高频交易算法在检测到异常波动后，选择撤回流动性，使买卖价差急剧扩大。做市商的撤出导致市场流动性瞬间枯竭，价格因此暴跌。在最低点，E-mini期货价格下跌了约5%，触发了芝加哥商品交易所（CME）的"速度减速带"（即5秒暂停机制），暂停交易后市场才逐步恢复。 美国CFTC和SEC在事件后进行了联合调查，2015年公布报告认定，伦敦交',
