    id: 'case_117',
    category: '交易',
    difficulty: 3,
    title: '2014年门头沟（Mt. Gox）交易所倒闭',
    description: '2014年2月28日，全球最大的比特币交易所门头沟（Mt. Gox）宣布申请破产保护，披露其丢失了约85万个比特币，其中75万个属于客户，10万个属于交易所自身。按照当时的价格，丢失的比特币价值约4.5亿美元；按照2024年的价格，这些比特币价值超过500亿美元。门头沟的倒闭是加密货币行业早期最严重的信任危机，也暴露了中心化交易所的系统性风险。 门头沟的起源与比特币几乎同步。2010年7月，Jed',
    context: ' McCaleb创建了Mt. Gox（最初是一个Magic: The Gathering卡牌交易网站），2011年将其卖给了法国开发者马克·卡佩莱斯（Mark Karpelès）。在2013年的比特币牛市中，门头沟处理了全球约70%的比特币交易，成为加密货币生态系统的核心枢纽。然而，门头沟的技术基础设施和管理能力远未跟上其业务增长的速度。 比特币丢失的原因至今仍有争议。卡佩莱斯声称，黑客利用比特币协议中的"交易延展性"（transaction malleability）漏洞，通过修改交易ID来重复提取比特币。然而，后来的调查表明，比特币的丢失可能早在2011年就开始了，远早于公开披露的时间。一些分析认为，门头沟可能长期处于资不抵债状态，通过新客户的存款来弥补旧客户的提款——本质上是一个庞氏骗局。 门头沟倒闭的过程充满混乱。2014年2月7日，门头沟暂停了所有比特币提款，声称发现了交易延展性',
