    difficulty: 3,
    title: '2023年币安被罚43亿美元',
    description: '2023年11月21日，全球最大的加密货币交易所币安（Binance）与美国司法部、商品期货交易委员会（CFTC）和财政部达成和解，同意支付约43亿美元的罚款，创下加密货币行业罚款纪录。创始人赵长鹏（CZ）同时辞去CEO职务，并承认违反反洗钱法规。这一和解标志着美国监管机构对加密货币行业的执法行动达到了新高度。 美国司法部的调查发现，币安在多个方面违反了美国法律。首先，币安故意允许美国用户在未完成',
    context: 'KYC（了解你的客户）验证的情况下进行交易，违反了反洗钱法规。币安甚至为高净值美国客户提供了规避合规检查的指引。其次，币安未能建立有效的反洗钱程序，使其平台被用于洗钱、恐怖融资和非法交易。司法部估计，与非法活动相关的交易在币安平台上的总额超过7亿美元。第三，币安违反了美国制裁法规，允许来自受制裁国家（如伊朗、朝鲜、叙利亚）的用户进行交易。 币安的合规问题由来已久。2019年，币安推出面向美国用户的Binance.US平台，但调查发现，币安的国际平台仍然大量服务美国客户。CZ在内部通信中曾表示，如果美国用户想使用币安，他们需要"使用VPN并隐瞒身份"。币安还鼓励员工使用加密通信应用（如Signal）进行工作沟通，并设置消息自动删除，以规避监管审查。 和解协议的条款包括：币安支付18亿美元罚款和25亿美元没收款；接受为期五年的独立合规监控；全面退出美国市场；CZ个人支付5000万美元罚款。CZ',
