    title: '2024年比特币现货ETF获批',
    description: '2024年1月10日，美国证券交易委员会（SEC）以3:2的投票结果批准了11只比特币现货ETF，包括贝莱德、富达、景顺等传统金融巨头发行的产品。这一决定结束了长达十年的监管博弈，标志着比特币正式进入美国主流金融市场。比特币现货ETF的首日交易量达到约46亿美元，创下了ETF首发日交易量纪录，反映了市场对这一产品的巨大需求。 SEC此前多次拒绝比特币现货ETF的申请，理由包括：比特币市场容易操纵、',
    context: '缺乏有效的监控共享协议、比特币期货市场与现货市场之间的关联性不足等。2023年8月，华盛顿特区巡回上诉法院裁定SEC拒绝Grayscale比特币信托（GBTC）转换为ETF的决定是"武断和反复无常的"，这一裁决迫使SEC重新审视其立场。 获批的11只比特币ETF在费率上展开了激烈竞争。贝莱德的iShares Bitcoin Trust（IBIT）收取0.25%的管理费（前12个月0.12%的优惠费率），富达的Wise Origin Bitcoin Fund收取0.25%（免收至7月），Bitwise收取0.24%。Grayscale的GBTC在转换为ETF后收取1.5%的费率，远高于竞争对手，导致大量资金流出。截至2024年底，比特币ETF累计净流入超过200亿美元，IBIT成为历史上增长最快的ETF之一。 比特币现货ETF的影响是多方面的。首先，它为传统投资者（养老金、捐赠基金、财富管理',
