    id: 'case_125',
    category: '危机',
    difficulty: 4,
    title: '2021年NFT泡沫',
    description: '2021年，非同质化代币（NFT）市场经历了爆炸式增长，全年交易额从2020年的约1亿美元飙升至约250亿美元，涨幅超过250倍。NFT泡沫是加密货币牛市中最具戏剧性的篇章之一，也是数字资产投机狂潮的缩影。从数字艺术品到虚拟地产，从体育收藏品到社交媒体头像，NFT似乎无所不包，价格屡创新高，但泡沫在2022年迅速破裂。 NFT泡沫的标志性事件包括：2021年3月，数字艺术家Beeple的NFT作品',
    context: '《Everydays: The First 5000 Days》在佳士得拍卖行以6930万美元成交，创下数字艺术品拍卖纪录；无聊猿游艇俱乐部（BAYC）系列NFT的地板价从4月的约0.08 ETH飙升至9月的约30 ETH；虚拟世界Decentraland和The Sandbox中的数字土地以数百万美元的价格交易；Twitter创始人杰克·多西的第一条推文NFT以290万美元售出。 NFT泡沫的驱动因素是多方面的。首先，2021年的加密货币牛市创造了大量新财富，NFT成为加密富豪展示财富和身份的途径。其次，新冠疫情使人们更多地在数字世界中生活和工作，增加了对数字资产的需求。第三，名人效应——从NBA球星斯蒂芬·库里到歌手林俊杰，大量名人购买和推广NFT，吸引了散户投资者涌入。第四，FOMO心理——许多人害怕错过"下一个比特币"，将NFT视为暴富机会。 然而，NFT市场在2022年急剧降温。',
