    title: '2022年Celsius Network破产',
    description: '2022年7月13日，加密借贷平台Celsius Network申请破产保护，披露其资产缺口约12亿美元，约30万名债权人受到影响。Celsius的破产是2022年加密货币行业连锁崩溃的重要一环，也是"CeFi"（中心化金融）风险暴露的典型案例。Celsius曾以高达17%的年化收益率吸引存款，但其商业模式本质上不可持续。 Celsius由亚历克斯·马辛斯基（Alex Mashinsky）于201',
    context: '7年创立，总部位于新泽西州。其商业模式是：吸收用户的加密货币存款，支付高额利息，然后将这些资金用于流动性挖矿、质押、借贷和专有交易等更高收益的活动，赚取利差。Celsius在2021年的加密牛市中迅速扩张，管理资产一度超过250亿美元，用户超过170万。 然而，Celsius的商业模式存在根本性问题。首先，其支付给存款人的利率远高于其投资活动的可持续回报率，利差为负——这意味着Celsius每吸收1美元存款都在亏损。其次，Celsius将大量用户资金投资于高风险、低流动性的DeFi协议和质押项目，包括stETH（Lido质押的以太坊）和各类流动性挖矿项目。第三，Celsius缺乏有效的风险管理，对市场下行缺乏缓冲。 2022年5月Luna/UST崩盘后，Celsius遭受了约6亿美元的损失。6月，stETH与ETH的脱锚进一步加剧了Celsius的困境——Celsius持有大量stETH，',
