    id: 'case_128',
    category: '金融史',
    difficulty: 3,
    title: '2019年PlusToken庞氏骗局',
    description: '2019年6月，中国警方开始大规模抓捕PlusToken庞氏骗局的运营者，这一涉案金额超过400亿元人民币（约57亿美元）的加密货币骗局是当时全球最大的加密货币欺诈案件之一。PlusToken的运作模式是典型的庞氏骗局——以高收益为诱饵吸引新投资者，用新资金支付旧投资者的回报，最终在资金链断裂时崩盘。 PlusToken于2018年5月上线，自称是一款"去中心化的数字货币钱包"，声称通过其"智能狗',
    context: '"（AI交易机器人）进行套利交易，可以为投资者提供10%至30%的月收益率。用户需要存入比特币、以太坊等加密货币才能激活"智能狗"并获得收益。PlusToken还采用了多级分销模式——用户通过推荐新用户加入可以获得额外的奖励，形成了庞大的传销网络。 PlusToken的推广极具侵略性。它在微信、微博等中国社交媒体上大量投放广告，举办线下推广活动，甚至赞助体育赛事。其用户主要集中在中国、韩国和东南亚，注册用户超过200万。然而，"智能狗"的交易收益完全是虚构的——PlusToken没有任何真实的交易策略，早期投资者的回报完全来自新投资者的存款。 2019年6月底，PlusToken突然停止了提款功能，运营团队开始转移资金。区块链分析公司Chainalysis追踪到PlusToken的比特币钱包，发现其持有超过18万个BTC和900万个ETH，按当时价格价值约40亿美元。这些资金经过复杂的洗钱',
