    difficulty: 3,
    title: '2020年DeFi之夏',
    description: '2020年6月至9月，去中心化金融（DeFi）经历了爆发式增长，被称为"DeFi之夏"。锁定在DeFi协议中的总价值（TVL）从6月初的约10亿美元飙升至9月底的约150亿美元，涨幅超过14倍。DeFi之夏标志着区块链技术从"数字黄金"叙事转向"可编程金融"叙事，也催生了流动性挖矿、治理代币和收益农耕等全新金融范式。 DeFi之夏的导火索是Compound协议在6月15日推出其治理代币COMP的流',
    context: '动性挖矿计划。Compound向提供流动性的用户分发COMP代币作为额外激励，用户可以通过借贷活动获得COMP代币奖励。这一模式立即被市场解读为"免费的钱"——用户在正常借贷收益之外还能获得代币奖励，年化收益率动辄超过100%。COMP代币的价格在推出后迅速上涨，进一步放大了收益率。 流动性挖矿模式迅速被其他DeFi协议复制。Synthetix、Balancer、Curve、Yearn Finance、Yam Finance等项目纷纷推出自己的治理代币和挖矿计划。其中最极端的案例是Yam Finance——这个在8月11日上线的协议，其YAM代币在36小时内从0飙升至约160美元，TVL达到5亿美元。然而，Yam Finance的智能合约被发现存在一个致命漏洞（rebase机制中的整数溢出），导致代币供应量异常膨胀，YAM价格在数小时内暴跌99%。 DeFi之夏还催生了"收益农耕"（yie',
