    description: '2021年，狗狗币（Dogecoin）——一种最初作为玩笑创建的加密货币——经历了令人难以置信的价格飙升，从年初的约0.005美元涨至5月的约0.73美元，涨幅超过14000%，市值一度超过800亿美元。狗狗币狂潮是2021年加密货币牛市中最荒诞的篇章，也是社交媒体力量和"迷因经济"（meme economy）的极端体现。 狗狗币于2013年由软件工程师比利·马库斯和杰克逊·帕尔默创建，其标志是当',
    context: '时流行的"柴犬"表情包（Doge meme）。创建狗狗币的初衷是讽刺加密货币市场的投机狂热——一种"连玩笑币都能有价值"的讽刺。然而，狗狗币凭借其友好的社区文化和"做善事"的传统（曾资助牙买加雪橇队参加冬奥会、肯尼亚清洁饮水项目等），在加密社区中保持了持久的关注度。 2021年狗狗币狂潮的核心推手是埃隆·马斯克。从1月开始，马斯克频繁在Twitter上发布关于狗狗币的推文，每次发布后狗狗币价格都会大幅上涨。2月4日，马斯克发布了一张"狗狗币"杂志封面的图片，狗狗币单日上涨50%。4月1日，马斯克称将把一枚狗狗币"送到月球"（字面意思，SpaceX将发射携带狗狗币的卫星），价格再次飙升。5月8日，马斯克在《周六夜现场》节目中被问及狗狗币时，称其为"hustle"（骗局），价格随即暴跌。 狗狗币狂潮还得到了Reddit社区WallStreetBets和CryptoCurrency的推动。在Ga',
