    title: '2019年Libra/Diem项目',
    description: '2019年6月18日，Facebook宣布将推出名为Libra的全球数字货币，计划于2020年上线。这一消息在全球金融界和监管界引发了地震般的反应——一家拥有27亿用户的社交媒体公司要发行自己的货币，这对主权货币体系和全球金融稳定意味着什么？Libra项目（后更名为Diem）最终在监管压力下大幅缩水，并于2022年1月正式终止，但其对央行数字货币（CBDC）发展的推动作用不可忽视。 Libra的初',
    context: '始设计雄心勃勃。它将是一种与一篮子货币（美元、欧元、日元、英镑、新加坡元）挂钩的稳定币，由总部设在瑞士的Libra协会管理。Libra协会的创始成员包括Visa、Mastercard、PayPal、Uber、Spotify等28家企业和非营利组织，每个创始成员需缴纳1000万美元的加盟费。Libra区块链将采用许可链（初期）逐步过渡到公有链的模式，使用BFT共识机制。 Facebook的参与是Libra最大的资产，也是最大的包袱。Facebook拥有27亿月活用户，如果Libra被整合到WhatsApp、Messenger和Instagram中，其潜在用户规模将超过任何现有货币。然而，Facebook此前因Cambridge Analytica数据丑闻而信誉受损，监管机构和立法者对其管理货币的能力深表怀疑。 Libra宣布后，全球监管机构迅速表达了强烈反对。美国众议院金融服务委员会主席马克',
