    id: 'case_134',
    category: '交易',
    difficulty: 3,
    title: '2020年Robinhood交易限制争议',
    description: '2021年1月28日，在GameStop逼空事件最激烈的时刻，零佣金交易平台Robinhood突然限制用户买入GME、AMC、BB等"迷因股票"，只允许卖出。这一决定引发了轩然大波——散户投资者愤怒地指责Robinhood"操纵市场"，在华尔街对冲基金亏损时改变规则。Robinhood的CEO弗拉德·特内夫（Vlad Tenev）被传唤至国会作证，平台面临数十起集体诉讼。 Robinhood限制买',
    context: '入的直接原因是清算所要求的保证金大幅增加。美国证券交易实行T+2结算制度——交易在两天后完成结算，在此期间，清算所（DTCC）要求券商缴纳保证金以覆盖潜在风险。1月27日至28日，随着GME等股票的波动性急剧上升，DTCC的全国证券清算公司（NSCC）将Robinhood的保证金要求从约7亿美元提高至约15亿美元。Robinhood声称，公司没有足够的资金满足这一要求，不得不限制买入以控制风险敞口。 然而，Robinhood的解释未能平息公众愤怒。散户投资者认为，Robinhood的真正动机是保护其做市商合作伙伴（如Citadel Securities）的利益——如果GME价格继续上涨，做空GME的对冲基金（包括Citadel投资的梅尔文资本）将遭受更大损失。Citadel Securities是Robinhood最大的订单流支付（payment for order flow）来源，两者之',
