    id: 'case_135',
    category: '金融史',
    difficulty: 3,
    title: '2021年SPAC上市热潮',
    description: '2021年，特殊目的收购公司（SPAC，又称"空白支票公司"）在美国资本市场掀起了前所未有的热潮。全年共有613家SPAC完成IPO，筹集资金超过1600亿美元，远超2020年的248家和830亿美元。SPAC热潮是低利率环境、散户投资者涌入和加密货币牛市共同催生的金融创新与投机泡沫，也引发了关于市场质量和投资者保护的深刻讨论。 SPAC的运作机制是：发起人设立一家空壳公司，通过IPO筹集资金（通',
    context: '常每单位10美元），然后在规定时间内（通常18-24个月）寻找一家私人公司进行合并，使后者实现"借壳上市"。与传统IPO相比，SPAC上市的优势包括：更快的上市速度（通常3-6个月 vs 12-18个月）；更灵活的信息披露（SPAC允许使用前瞻性预测，而传统IPO不允许）；更确定的估值（与SPAC发起人协商确定，而非由市场定价）。 2021年SPAC热潮的标志性案例包括：电动汽车公司Lucid Motors通过Churchill Capital Corp. IV合并上市，估值约240亿美元；在线赌博公司DraftKings在2020年通过SPAC上市后股价大涨，激发了更多SPAC交易；加密货币交易平台Bullish、金融科技公司SoFi等也通过SPAC上市。然而，许多SPAC合并后的公司表现不佳——De-SPAC指数在2021年下半年下跌超过40%。 SPAC热潮的驱动因素包括：超低利率环',
