    title: '2007年苏格兰皇家银行并购荷兰银行',
    description: '2007年10月，以苏格兰皇家银行（RBS）为首的财团以约710亿欧元（约1000亿美元）收购了荷兰银行（ABN AMRO），这是当时银行业历史上最大的并购交易。然而，这笔交易在市场周期顶部完成，随后全球金融危机爆发，RBS因收购带来的巨额债务和减值而濒临破产，最终被英国政府国有化。RBS-ABN AMRO并购是"在错误的时间以错误的价格买错误资产"的典型案例。 并购战的背景是2007年银行业的并',
    context: '购热潮。ABN AMRO是荷兰最大的银行，但因业绩不佳而成为收购目标。英国巴克莱银行首先提出收购要约，但RBS财团（包括西班牙Santander银行和比利时Fortis银行）提出了更高的竞购价格。经过数月的竞购战，RBS财团以约710亿欧元胜出——这一价格约为ABN AMRO账面价值的2.5倍，远超合理估值。 RBS的收购资金主要来自债务融资。在收购完成时，RBS的资产负债表急剧膨胀，杠杆率大幅上升。更糟糕的是，RBS在收购中获得了ABN AMRO的美国子公司LaSalle银行，但这一资产在金融危机中遭受重创。Fortis银行也因收购ABN AMRO的荷兰业务而陷入困境，最终被荷兰政府部分国有化。 2008年9月雷曼兄弟倒闭后，RBS的处境急剧恶化。收购ABN AMRO带来的巨额债务和不良资产使RBS成为英国银行业中最脆弱的机构。2008年10月，英国政府向RBS注入200亿英镑资本，获得',
