    title: '2008年美国银行并购美林证券',
    description: '2008年9月15日，在雷曼兄弟倒闭的同一天，美国银行宣布以约500亿美元收购美林证券，这笔交易在金融危机最混乱的时刻完成，后来成为并购争议的焦点案例。美国银行CEO肯·刘易斯（Ken Lewis）在政府压力下完成了收购，但美林证券的巨额亏损几乎拖垮了美国银行，而收购前的信息披露问题也引发了法律诉讼和监管调查。 并购的背景是2008年9月金融体系的全面恐慌。雷曼兄弟倒闭后，美林证券成为市场下一个攻',
    context: '击目标——其大量持有次贷相关资产，股价暴跌，信用违约互换利差飙升。美林CEO约翰·赛恩（John Thain）紧急寻求买家，美国银行在9月14日至15日的周末迅速达成协议，以0.859股美国银行股票换1股美林股票，总价约500亿美元，较美林9月12日的收盘价溢价约70%。 然而，在收购完成前的第四季度，美林的财务状况急剧恶化，亏损达到约153亿美元——远超美国银行在签署协议时的预期。美国银行声称，美林在签署协议后未及时披露第四季度的巨额亏损，而美国银行也未向股东披露这一信息，导致股东在不了解真实情况的情况下投票批准了收购。纽约州总检察长库莫对此展开了调查。 2009年1月，刘易斯在政府压力下完成了收购——美联储主席伯南克和财政部长保尔森据称警告刘易斯，如果退出收购，美国银行管理层和董事会将被更换。美国银行随后获得了200亿美元的TARP额外注资和1180亿美元的资产担保。 2014年，美国',
