    description: '2014年2月19日，Facebook宣布以约190亿美元收购即时通讯应用WhatsApp，这是当时科技行业最大的并购交易之一。收购价格包括约40亿美元现金、约120亿美元Facebook股票和约30亿美元限制性股票单位。对于一个当时年收入仅约1000万美元、仅有55名员工的公司来说，这一估值令人震惊——相当于每个WhatsApp用户价值约42美元。 Facebook收购WhatsApp的战略逻辑',
