    title: '2016年拜耳并购孟山都',
    description: '2016年9月14日，德国制药和化工巨头拜耳宣布以约660亿美元收购美国农业生物技术公司孟山都，这是当年最大的跨境并购交易，也是农业行业历史上最大的并购。然而，这笔交易后来成为拜耳的沉重负担——孟山都的草甘膦除草剂Roundup面临数万起致癌诉讼，拜耳的市值在收购后大幅缩水，被戏称为"史上最糟糕的并购之一"。 拜耳收购孟山都的战略逻辑是打造全球最大的种子和农化公司。拜耳在作物保护和种子领域有强势地',
    context: '位，孟山都则是全球最大的转基因种子供应商和Roundup除草剂的制造商。合并后的公司将控制全球约25%的种子和农化市场。然而，这一市场集中度引发了反垄断担忧——拜耳被迫出售了约90亿美元的资产（包括整个蔬菜种子业务和部分除草剂业务）给巴斯夫，以获得监管批准。 交易于2018年6月完成，拜耳为此支付了约630亿美元（扣除出售资产后的净额）。然而，几乎在交易完成的同时，孟山都的法律风险开始爆发。2018年8月，加州旧金山的一个陪审团裁定Roundup导致一名校园场地管理员患癌，判决拜耳赔偿2.89亿美元（后减至7850万美元）。此后，类似诉讼如潮水般涌来——截至2023年，拜耳面临超过10万起Roundup致癌诉讼。 2020年6月，拜耳宣布以约109亿美元和解约12.5万起Roundup诉讼，同时承诺在未来五年内再支付12.5亿美元解决潜在的未来诉讼。然而，和解并未完全解决法律风险——仍有约',
