    title: '2017年迪士尼并购21世纪福克斯',
    description: '2017年12月14日，迪士尼宣布以约524亿美元收购21世纪福克斯的大部分娱乐资产，包括福克斯电影工作室、福克斯电视工作室、国家地理频道、福克斯在Hulu的30%股份等。这笔交易在2019年3月完成（最终价格为约713亿美元，含债务），是迪士尼历史上最大的收购，也是媒体行业整合浪潮的标志性事件。 迪士尼收购福克斯的战略逻辑是应对流媒体时代的竞争。Netflix、Amazon Prime Vide',
    context: 'o等流媒体平台的崛起对传统媒体巨头构成了严峻挑战。迪士尼CEO鲍勃·伊格尔（Bob Iger）认为，要在流媒体时代获胜，迪士尼需要更多的内容资产——福克斯的影视库（包括《阿凡达》、《辛普森一家》、《X战警》等IP）将大大增强迪士尼的内容优势。此外，福克斯在Hulu的30%股份使迪士尼获得了Hulu的控股权（加上此前持有的30%），为迪士尼的流媒体战略提供了重要平台。 然而，迪士尼的收购也面临来自康卡斯特（Comcast）的竞购。康卡斯特在2018年6月提出了650亿美元的全现金竞购报价，迫使迪士尼提高报价至713亿美元。最终，迪士尼凭借其更高的确定性和反垄断优势赢得了竞购战——康卡斯特作为有线电视运营商收购福克斯内容资产面临更大的反垄断障碍。 收购完成后，迪士尼于2019年11月推出了Disney+流媒体服务，凭借丰富的内容库（包括漫威、星球大战、皮克斯、国家地理和福克斯内容）迅速获得用户',
