    title: '2022年马斯克收购Twitter',
    description: '2022年10月27日，埃隆·马斯克以440亿美元完成对社交媒体平台Twitter的收购，结束了长达七个月的戏剧性并购过程。这笔交易是科技行业最具争议的收购之一，从马斯克的突然报价到试图反悔，再到被迫完成交易，整个过程充满戏剧性，也揭示了社交媒体治理、言论自由和企业并购法律的复杂交织。 收购过程始于2022年4月14日，马斯克向SEC提交文件，披露其已收购Twitter 9.1%的股份，并提出以每',
    context: '股54.20美元（总价约440亿美元）收购Twitter全部股份。Twitter董事会最初采取了"毒丸计划"（poison pill）抵制收购，但在马斯克直接向股东发出收购要约后，董事会于4月25日接受了报价。 然而，5月13日，马斯克突然宣布"暂时搁置"收购，声称需要确认Twitter的虚假账户（spam accounts）比例是否如公司所称的低于5%。7月8日，马斯克正式通知Twitter将终止收购协议。Twitter随即向特拉华州衡平法院提起诉讼，要求马斯克完成交易。法院定于10月17日开庭审理。 在审判前夕，马斯克于10月4日突然反转，表示将按原价完成收购。分析认为，马斯克反悔的原因是：他在法庭上胜诉的可能性很低——收购协议中的条款对他非常不利；如果败诉，他不仅需要支付10亿美元的"分手费"，还可能被法院强制完成交易；Twitter的股价在并购期间下跌，440亿美元的报价已经高于市',
