    description: '2023年10月13日，微软以约690亿美元完成对游戏公司动视暴雪的收购，这是微软历史上最大的收购，也是科技行业最大的并购交易之一。这笔交易从2022年1月18日宣布到最终完成，历时近21个月，经历了美国、欧盟和英国监管机构的严格审查，一度因英国竞争与市场管理局（CMA）的阻止而濒临失败。 微软收购动视暴雪的战略逻辑是加强其在游戏行业的地位。动视暴雪拥有《使命召唤》、《魔兽世界》、《糖果传奇》等顶',
    context: '级游戏IP，月活用户超过4亿。微软CEO萨蒂亚·纳德拉认为，游戏是微软消费者战略的核心，收购动视暴雪将使微软成为全球收入第三大的游戏公司（仅次于腾讯和索尼），并为其Xbox Game Pass订阅服务提供强大的内容库。 监管审查的焦点是《使命召唤》IP的独占性问题。美国联邦贸易委员会（FTC）、欧盟委员会和英国CMA都担心，微软可能将《使命召唤》变为Xbox和PC独占，损害PlayStation和任天堂平台的玩家利益。FTC于2022年12月提起诉讼试图阻止收购，但2023年7月被联邦法院驳回。欧盟委员会在2023年5月有条件批准了收购，条件是微软承诺向竞争对手提供10年的《使命召唤》授权。 最大的障碍来自英国CMA。2023年4月，CMA以云游戏市场的竞争担忧为由阻止了收购，这是CMA首次阻止全球性科技并购。然而，微软通过将动视暴雪的云游戏权利出售给法国游戏公司Ubisoft（育碧）来解',
