    title: '2008年摩根大通并购贝尔斯登',
    description: '2008年3月16日，在美联储的强力推动下，摩根大通以约2.36亿美元收购了濒临破产的投行贝尔斯登，每股收购价仅2美元——而贝尔斯登在2007年初的股价曾高达170美元。美联储为交易提供了约290亿美元的融资支持，用于购买贝尔斯登的流动性较差的资产。这是2008年金融危机中第一起重大救助事件，也开创了"大而不能倒"的争议先例。 贝尔斯登的危机始于2007年夏季。作为美国最大的抵押贷款支持证券（MB',
    context: 'S）交易商之一，贝尔斯登旗下的两只对冲基金因大量持有次贷相关证券而崩溃，投资者损失超过16亿美元。此后，市场对贝尔斯登的信心持续恶化。2008年3月10日至14日，贝尔斯登遭遇了类似银行挤兑的流动性危机——客户和交易对手纷纷撤回资金，现金储备从约180亿美元骤降至不足20亿美元。 3月14日，贝尔斯登向美联储寻求紧急援助。美联储通过摩根大通向贝尔斯登提供了28天的紧急贷款，但市场认为这只是权宜之计。3月15日至16日周末，在美联储和财政部的协调下，摩根大通同意收购贝尔斯登。最初的收购价为每股2美元，后因贝尔斯登股东强烈反对而提高至10美元。美联储同意为贝尔斯登约300亿美元的困难资产提供融资支持——如果这些资产产生损失，前10亿美元由摩根大通承担，其余由美联储承担。 贝尔斯登的员工遭受了巨大损失。公司约14000名员工持有大量贝尔斯登股票，许多人的退休储蓄因此蒸发。CEO艾伦·施瓦茨（Al',
