    difficulty: 3,
    title: '2008年巴菲特投资高盛',
    description: '2008年9月23日，在雷曼兄弟倒闭仅一周后、全球金融体系风雨飘摇之际，沃伦·巴菲特旗下的伯克希尔·哈撒韦宣布向高盛投资50亿美元，购买其优先股，年股息率10%，同时获得认股权证，可在五年内以每股115美元的价格购买50亿美元普通股。巴菲特的投资被市场解读为对高盛和金融体系的"信任投票"，也成为了"在别人恐惧时贪婪"的经典案例。 巴菲特投资高盛的时机极为大胆。2008年9月15日雷曼兄弟倒闭后，全',
    context: '球金融市场陷入恐慌。高盛和摩根士丹利的股价大幅下跌，信用违约互换利差飙升，市场担心它们可能成为下一个倒下的投行。9月21日，高盛和摩根士丹利获准转型为银行控股公司，获得了美联储的紧急流动性支持。9月23日，巴菲特宣布投资高盛，这一消息立即提振了市场信心。 巴菲特的投资条件极为优厚。50亿美元的优先股每年支付10%的股息，即5亿美元——这意味着高盛每年仅向巴菲特支付股息就需要5亿美元。认股权证则赋予了巴菲特在五年内以每股115美元购买50亿美元高盛普通股的权利。如果高盛股价上涨，巴菲特将获得巨大的额外收益。 2011年3月，高盛以56亿美元回购了巴菲特的优先股（包括5亿美元股息和10亿美元溢价），结束了每年5亿美元的股息负担。2013年10月，巴菲特行使了认股权证，以约115美元的价格获得了约1300万股高盛普通股（通过现金结算方式），当时高盛股价约160美元，巴菲特从认股权证中获利约20亿',
