    description: '2006年6月25日，印度钢铁大亨拉克希米·米塔尔（Lakshmi Mittal）旗下的米塔尔钢铁公司以约269亿欧元（约330亿美元）收购了欧洲钢铁巨头安赛乐（Arcelor），创建了全球最大的钢铁公司安赛乐米塔尔（ArcelorMittal），年产量超过1亿吨，占全球钢铁产量的约10%。这是当时全球钢铁行业最大的并购交易，也是新兴市场企业收购发达国家企业的标志性事件。 并购战始于2006年1月',
    context: '27日，米塔尔向安赛乐发出了敌意收购要约。安赛乐管理层强烈抵制，CEO居伊·多莱（Guy Dollé）公开贬低米塔尔，称其产品为"香水"与"古龙水"的区别，暗示米塔尔的产品质量低劣。安赛乐采取了多种防御措施，包括引入俄罗斯寡头莫尔达绍夫作为"白衣骑士"，以及向西班牙合作伙伴出售部分资产以稀释米塔尔的持股比例。 然而，米塔尔通过提高报价和直接与安赛乐股东沟通，逐步赢得了支持。最终报价从最初的约186亿欧元提高至约269亿欧元，溢价约49%。6月25日，安赛乐董事会接受了米塔尔的报价，6月30日，安赛乐股东以约92%的赞成票批准了交易。 安赛乐米塔尔的合并创造了全球钢铁行业的巨无霸，但也面临整合挑战。米塔尔承诺的协同效应（约16亿美元的年度成本节约）部分实现，但文化整合和工会关系管理比预期更困难。2008年金融危机后，全球钢铁需求大幅下降，安赛乐米塔尔的股价从2008年的约100美元跌至200',
