    description: '2020年12月1日，企业软件公司Salesforce宣布以约277亿美元收购企业通讯平台Slack，这是Salesforce历史上最大的收购。这笔交易发生在新冠疫情期间，远程办公需求激增的背景下，Salesforce希望通过收购Slack来挑战微软在办公协作领域的主导地位。 Salesforce收购Slack的战略逻辑是构建"企业操作系统"。Salesforce是客户关系管理（CRM）软件的领导',
