    title: '2004年摩根大通并购美一银行',
    description: '2004年1月14日，摩根大通宣布以约580亿美元收购芝加哥的美一银行（Bank One），这是当时银行业最大的并购交易之一。这笔交易使摩根大通成为美国第二大银行（仅次于花旗集团），也标志着杰米·戴蒙（Jamie Dimon）重返摩根大通——他后来成为CEO，将摩根大通打造为全球最大和最赚钱的银行之一。 并购的背景是2000年代初银行业的整合浪潮。1999年《格拉姆-利奇-布利利法案》废除了《格拉',
    context: '斯-斯蒂格尔法案》对商业银行和投资银行分业经营的限制，推动了银行业与证券业的整合。摩根大通在2000年由J.P.摩根与大通曼哈顿银行合并而成，但在零售银行业务方面相对薄弱。美一银行是美国第六大银行，在中西部和西南部拥有强大的零售银行网络，但其投资银行业务较弱。 并购的关键人物是杰米·戴蒙。戴蒙曾是花旗集团CEO桑迪·威尔的得力助手，但在1998年被威尔解雇。2000年，戴蒙成为美一银行CEO，成功扭转了这家陷入困境的银行。摩根大通CEO威廉·哈里森（William Harrison）邀请戴蒙加入合并后的公司担任总裁，并约定戴蒙将在2005年接任CEO。 合并于2004年7月完成。摩根大通获得了美一银行约1800家分行和强大的零售存款基础，美一银行则获得了摩根大通的投资银行和资产管理能力。合并后的摩根大通拥有约1.1万亿美元资产，成为美国第二大银行。 戴蒙于2005年12月接任CEO，此后领',
