    id: 'case_150',
    category: '并购',
    difficulty: 3,
    title: '2024年新日铁收购美国钢铁争议',
    description: '2023年12月18日，日本最大钢铁公司新日铁（Nippon Steel）宣布以约149亿美元收购美国钢铁公司（U.S. Steel），这一交易立即引发了美国政界和工会的强烈反对，成为外国投资与国家安全、产业政策和选举政治交织的典型案例。2025年1月，美国总统拜登以国家安全为由正式阻止了这笔交易。 美国钢铁公司是美国工业的象征性企业，由安德鲁·卡内基于1901年创立，曾是美国最大的公司和全球最大',
    context: '的钢铁生产商。然而，经过一个多世纪的衰退，美国钢铁在2023年的粗钢产量仅约1450万吨，排名美国第三，远落后于纽柯钢铁（Nucor）和克利夫兰-克利夫斯（Cleveland-Cliffs）。公司面临设备老化、成本高企和竞争力下降等问题，一直在寻求买家。 新日铁的收购报价为每股55美元，较公告前股价溢价约40%，总价值约149亿美元。新日铁承诺保留美国钢铁的名称和总部（匹兹堡），履行现有劳动合同，并投资约27亿美元升级设备。新日铁认为，收购将使其全球年产能达到约8600万吨，成为全球第二大钢铁公司（仅次于宝武钢铁），并扩大其在美国市场的份额。 然而，交易面临多方反对。美国钢铁工人联合会（USW）强烈反对，担心日本公司可能削减就业和投资；民主党参议员约翰·费特曼和鲍勃·凯西（均来自宾夕法尼亚州）公开反对；共和党参议员J.D.万斯（后成为副总统）也反对外国收购美国钢铁公司。2024年大选期间，',
