    id: 'case_155',
    category: '金融史',
    difficulty: 3,
    title: '2018年先买后付（BNPL）兴起',
    description: '2018年至2021年，"先买后付"（Buy Now, Pay Later, BNPL）模式在全球范围内迅速兴起，成为金融科技领域最热门的赛道之一。以瑞典的Klarna、澳大利亚的Afterpay和美国的Affirm为代表的BNPL公司，为消费者提供了一种简单、透明的分期付款方式——在购物时将付款分为3-4期，通常免息，审批即时完成。BNPL的兴起反映了年轻一代对传统信用卡的不满和对更灵活支付方式',
    context: '的需求。 BNPL的商业模式核心是向商家收费而非向消费者收费。BNPL公司向合作商家收取约2-6%的交易手续费（高于信用卡的约1.5-3%），作为交换，商家获得了更高的转化率和客单价。数据显示，接入BNPL后，商家的转化率平均提高20-30%，客单价提高40-60%。消费者则享受了免息分期和便捷的支付体验。 BNPL在疫情期间加速增长。2020年至2021年，Klarna的估值从106亿美元飙升至456亿美元；Afterpay被Square（后更名为Block）以290亿美元收购；Affirm在2021年1月上市，市值一度超过230亿美元。BNPL的快速增长吸引了大量竞争者，包括苹果（Apple Pay Later）、PayPal（Pay in 4）和传统银行也推出了类似产品。 然而，BNPL也引发了监管关注。批评者指出，BNPL的便捷性可能导致消费者过度消费和过度负债——特别是年轻和低收',
