    category: '金融史',
    difficulty: 3,
    title: '2006年LendingClub P2P借贷',
    description: '2006年，LendingClub在美国成立，成为全球P2P（点对点）借贷行业的先驱之一。LendingClub的核心理念是利用互联网平台直接连接借款人和投资者，绕过传统银行中介，降低借贷成本，提高投资者收益。LendingClub在2014年上市时估值约85亿美元，是当时金融科技领域最大的IPO之一。然而，P2P借贷模式在经历短暂繁荣后面临了严峻挑战，LendingClub自身也在2016年因丑',
    context: '闻而陷入困境。 LendingClub的运作模式经历了演变。最初，它采用纯P2P模式——借款人在平台上发布借款需求，投资者直接选择并资助借款。然而，SEC认为这种模式涉及证券发行，要求LendingClub注册。2008年，LendingClub调整为"平台+银行"模式——借款人的贷款由WebBank发放，然后LendingClub将贷款份额出售给投资者。这一模式解决了合规问题，但也使LendingClub更像是证券化平台而非真正的P2P。 P2P借贷在2008年金融危机后获得了发展动力。银行收紧了信贷标准，大量消费者和小企业无法获得传统银行贷款，转向P2P平台。LendingClub的贷款发放量从2009年的约1亿美元增长至2015年的约84亿美元。然而，快速增长也带来了风险控制问题——LendingClub的贷款质量在2014年至2015年间恶化，逾期率上升。 2016年5月，Lend',
