    title: '2009年Square移动支付',
    description: '2009年，Twitter联合创始人杰克·多西（Jack Dorsey）创立了Square公司，推出了一款可以插入智能手机耳机插孔的小型读卡器，使小商户和个人能够随时随地接受信用卡支付。Square的诞生解决了美国小微企业接受卡支付的痛点——传统POS终端成本高、申请流程复杂、审批周期长，许多小商户只能接受现金。Square通过简化申请流程、降低硬件成本和提供透明费率，迅速赢得了小微商户市场。 S',
    context: 'quare读卡器的硬件设计简洁优雅——一个白色的小方块（square），可以免费获取或以极低价格购买。商户只需将读卡器插入iPhone或Android手机的耳机插孔，下载Square Register应用，即可开始接受信用卡支付。Square的费率结构简单透明——每笔刷卡交易收取2.6%加10美分，手动输入交易收取3.5%加15美分，没有月费、年费或隐藏费用。 Square的成功得益于其精准的市场定位和卓越的产品设计。传统支付处理商忽视小微商户市场——这些商户的交易量小、服务成本高、利润率低。Square通过技术手段（智能手机替代POS终端、云计算替代本地服务器）大幅降低了服务成本，使小微商户市场变得有利可图。2011年，Square推出了Square Wallet（后更名为Square Cash，即Cash App），进入消费者支付领域。 2015年11月，Square在纽约证券交易所上',
