    id: 'case_159',
    category: '银行',
    difficulty: 3,
    title: '2017年开放银行（Open Banking）兴起',
    description: '2018年1月13日，英国正式实施了开放银行（Open Banking）法规，要求英国九大银行（包括巴克莱、汇丰、劳埃德、桑坦德等）向经授权的第三方提供商开放客户数据，通过标准化的API接口允许客户安全地共享其银行账户信息。英国是第一个强制实施开放银行的主要经济体，这一举措被视为全球银行业数字化转型的重要里程碑，也引发了关于数据所有权、金融竞争和消费者保护的深刻讨论。 开放银行的推动力来自英国竞争',
    context: '与市场管理局（CMA）2016年的一项调查。CMA发现，英国零售银行市场缺乏有效竞争——老牌银行占据了约85%的个人经常账户市场份额，客户转换银行的比例仅为约3%。CMA认为，通过强制银行开放数据，可以降低客户转换成本，促进新进入者竞争，最终使消费者受益。 开放银行的核心机制是API（应用程序编程接口）标准。银行必须提供标准化的API，允许第三方（如金融科技公司、比价网站等）在客户授权的情况下访问其账户数据，包括余额、交易记录和支付功能。客户可以授权第三方应用（如Yolt、Moneyhub等）汇总多个银行账户的信息，或使用第三方支付服务直接从银行账户付款，无需通过Visa或Mastercard网络。 开放银行在英国的实施初期进展缓慢。到2019年底，仅有约100万用户使用了开放银行服务，远低于预期。银行在API开发上进展不一，部分银行的API稳定性不足。消费者对数据安全的担忧也限制了采纳率',
