    title: '2015年蚂蚁金服成立',
    description: '2015年，阿里巴巴集团将旗下的支付宝及相关金融业务整合为蚂蚁金服（后更名为蚂蚁集团），标志着中国金融科技从单一支付产品向综合金融平台的跨越。蚂蚁金服旗下拥有支付宝（支付）、余额宝（理财）、蚂蚁财富（基金代销）、网商银行（小微企业贷款）、芝麻信用（信用评估）、花呗/借呗（消费信贷）等业务，形成了覆盖支付、理财、信贷、保险和信用的完整金融生态。 蚂蚁金服的核心竞争力在于其数据驱动的风控能力。芝麻信用',
    context: '利用支付宝的支付数据、淘宝的消费数据和公共数据，为用户建立信用评分，覆盖了传统征信系统未覆盖的大量人群。网商银行利用电商交易数据和算法模型，为小微企业提供"310"贷款——3分钟申请、1秒钟放款、0人工干预，不良贷款率控制在约2%以下，远低于传统银行的小微贷款不良率。 蚂蚁金服的商业模式是"平台+生态"。它不直接提供大部分金融服务，而是作为平台连接用户和金融机构——余额宝对接天弘基金，蚂蚁财富代销基金公司产品，蚂蚁保代销保险产品。蚂蚁金服从交易中收取技术服务费，而非利差收入。这一模式使蚂蚁金服能够快速扩展产品线，同时保持轻资产运营。 2020年10月，蚂蚁集团宣布在上海证券交易所科创板和香港联交所同步上市，估值约3130亿美元，有望成为全球最大的IPO。然而，2020年10月24日，马云在外滩金融峰会上发表演讲，批评传统银行是"当铺思维"，监管机构"管得太死"。这番言论激怒了监管层。11月',
