    id: 'case_163',
    category: '交易',
    difficulty: 3,
    title: '2002年ImClone内幕交易案（玛莎·斯图尔特）',
    description: '2001年12月27日，美国生活方式品牌大亨玛莎·斯图尔特（Martha Stewart）在ImClone公司CEO塞缪尔·瓦克萨尔（Samuel Waksal）的暗示下，提前卖出了约4000股ImClone股票，避免了约4.5万美元的损失。次日，美国食品药品监督管理局（FDA）宣布拒绝ImClone的抗癌药物Erbitux上市申请，股价暴跌16%。这一内幕交易案虽然金额不大，但因涉及名人而引发了',
    context: '广泛关注，也成为SEC执法行动的标志性案例。 瓦克萨尔在得知FDA将拒绝Erbitux上市申请后，立即通知家人和朋友卖出ImClone股票。他的女儿和父亲在12月26日至27日卖出了全部持股。斯图尔特是瓦克萨尔的好友，她的经纪人彼得·巴卡诺维奇也是瓦克萨尔的经纪人。巴卡诺维奇在12月27日给斯图尔特留了一条消息，暗示ImClone股价将下跌。斯图尔特随后卖出了约4000股ImClone股票。 2002年6月，SEC和司法部对斯图尔特展开调查。斯图尔特声称，她与巴卡诺维奇事先约定了止损策略——如果ImClone股价跌破60美元就卖出。然而，调查发现，这一"止损策略"是事后编造的——斯图尔特和巴卡诺维奇在调查开始后才达成一致。斯图尔特还修改了电话记录以支持其虚假陈述。 2004年3月，斯图尔特被判定犯有妨碍司法公正、共谋和虚假陈述罪，被判处五个月监禁（在联邦监狱服刑）和五个月居家监禁。瓦克萨尔',
