    id: 'case_164',
    category: '欺诈',
    difficulty: 4,
    title: '2012年LIBOR操纵丑闻',
    description: '2012年6月，巴克莱银行同意向美国和英国监管机构支付约4.5亿美元罚款，了结对其操纵伦敦银行间同业拆借利率（LIBOR）的调查。LIBOR是全球最重要的基准利率之一，影响约300万亿美元的金融合约，包括房贷、衍生品和企业贷款。LIBOR操纵丑闻是金融行业历史上最严重的市场操纵案件之一，严重损害了公众对金融体系的信任。 LIBOR的确定机制存在根本性缺陷。每天上午，16家银行向英国银行家协会（BB',
    context: 'A）报告其借款利率，剔除最高和最低的四个报价后取平均值，即为当天的LIBOR。这一机制依赖于银行诚实报告其真实借款成本，但实际上银行有强烈的动机操纵报价——如果银行报告的LIBOR较低，市场会认为其信用风险较低，有利于其融资；交易员也可以通过操纵LIBOR来使其衍生品头寸获利。 巴克莱的调查揭示了两种操纵模式。第一种是"利润驱动型"操纵——衍生品交易员通过要求报价人员调整LIBOR报价来使其衍生品头寸获利。交易员在内部邮件和即时消息中直接要求报价人员"调高"或"调低"报价，有时甚至指定具体的调整幅度。第二种是"声誉驱动型"操纵——2007年至2009年金融危机期间，巴克莱故意低报其借款利率，以避免显得比其他银行更脆弱。其他银行也在低报利率，形成了"集体低报"的局面。 巴克莱的调查文件中包含了大量令人震惊的内部通信。一位交易员写道："如果可以的话，今天请把三个月LIBOR设高一点，我有一个大',
