    id: 'case_165',
    category: '欺诈',
    difficulty: 4,
    title: '2003年共同基金择时交易丑闻',
    description: '2003年9月，纽约州总检察长埃利奥特·斯皮策（Eliot Spitzer）揭露了共同基金行业广泛存在的择时交易（market timing）和延迟交易（late trading）行为，涉及多家知名基金公司，包括Putnam Investments、Alliance Capital、Strong Capital和Janus Capital等。这一丑闻动摇了投资者对共同基金行业的信心，也暴露了基金公',
    context: '司为追求资产管理规模而牺牲长期投资者利益的利益冲突。 延迟交易是最严重的违规行为。根据SEC规定，共同基金的申购和赎回必须以当天下午4点（纽约时间）的收盘净值计算。然而，一些基金公司允许特定投资者在4点之后下单，仍以当天的收盘净值交易——这相当于允许投资者在已知收盘价的情况下进行交易，是明确的违法行为。例如，如果某科技股在盘后发布利好消息，投资者可以在4点后买入持有该股票的基金，以当天较低的净值买入，第二天以更高的净值卖出，获取无风险利润。 择时交易虽然不违法，但违反了基金公司自己的政策。择时交易者利用不同市场之间的时差和价格滞后，频繁买卖基金份额以获取套利利润。例如，国际基金通常使用外国市场的收盘价计算净值，但这些价格可能已经过时（亚洲市场在美国开盘前数小时已关闭）。择时交易者可以在美国市场开盘后，根据当天亚洲市场的走势，买入或卖出国际基金，利用过时的净值获取利润。这种行为增加了基金的交',
