    title: '2020年Wirecard做空与操纵',
    description: '2020年6月，德国支付公司Wirecard在承认其资产负债表上19亿欧元的现金"可能不存在"后，于6月25日申请破产。这一事件是德国自二战以来最大的企业欺诈案，也是欧洲金融监管的巨大失败——德国金融监管局（BaFin）在多年间无视做空者的警告，反而对质疑Wirecard的分析师和记者进行调查。Wirecard的崩溃不仅造成了约数十亿欧元的投资者损失，还严重损害了德国作为金融中心的声誉。 Wire',
    context: 'card成立于1999年，最初是一家处理在线赌博和成人网站支付的公司，后来转型为数字支付处理商，声称在亚洲、南美和东欧等新兴市场提供支付服务。Wirecard的股价从2008年的约10欧元上涨至2018年的约200欧元，市值一度超过240亿欧元，被纳入德国DAX指数，与大众、西门子等蓝筹股并列。 然而，Wirecard的商业模式存在根本性问题。其大部分收入和利润来自所谓的"第三方合作伙伴"（TPA）——Wirecard声称这些合作伙伴在亚洲等地区为其处理支付，并向Wirecard支付分成。然而，做空者和记者多年来质疑这些TPA是否真实存在。2019年1月，英国《金融时报》报道了Wirecard在新加坡办公室的会计违规行为，但BaFin的反应不是调查Wirecard，而是对《金融时报》提起刑事诉讼，指控其操纵市场。 2020年6月17日，Wirecard推迟发布年报，承认审计师安永无法确认其',
