    title: '2019年电报TON项目SEC诉讼',
    description: '2019年10月11日，美国证券交易委员会（SEC）对Telegram集团及其TON（The Open Network）区块链项目提起紧急诉讼，指控其通过出售"Gram"代币筹集的17亿美元构成未经注册的证券发行。这一案件是SEC对加密货币项目执法的标志性案例，也明确了美国证券法对代币发行的适用标准——即使代币在发行时不被视为证券，如果购买者期望通过他人的努力获得利润，仍可能构成投资合同（即证券）',
    context: '。 Telegram由俄罗斯企业家帕维尔·杜洛夫（Pavel Durov）于2013年创立，是一款以隐私和安全著称的即时通讯应用，全球月活用户超过5亿。2018年初，Telegram宣布将开发TON区块链和Gram代币，打造一个去中心化的互联网生态系统。2018年1月至3月，Telegram通过两轮私募向约171名投资者出售了约29亿个Gram代币，筹集了17亿美元，投资者包括俄罗斯富豪、硅谷风投和中东主权基金。 SEC的诉讼核心论点是：Gram代币的发行构成"投资合同"，因此是证券，需要在SEC注册或获得豁免。SEC认为，Gram的购买者投资于TON项目，期望通过Telegram团队的开发努力使Gram升值——这满足了Howey测试的所有要素（投资于共同企业、期望利润、依赖他人努力）。Telegram辩称，Gram是货币而非证券，购买者获得的是可消费的数字资产而非投资合同。 2019年1',
