    difficulty: 4,
    title: '2002年泰科国际丑闻',
    description: '2002年，美国多元化制造企业泰科国际（Tyco International）的CEO丹尼斯·科兹洛夫斯基（Dennis Kozlowski）和CFO马克·斯沃茨（Mark Swartz）被指控通过大规模财务欺诈和挪用公司资金，造成约6亿美元的损失。泰科丑闻与安然、世通并列为2000年代初美国企业丑闻的"三大案"，直接推动了2002年《萨班斯-奥克斯利法案》的通过。 科兹洛夫斯基1992年成为泰科',
    context: 'CEO，此后通过超过700次收购将泰科从一家中等规模的公司打造为年收入超过360亿美元的跨国集团。他被誉为"并购大师"，其激进的收购策略被华尔街追捧。然而，在光鲜的外表下，科兹洛夫斯基和斯沃茨系统性地挪用公司资金用于个人消费。 挪用的方式令人瞠目。科兹洛夫斯基用公司资金购买了价值6000美元的浴帘、15000美元的狗伞架、6300美元的针线篮和200万美元的生日派对（包括冰雕米开朗基罗的大卫和伏特加喷泉）。他还通过"关键员工贷款"项目从公司借款，然后由董事会豁免偿还。科兹洛夫斯基在纽约第五大道的公寓装修花费了公司约3000万美元，包括价值8000美元的壁炉屏风和5000美元的毛巾架。 财务欺诈方面，科兹洛夫斯基和斯沃茨通过不当确认收入、隐瞒关联交易和虚假申报收购价格来美化财务报表。他们在收购中将部分收购价格记为"内部开发无形资产"，避免在利润表中确认商誉摊销费用。他们还通过"闪电"收购——',
