    id: 'case_170',
    category: '金融史',
    difficulty: 3,
    title: '2005年瑞富公司破产',
    description: '2005年10月，全球最大的非交易所衍生品经纪商之一瑞富公司（Refco）在IPO后仅两个月即宣布破产，披露其CEO菲利普·本内特（Phillip Bennett）隐瞒了约4.3亿美元的债务。瑞富的破产是2000年代最令人震惊的企业欺诈案之一，也是IPO尽职调查失败的典型案例——多家顶级投行和审计师未能发现隐藏的债务。 瑞富由托马斯·迪特默（Thomas Dittmer）于1969年创立，最初是一',
    context: '家小型商品经纪商，后来发展成为全球最大的衍生品经纪商之一，在商品、外汇和固定收益领域拥有大量客户。2004年，瑞富的营业收入约12亿美元，净利润约1.7亿美元。2005年8月，瑞富在纽约证券交易所上市，IPO融资约5.83亿美元，市值约35亿美元。 然而，瑞富的财务报表中隐藏着一个巨大的秘密。本内特通过关联公司Refco Group Holdings, Inc.（RGHI）向瑞富借款约4.3亿美元，用于弥补其个人投资损失。每个季度末，本内特将这笔债务从瑞富的资产负债表上暂时转移，使财务报表显示正常；季度结束后，再将债务转回。这种"窗口粉饰"（window dressing）手法使瑞富的审计师和IPO承销商未能发现隐藏的债务。 2005年10月10日，瑞富披露了本内特的隐瞒行为，宣布本内特已偿还了4.3亿美元（通过向第三方借款），但公司同时宣布本内特被解雇。消息公布后，瑞富股价暴跌，客户纷纷',
