    id: 'case_172',
    category: '欺诈',
    difficulty: 4,
    title: '2004年AIG会计丑闻',
    description: '2004年至2005年，全球最大的保险公司美国国际集团（AIG）爆发了严重的会计丑闻，被指控通过虚假再保险交易和不当会计处理虚增约39亿美元的收益。AIG的传奇CEO莫里斯·格林伯格（Maurice "Hank" Greenberg）被迫辞职，公司支付了16亿美元的罚款和解金。AIG丑闻是2000年代初企业欺诈浪潮中的重要案例，也揭示了再保险交易被用于操纵财务报表的手法。 AIG丑闻的核心是通用再',
    context: '保险公司（General Re）与AIG之间的一笔再保险交易。2000年底，格林伯格要求通用再保险向AIG提供5亿美元的再保险保障，以增加AIG的损失准备金，使财务报表看起来更健康。通用再保险（伯克希尔·哈撒韦的子公司）同意了这一交易，但双方秘密约定，AIG将通过投资协议将5亿美元返还给通用再保险——这意味着这笔再保险实际上没有转移任何风险，纯粹是为了粉饰财务报表。 根据会计准则，再保险交易只有在转移了显著风险的情况下才能在财务报表中确认。由于这笔交易没有转移风险，AIG不应将其作为再保险入账。然而，AIG将其记录为再保险收入，虚增了约5亿美元的损失准备金和约3.9亿美元的税前收入。 2005年2月，纽约州总检察长斯皮策和SEC对AIG展开调查。3月，AIG承认了会计违规，宣布将重述此前五年的财务报表，减少约39亿美元的股东权益。格林伯格在3月14日被解雇，结束了他在AIG长达37年的统治',
