    id: 'case_173',
    category: '金融史',
    difficulty: 3,
    title: '2008年AIG救助',
    description: '2008年9月16日，美联储宣布向AIG提供850亿美元的紧急贷款，以防止这家全球最大保险公司的倒闭引发系统性金融风险。此后，政府救助总额扩大至约1820亿美元，美国政府获得了AIG约80%的股权。AIG救助是2008年金融危机中规模最大的政府干预行动之一，也是"大而不能倒"问题最极端的体现——AIG的倒闭将通过其庞大的衍生品敞口对全球金融体系造成灾难性连锁反应。 AIG危机的核心是其金融产品部门',
    context: '（AIGFP）出售的大量信用违约互换（CDS）。AIGFP由约瑟夫·卡萨诺（Joseph Cassano）领导，自2000年代初开始大量出售CDS，为抵押贷款支持证券（MBS）和担保债务凭证（CDO）提供信用保护。截至2007年底，AIGFP的CDS名义金额超过5000亿美元，其中约780亿美元与次贷相关证券挂钩。AIGFP收取了可观的CDS保费，但由于CDS不需要持有资本准备金（只要AIG的信用评级足够高），这些交易几乎没有占用任何资本。 2007年至2008年，随着次贷市场恶化，AIGFP的CDS头寸开始产生巨额亏损。根据CDS合约，AIG需要向交易对手方（包括高盛、法兴银行、德意志银行等）支付大量保证金。2008年前三个季度，AIG的CDS亏损超过250亿美元。9月15日雷曼兄弟倒闭后，AIG的信用评级被下调，触发了更多保证金要求，AIG无法满足。 9月16日，美联储在雷曼倒闭仅一天',
