    title: '2007年贝尔斯登对冲基金倒闭',
    description: '2007年6月至7月，贝尔斯登旗下的两只对冲基金——High-Grade Structured Credit Strategies Fund和High-Grade Structured Credit Strategies Enhanced Leverage Fund——因大量持有次贷相关证券而崩溃，投资者损失超过16亿美元。这两只基金的倒闭被广泛视为2007-2008年全球金融危机的序幕，也是次贷',
    context: '市场问题的首次大规模暴露。 两只基金由贝尔斯登的资产管理子公司管理，由基金经理拉尔夫·乔菲（Ralph Cioffi）和马修·坦宁（Matthew Tannin）运营。基金的投资策略是：购买高评级的次贷支持证券（AAA/AA级），同时利用杠杆放大收益。Enhanced Leverage基金的杠杆率高达10倍以上——每1美元的权益资本对应超过10美元的资产。在市场正常时，这种策略可以产生稳定但适中的超额收益；但在市场下行时，杠杆将放大损失。 2007年初，次贷市场开始恶化。次贷违约率上升，次贷支持证券的价格开始下跌。两只基金的净值在3月至4月间下降了约20%。6月，一只基金无法满足追加保证金要求，贝尔斯登被迫向其提供32亿美元的紧急贷款——但随后又收回了贷款。6月底，贝尔斯登通知投资者，High-Grade基金已几乎无价值，Enhanced Leverage基金损失了超过90%的价值。 基金',
