    id: 'case_178',
    category: '金融史',
    difficulty: 3,
    title: '2011年保尔森基金做空次贷',
    description: '2006年至2007年，约翰·保尔森（John Paulson）旗下的保尔森基金通过做空次贷相关证券，获得了约150亿美元的利润，保尔森本人获利约40亿美元，成为华尔街历史上最成功的单笔交易之一。保尔森的做空策略被迈克尔·刘易斯在《大空头》中详细描述，也引发了关于"做空是否有益社会"的伦理讨论。 保尔森做空次贷的逻辑始于2005年。他的研究员保罗·佩莱格里尼（Paolo Pellegrini）分析',
    context: '了次贷市场的数据，发现次贷违约率正在上升，而次贷支持证券的定价并未反映这一风险。更重要的是，他们发现CDS为做空次贷提供了完美的工具——通过购买CDS保护，他们可以在次贷证券违约时获得赔付，而成本仅为每年约1-2%的保费。 2006年初，保尔森开始大量购买次贷CDS保护。他创建了专门的基金——保尔森信用机会基金——来执行这一策略。到2006年底，他已持有约250亿美元名义金额的次贷CDS头寸。2007年，随着次贷市场恶化，这些CDS头寸的价值急剧上升。ABX指数（追踪次贷证券表现的指数）从2007年初的约100跌至年底的约50，保尔森的CDS头寸产生了巨额利润。 保尔森的成功也引发了争议。2010年，SEC对高盛提起了民事诉讼，指控其在设计一款名为Abacus 2007-AC1的CDO时，允许保尔森选择最差的次贷证券放入CDO，然后做空这些证券，而未向投资者披露保尔森的利益冲突。高盛在20',
