    description: '2015年至2016年，加拿大制药公司Valeant Pharmaceuticals International的商业模式崩塌，股价从2015年8月的约263美元跌至2017年的约10美元，市值蒸发超过900亿美元。Valeant的崩塌是私募股权式运营模式在制药行业失败的标志性案例，也引发了关于药品定价、企业治理和会计操纵的广泛讨论。 Valeant的商业模式由CEO迈克尔·皮尔森（Michael',
    context: ' Pearson）设计，核心是"收购+涨价"——收购拥有专利药品的小型制药公司，然后大幅提高药品价格。2013年至2015年，Valeant收购了数十家公司，包括Bausch & Lomb（眼保健）、Salix Pharmaceuticals（胃肠病）和Sprout Pharmaceuticals（女性性欲药物）等。每次收购后，Valeant都会大幅提高药品价格——有些药品的价格涨幅超过500%甚至1000%。 Valeant还通过一家名为Philidor Rx Services的特殊药房来推动销售。Philidor是一家"专属药房"——只销售Valeant的药品。Valeant通过Philidor绕过了传统药房的通用药替代机制，确保患者只能获得Valeant的高价品牌药。Valeant还通过Philidor的会计处理虚增了收入——将Philidor的销售额全额计入Valeant收入，而非',
