    description: '2019年6月，英国最知名基金经理之一尼尔·伍德福德（Neil Woodford）的旗舰基金——Woodford Equity Income Fund——被暂停赎回，因为大量投资者要求撤资，而基金持有的许多资产无法及时变现。2019年10月，基金被宣布清算，约30万投资者遭受了重大损失。Woodford基金的崩溃是英国投资行业近年来最严重的信任危机，也暴露了开放式基金流动性管理的根本性问题。 伍德',
    context: '福德是英国最成功的基金经理之一，在景顺（Invesco Perpetual）工作超过25年，管理约330亿英镑的资产，以逆向投资和长期持有著称。2014年，他离开景顺创立了自己的基金公司，Woodford Equity Income Fund在成立后迅速吸引了大量资金，规模一度超过100亿英镑。 然而，伍德福德逐渐偏离了其传统的蓝筹股投资策略，将越来越多的资金投入未上市企业和早期公司。这些投资流动性极差——未上市股票没有公开市场，难以估值和变现。到2019年，基金中约20%的资产是未上市或流动性极差的证券，远超基金招股说明书中允许的比例。伍德福德通过将部分未上市投资转移到另一个基金（Woodford Patient Capital Trust）来规避10%的未上市资产限制，但这一做法的合规性存疑。 2019年5月，肯特郡养老金基金要求从Woodford Equity Income Fund',
