    title: '2021年Melvin Capital做空GameStop巨亏',
    description: '2021年1月，对冲基金梅尔文资本（Melvin Capital）在GameStop逼空事件中遭受了毁灭性打击，1月份亏损约53%，损失超过60亿美元。梅尔文资本的创始人加布·普洛特金（Gabe Plotkin）被迫接受肯·格里芬（Ken Griffin）的Citadel和史蒂夫·科恩（Steve Cohen）的Point72的27.5亿美元紧急注资，但基金最终在2022年5月关闭。梅尔文资本的崩',
    context: '溃是散户投资者集体行动对机构投资者造成最大损失的案例。 梅尔文资本是华尔街最知名的对冲基金之一，管理约125亿美元的资产。普洛特金曾是史蒂夫·科恩的SAC Capital的明星交易员，2014年创立梅尔文资本后，年化回报率约30%，是表现最好的对冲基金之一。2020年底，梅尔文资本大量做空GameStop——这家电子游戏零售商的商业模式被认为已经过时，向数字下载转型的趋势使其实体零售前景黯淡。 然而，梅尔金低估了散户投资者的力量。2021年1月，Reddit论坛WallStreetBets上的散户投资者发现了GameStop的巨大空头头寸，开始大量买入GME股票和看涨期权。随着股价上涨，空头被迫回补，进一步推高股价，形成了经典的"空头挤压"循环。GME股价从1月初的约20美元飙升至1月28日的483美元。 梅尔文资本在1月份损失了约53%的资产。1月25日，Citadel和Point72向',
