    id: 'case_183',
    category: '金融史',
    difficulty: 3,
    title: '2002年萨班斯-奥克斯利法案',
    description: '2002年7月30日，美国总统乔治·W·布什签署了《萨班斯-奥克斯利法案》（Sarbanes-Oxley Act, SOX），这是自1930年代大萧条以来美国最重要的证券法律改革。SOX法案的出台是对2001年至2002年安然、世通等企业丑闻的直接回应，旨在恢复公众对资本市场的信心。法案的核心内容包括：CEO和CFO必须个人认证财务报表的真实性；设立独立的上市公司会计监督委员会（PCAOB）；加强',
    context: '审计师的独立性；强化内部控制要求；加大对证券欺诈的刑事处罚。 SOX法案的背景是2001年至2002年一系列企业丑闻的爆发。安然在2001年12月破产，世通在2002年6月破产，泰科、Adelphia等公司也曝出丑闻。这些丑闻的共同特征是：管理层操纵财务报表、审计师未能独立审计、董事会未能有效监督、分析师的利益冲突导致误导性推荐。公众对资本市场的信心跌至谷底。 SOX法案最著名的条款是第404条，要求上市公司建立和维持有效的内部控制框架，并由外部审计师对内部控制进行审计。404条款的实施成本远超预期——上市公司平均每年花费约120万美元用于404合规，大型公司的成本更高。许多公司抱怨404条款过于繁琐，增加了合规负担，特别是对小型上市公司而言。 SOX法案的影响是深远的。积极方面，上市公司的财务报告质量显著提高，内部控制更加健全，审计师的独立性增强。CEO和CFO对财务报表的个人认证增加了',
