    id: 'case_184',
    category: '金融史',
    difficulty: 3,
    title: '2010年多德-弗兰克法案',
    description: '2010年7月21日，美国总统奥巴马签署了《多德-弗兰克华尔街改革和消费者保护法案》（Dodd-Frank Act），这是自大萧条以来美国最全面的金融监管改革。法案长达2300页，包含16个标题和数百项条款，旨在解决2008年金融危机暴露的监管漏洞，防止危机重演。核心内容包括：设立金融稳定监督委员会（FSOC）；建立有序清算机制；实施沃尔克规则；设立消费者金融保护局（CFPB）；加强衍生品监管。 ',
    context: '沃尔克规则（Volcker Rule）是多德-弗兰克法案最具争议的条款，以美联储前主席保罗·沃尔克命名。该规则禁止银行利用自有资金进行短期专有交易（proprietary trading），并限制银行对对冲基金和私募股权基金的投资。沃尔克认为，享有存款保险和央行流动性支持的银行不应从事高风险交易活动。然而，沃尔克规则的实施面临巨大挑战——如何区分"专有交易"和"做市交易"（market making）在实践中极为困难。最终规则直到2014年才出台，长达71页，附带约900页的补充说明。 消费者金融保护局（CFPB）是法案的另一重要创新。CFPB整合了此前分散在多个机构的消费者保护职能，负责监管抵押贷款、信用卡、学生贷款等消费金融产品。CFPB的首任局长理查德·科德雷（Richard Cordray）积极执法，对多家银行和金融科技公司采取了执法行动，追回了超过120亿美元的消费者赔偿。然而，',
