    id: 'case_186',
    category: '金融史',
    difficulty: 3,
    title: '2012年英国金融监管改革（FCA成立）',
    description: '2013年4月1日，英国实施了金融监管体制的重大改革，废除了金融服务局（FSA），将其职能拆分为审慎监管局（PRA）和金融行为监管局（FCA）。这一改革是对2008年金融危机和后续LIBOR操纵等丑闻的回应，旨在解决FSA"既管审慎又管行为"导致的监管失败。FCA的成立标志着英国监管哲学从"轻触式监管"向"更积极干预"的转变。 FSA的失败被认为是2008年金融危机中英国银行业遭受重创的重要原因之',
    context: '一。FSA在危机前采取了"轻触式监管"（light-touch regulation）理念，认为市场自律和信息披露足以保护消费者和金融稳定。FSA对北岩银行、苏格兰皇家银行等机构的监管严重不足——未能识别其过度杠杆和流动性风险。FSA主席阿代尔·特纳（Adair Turner）在危机后承认，FSA过于关注流程合规而忽视了实质性风险。 新监管架构将审慎监管和行为监管分离。PRA作为英格兰银行的附属机构，负责监管约1500家银行、建筑协会和保险公司，关注其安全性和稳健性。FCA作为独立机构，负责监管约56000家金融公司的行为，关注消费者保护、市场完整性和竞争。这种"双峰"（twin peaks）监管模式借鉴了澳大利亚和荷兰的经验。 FCA在成立后采取了更加积极的执法态度。2013年至2023年，FCA对多家金融机构采取了执法行动，罚款总额超过50亿英镑。重要案例包括：2014年对LIBOR操',
