    title: '2023年美国加密货币监管框架',
    description: '2023年，美国加密货币监管框架经历了重大发展，SEC和CFTC加大了对加密货币行业的执法力度，国会也推进了多项立法提案。2023年的监管行动标志着美国从"监管模糊"向"积极执法"的转变，对全球加密货币行业产生了深远影响。 SEC在2023年采取了多项重大执法行动。2月，SEC与Kraken达成和解，Kraken同意支付3000万美元罚款并关闭其质押即服务（staking-as-a-service',
    context: '）产品，SEC认定Kraken的质押服务构成未注册证券。6月，SEC对币安及其创始人赵长鹏提起诉讼，指控其运营未注册的证券交易所、经纪商和清算机构，以及滥用客户资金。同日，SEC对Coinbase提起诉讼，指控其运营未注册的证券交易所、经纪商和清算机构，并认定多种加密代币为证券。10月，SEC在FTX破产案中推进了资产追回程序。 SEC主席根斯勒的立场是明确的：大多数加密代币构成证券，应遵守证券法；加密货币交易所必须注册或遵守现有规则；DeFi平台也不能逃避监管。根斯勒认为，加密货币行业的"合规成本"不应由投资者承担——"不是规则不明确，而是行业不愿合规"。 CFTC也加强了对加密货币的执法。2023年3月，CFTC对币安提起诉讼，指控其非法运营期货和期权交易。CFTC主席贝纳姆主张，比特币和以太坊等非证券的加密货币应归CFTC监管。 国会方面，2023年多项加密货币立法提案取得进展。7月',
