    id: 'case_191',
    category: '危机',
    difficulty: 5,
    title: '2006年美国次贷危机前兆',
    description: '2006年，美国住房市场在经历了十年的繁荣后开始出现裂缝，房价增速放缓，次贷违约率开始上升，多家次贷机构陷入困境。这些早期信号被大多数市场参与者和监管者忽视，但事后来看，它们是2007-2008年全球金融危机的明确前兆。2006年的次贷危机前兆是金融泡沫破裂前"温水煮青蛙"的典型案例，也揭示了市场共识如何在泡沫中形成并阻碍对风险的识别。 2006年初，美国房价在连续11年上涨后首次出现环比下降。全',
    context: '国房价指数在2006年中期达到峰值，此后开始缓慢下跌。然而，大多数分析师和投资者认为这只是"软着陆"——房价涨幅放缓而非下跌，市场将逐步回归正常。美联储主席伯南克在2006年表示，住房市场的降温是"有序的"，不会对经济产生重大影响。 次贷市场的恶化更为明显。2006年第四季度，次贷的60天以上逾期率从2005年底的约12%上升至约14%。多家次贷机构开始报告亏损：Ownit Mortgage Solutions于2006年12月申请破产；Sebring Capital Partners在2006年底停止运营；ResMae Mortgage于2007年2月申请破产。然而，这些事件被市场视为"个别机构的问题"而非系统性风险的信号。 次贷市场的风险积累源于多个因素。第一，贷款标准持续放松——2004年至2006年间，大量"无收入、无资产"（NINJA）贷款被发放，借款人无需证明收入或资产即可获得',
