    id: 'case_192',
    category: '金融史',
    difficulty: 3,
    title: '2008年两房（房利美、房地美）救助',
    description: '2008年9月7日，美国财政部宣布将房利美（Fannie Mae）和房地美（Freddie Mac）——合称"两房"——置于联邦住房金融局（FHFA）的接管之下，这是美国历史上最大的金融救助行动之一。两房是政府支持企业（GSE），在美国住房金融体系中扮演核心角色——它们购买银行发放的抵押贷款，将其证券化为MBS出售给投资者，并为这些MBS提供信用担保。在危机爆发时，两房拥有或担保了约5.3万亿美元',
    context: '的抵押贷款，占美国住房抵押贷款市场的一半以上。 两房危机的根源是其商业模式的结构性缺陷。作为GSE，两房享有隐性的政府支持——市场普遍认为，如果两房陷入困境，政府不会让其倒闭。这一隐性担保使两房能够以低于纯私营机构的成本融资，但也鼓励了过度冒险。两房利用低成本资金大量持有抵押贷款和MBS，杠杆率极高——2007年底，两房的核心资本仅约830亿美元，而其持有的资产和担保总额超过5万亿美元，杠杆率超过60倍。 2007年至2008年，随着住房市场恶化和次贷违约率上升，两房的资本急剧缩水。2008年第一季度，房利美净亏损21亿美元，房地美净亏损1.51亿美元。两房的股价从2007年初的约60美元跌至2008年9月的约5美元。市场开始质疑两房的偿付能力，如果两房无法继续购买抵押贷款，美国住房市场将面临崩溃。 2008年7月，国会通过了《住房和经济复苏法案》（HERA），授权财政部向两房提供无限量的',
