    title: '2012年西班牙房地产崩盘',
    description: '2012年，西班牙房地产市场的崩盘进入最严重的阶段，房价从2007年的峰值下跌超过35%，约70万套新建住宅无人居住，银行不良贷款率飙升至约11%，失业率超过26%。西班牙房地产崩盘是欧元区金融危机的重要组成部分，也是欧洲房地产泡沫破裂最严重的案例之一。 西班牙房地产泡沫的形成与多个因素有关。加入欧元区后，西班牙享受了历史最低的利率水平，信贷大规模扩张。2000年至2007年间，西班牙房价累计上涨',
    context: '约200%，建筑业的GDP占比从约8%飙升至约14%。银行，特别是地方储蓄银行（Cajas），大量向房地产开发商提供贷款，贷款标准不断放松。外国资本大量流入西班牙的房地产和建筑业，推高了资产价格。 泡沫破裂的过程始于2008年。全球金融危机导致信贷紧缩和需求下降，西班牙房价开始下跌。然而，与美国的次贷危机不同，西班牙的问题更多集中在开发商贷款而非个人住房贷款。西班牙银行向开发商发放了大量贷款——2007年底，开发商贷款余额约4450亿欧元，占银行贷款总额的约25%。当房地产项目无法出售时，开发商无法偿还贷款，银行不良资产激增。 2012年，西班牙银行业的房地产相关不良贷款和问题资产总额估计约1840亿欧元。政府被迫对银行体系进行大规模重组和救助。2012年6月，西班牙向欧盟申请了最高1000亿欧元的银行业救助资金。政府还设立了"坏账银行"SAREB，接管了约900亿欧元的不良房地产资产，以',
