    difficulty: 5,
    title: '2021年中国恒大危机',
    description: '2021年9月，中国最大的房地产开发商恒大集团陷入严重的流动性危机，无法按时偿还约3000亿美元的债务，引发了全球对中国房地产泡沫和金融稳定的担忧。恒大危机是中国房地产行业"高杠杆、高周转、高负债"模式崩塌的标志性事件，也是中国政府推进"去杠杆"政策过程中最严峻的考验。 恒大由许家印于1996年在广州创立，通过"高杠杆、高周转"模式迅速扩张，成为中国销售额最大的房地产开发商。恒大的商业模式核心是：',
    context: '大量预售期房获取现金→用预售款购买更多土地→以土地为抵押获取更多贷款→用贷款开发更多项目→预售更多期房。这一模式在房价持续上涨时可以高速运转，但一旦销售放缓，资金链就会断裂。 2020年8月，中国政府推出了"三道红线"政策，限制高负债房地产企业的融资：剔除预收款后的资产负债率不超过70%、净负债率不超过100%、现金短债比不小于1。恒大三条红线全部触碰，被列为"红档"企业，不得新增有息负债。这直接切断了恒大的融资渠道，使其"借新还旧"的模式无法继续。 2021年9月，恒大公开承认面临"前所未有的困难"，无法保证履行其融资义务。9月23日，一笔约8350万美元的离岸债券利息未能按时支付，构成技术性违约。此后，恒大陆续对多笔美元债券违约。全国各地的恒大项目停工，大量预售购房者担心无法收房，引发了社会稳定风险。 2023年9月，许家印因涉嫌违法犯罪被依法采取强制措施。2024年1月，香港高等法院',
