    id: 'case_195',
    category: '金融史',
    difficulty: 3,
    title: '2020年疫情后全球房地产繁荣',
    description: '2020年至2022年，全球房地产市场经历了一场出乎意料的繁荣——在新冠疫情导致经济严重衰退的背景下，多数国家的房价反而大幅上涨。美国房价在2020年至2022年间上涨约40%，加拿大上涨约30%，英国上涨约25%，澳大利亚上涨约25%，韩国上涨约20%。这场"疫情繁荣"（pandemic boom）颠覆了传统经济学对房地产市场的认知，也引发了关于住房可负担性和金融稳定的新一轮担忧。 疫情繁荣的驱',
    context: '动因素是多方面的。第一，超低利率——各国央行将利率降至历史最低水平，大幅降低了房贷成本。美国30年期固定房贷利率在2021年初降至约2.65%的历史低位，使购房者的月供大幅减少。第二，远程办公——疫情推动了远程办公的普及，许多城市居民迁往郊区和小城市，寻求更大的居住空间，推高了这些地区的房价。第三，供给不足——2008年金融危机后，全球住房建设长期不足，供需缺口在疫情期间被放大。美国估计缺少约380万套住房。第四，财政刺激——各国政府向家庭和企业提供了大量直接补贴，增加了购房资金。 疫情繁荣的全球性特征值得关注。不仅发达国家房价上涨，许多新兴市场也经历了类似趋势——土耳其、俄罗斯、巴西等国房价大幅上涨。这表明，低利率和供给不足是全球性现象，而非个别国家的特殊情况。 然而，2022年至2023年，随着全球央行大幅加息，房地产市场开始降温。美国30年期房贷利率从2021年的约3%飙升至2023',
