    title: '2015年中国房地产去库存',
    description: '2015年至2018年，中国政府推行了大规模的"房地产去库存"政策，旨在消化三四线城市的大量住房库存。这一政策通过货币化棚改（以现金补偿替代安置房）、降低首付比例和房贷利率等手段，成功刺激了住房需求，但也导致了房价大幅上涨、居民杠杆率快速攀升和房地产泡沫进一步膨胀。去库存政策是中国房地产政策"治标不治本"的典型案例，其短期效果显著但长期代价沉重。 去库存政策的背景是2014年至2015年中国房地产',
    context: '市场的低迷。2014年，全国商品房销售面积同比下降7.6%，销售金额同比下降6.3%。三四线城市面临严重的库存积压——据估计，2015年初全国商品房待售面积约6.5亿平方米，去化周期超过30个月。部分城市的库存消化周期甚至超过5年。开发商资金链紧张，地方政府土地出让收入锐减。 2015年12月，中央经济工作会议将"去库存"列为供给侧结构性改革的五大任务之一。2016年至2018年，政府推出了一系列刺激政策：降低首套房首付比例至20%、二套房首付比例至30%；下调房贷利率；推进货币化棚改——央行通过PSL（抵押补充贷款）向国开行提供资金，国开行向地方政府发放棚改贷款，地方政府以现金补偿拆迁居民，居民用补偿款购买商品房。 货币化棚改是去库存政策的核心工具。2015年至2018年，全国棚改开工量约2400万套，其中货币化安置比例从2015年的约30%提高至2017年的约60%。在三四线城市，货币',
