    title: '2022年全球房地产降温',
    description: '2022年，全球房地产市场经历了自2008年金融危机以来最广泛的降温。在2022年3月至12月间，美联储加息425个基点，其他主要央行也大幅加息，房贷利率飙升，购房负担能力急剧恶化。美国、加拿大、澳大利亚、英国、瑞典、新西兰等国的房价开始下跌，交易量大幅萎缩。2022年全球房地产降温是货币政策对资产价格影响的最新例证，也引发了关于"软着陆"还是"硬着陆"的讨论。 各国房地产市场的降温程度不一。瑞典',
    context: '和加拿大的房价下跌最为严重——瑞典房价在2022年下跌约12%，加拿大下跌约9%。美国房价在2022年下半年开始下跌，但跌幅相对温和（约5%），部分原因是供给不足支撑了价格。英国房价在2022年底开始下跌，但2023年有所企稳。澳大利亚房价在2022年下跌约5%，但2023年重新上涨。新西兰房价在2022年下跌约10%。 房贷利率的飙升是降温的核心驱动力。美国30年期固定房贷利率从2021年底的约3%飙升至2022年10月的约7%，创20年来新高。这意味着，同样30万美元的30年期贷款，月供从约1260美元增加至约1996美元，增幅约58%。许多潜在购房者被挤出市场，购房负担能力指数降至1980年代以来的最低水平。 交易量的萎缩比价格下跌更为显著。美国成屋销售从2021年的约650万套/年降至2022年底的约400万套/年，降幅约38%。这种"量跌价滞"的现象反映了市场的"锁定效应"——已',
