    difficulty: 4,
    title: '2007年美国房地产泡沫破裂',
    description: '2007年，美国住房市场泡沫正式破裂，全国房价开始全面下跌，次贷违约率飙升，多家次贷机构破产，引发了连锁金融反应，最终演变为2008年的全球金融危机。2007年是美国房地产泡沫从"局部问题"升级为"系统性危机"的关键转折点，也是金融监管和风险管理失败的集中体现。 2007年初，美国房价已从2006年中期的高点下跌约5-10%。2月，汇丰银行宣布其美国次贷业务亏损约105亿美元，这是大型金融机构首次',
    context: '披露大规模次贷损失。3月，新世纪金融（New Century Financial）——美国第二大次贷公司——停止发放新贷款，4月申请破产保护。此后，数十家次贷机构相继倒闭。 4月，新世纪金融的破产引发了市场恐慌。投资者开始质疑次贷支持证券的价值，要求评级机构重新评估。7月，穆迪和标普下调了数百只次贷MBS和CDO的评级，触发了持有这些证券的投资者的强制卖出。贝尔斯登旗下的两只对冲基金因大量持有次贷证券而崩溃，投资者损失超过16亿美元。 8月，危机从次贷市场蔓延至更广泛的信贷市场。银行间同业拆借市场冻结，TED利差从正常时期的约30个基点飙升至超过200个基点。欧洲央行和美联储向银行体系注入了大量流动性。9月，英国北岩银行遭遇挤兑——这是英国150年来首次银行挤兑。11月，花旗集团CEO查克·普林斯辞职，此前他曾表示"只要音乐还在响，你就必须站起来跳舞"。 2007年房地产泡沫破裂的传导机制',
