    id: 'case_199',
    category: '金融史',
    difficulty: 3,
    title: '2017年加拿大房地产降温',
    description: '2017年至2018年，加拿大房地产市场在经历了十多年的繁荣后开始降温，多伦多和温哥华等主要城市的房价从高点下跌约15-20%。加拿大房地产降温是政策干预（外国买家税、压力测试）与市场周期自然调整相结合的结果，也是全球主要城市应对住房可负担性危机的重要案例。 加拿大房地产泡沫的形成与多个因素有关。超低利率环境刺激了住房需求——加拿大央行在2015年至2017年将利率维持在0.5%的低水平。外国投资',
    context: '（特别是来自中国的资金）推高了温哥华和多伦多的房价。供给不足——主要城市的土地使用限制和审批流程延缓了新住房建设。投机活动——"炒房"在多伦多和温哥华非常普遍。 2016年至2017年，加拿大政府和地方政府采取了多项干预措施。2016年8月，不列颠哥伦比亚省对大温哥华地区的外国买家征收15%的附加税（后提高至20%）。2017年4月，安大略省对大多伦多地区实施了类似的外国买家税（15%），并扩大了租金管制范围。2018年1月，加拿大联邦政府实施了"压力测试"——购房者必须证明他们能够在比合同利率高200个基点的利率水平下承担月供，才能获得受保险的抵押贷款。 这些政策的效果是显著的。温哥华房价在2016年8月外国买家税实施后立即下跌约15%，但2017年又重新上涨。多伦多房价在2017年4月政策出台后下跌约20%，交易量大幅萎缩。全国房价增速从2017年初的约15%放缓至2018年底的约2%',
