    description: '2014年8月3日，葡萄牙第二大银行圣灵银行（Banco Espírito Santo, BES）因关联企业的财务欺诈而倒闭，被葡萄牙央行拆分为"好银行"（Novo Banco）和"坏银行"。BES的倒闭是欧元区银行业危机的重要案例，也是家族控制银行治理失败的典型——圣灵家族通过复杂的持股结构控制了BES，并将其作为家族企业的融资工具，最终导致银行和家族企业同时崩溃。 BES的危机源于其母公司圣灵',
    context: '集团（Espírito Santo Group, ESG）的财务欺诈。ESG由圣灵家族控制，业务涵盖银行、保险、医疗、农业和房地产等多个领域。2014年5月，ESG的控股公司ESI（Espírito Santo International）被发现存在"严重财务违规"——包括虚增资产、隐瞒负债和发行虚假商业票据。ESI通过发行商业票据向BES的零售客户融资，但这些资金实际上被用于弥补ESG的亏损。 葡萄牙央行在2014年7月发现，BES对ESG的敞口远超此前披露的12亿欧元，实际敞口可能超过50亿欧元。BES的审计师德勤拒绝签署2014年上半年的财务报表，因为无法确认ESG相关资产的回收可能性。7月30日，BES披露上半年净亏损36亿欧元，超过了银行的资本基础。 8月3日，葡萄牙央行宣布将BES拆分：优质资产和零售存款被转移至新成立的Novo Banco，由银行处置基金（由葡萄牙银行出资）提',
