    id: 'case_204',
    category: '银行',
    difficulty: 3,
    title: '2017年西班牙人民银行倒闭',
    description: '2017年5月10日，西班牙第六大银行人民银行（Banco Popular）因流动性危机被欧洲单一处置机制（SRM）以1欧元的价格出售给桑坦德银行。这是欧洲银行联盟处置机制首次被激活，也是"自救"（bail-in）原则在欧元区的重要实践——人民银行的股东和次级债券持有人被全额减记，而存款人和优先债券持有人未受损失。 人民银行的危机源于其对西班牙房地产泡沫的过度暴露。2008年房地产泡沫破裂后，人民',
    context: '银行的不良贷款率持续上升，但银行的资本补充和资产清理进展缓慢。2012年至2016年，人民银行多次进行增资和资产减记，但始终未能彻底解决资产质量问题。2016年底，人民银行的不良贷款率仍高达约15%，房地产相关不良资产约370亿欧元。 2017年初，市场对人民银行的信心开始恶化。3月，审计师德勤对人民银行的持续经营能力提出了"强调事项"。4月，人民银行宣布再次增资25亿欧元，但市场反应冷淡——股价在增资公告后下跌约25%。5月初，人民银行遭遇了电子挤兑——机构客户通过电子渠道大量提取存款，几天内存款外流约8亿欧元。 6月6日至7日，欧洲央行评估认为人民银行"可能倒闭或已经倒闭"，通知单一处置委员会（SRB）启动处置程序。SRB在6月7日凌晨决定将人民银行出售给桑坦德银行，售价为1欧元——这一价格反映了人民银行的资本缺口（约35亿欧元）已超过其股权价值。桑坦德随即宣布将增资70亿欧元来吸收人',
