    title: '2024年纽约社区银行危机',
    description: '2024年初，纽约社区银行（NYCB）因商业房地产贷款减值和内部控制缺陷而陷入危机，股价在1月至3月间下跌超过60%，信用评级被下调至垃圾级。NYCB的危机是2023年地区性银行危机的延续，也暴露了美国商业房地产市场的深层问题——远程办公导致的办公楼空置率上升和利率上升导致的资产价值下降。 NYCB的危机根源可以追溯到2023年对签名银行（Signature Bank）资产的收购。2023年3月签',
    context: '名银行倒闭后，NYCB以折扣价收购了其约380亿美元的贷款和租赁资产。这一收购使NYCB的资产规模超过1000亿美元，触发了更严格的监管要求——资产超过1000亿美元的银行被归类为第四类机构，需要满足更高的资本和流动性标准。 2024年1月31日，NYCB披露了令人震惊的第四季度业绩：净亏损2.52亿美元（上年同期盈利1.72亿美元），主要因商业房地产贷款减值5.52亿美元；将股息从每股17美分削减至5美分；贷款损失准备金增加至5.52亿美元。消息公布后，股价当日下跌38%。 2月6日，穆迪将NYCB的信用评级下调至垃圾级，理由是"与商业房地产相关的风险"和"内部控制缺陷"。评级下调可能触发融资成本上升和抵押品要求增加，进一步恶化NYCB的流动性状况。3月1日，NYCB披露其内部控制存在"重大缺陷"（material weakness），与贷款审查流程有关，并更换了CEO。 3月6日，NY',
