    id: 'case_206',
    category: '金融史',
    difficulty: 3,
    title: '2008年富通集团拆分救助',
    description: '2008年10月，比利时-荷兰金融集团富通集团（Fortis）因流动性危机被比利时、荷兰和卢森堡三国政府拆分救助。富通是2007年RBS财团收购ABN AMRO的参与者之一，收购了ABN AMRO的荷兰业务，但这一收购使其资本严重不足，在2008年金融危机中率先倒下。富通的拆分救助是欧洲跨国银行危机管理的首个重大案例，也暴露了跨国金融机构监管协调的困难。 富通集团成立于1990年，由比利时、荷兰和',
    context: '卢森堡的多家保险公司和银行合并而成，是比荷卢地区最大的金融集团。2007年10月，富通与RBS和Santander组成财团，以约710亿欧元收购了ABN AMRO，其中富通以约240亿欧元收购了ABN AMRO的荷兰业务。这一收购使富通的资产负债表急剧膨胀，资本充足率下降。 2008年7月，富通披露上半年净亏损19.3亿欧元，主要因次贷相关减值和ABN AMRO收购的整合成本。市场信心急剧恶化，富通股价在7月至9月间下跌超过60%。9月底，富通面临严重的流动性危机——客户大量提取存款，银行间市场融资渠道关闭。 9月28日至29日周末，比荷卢三国政府紧急磋商，达成了救助方案：荷兰政府以168亿欧元收购了富通的荷兰业务（包括ABN AMRO荷兰）；比利时政府以47亿欧元收购了富通的比利时业务75%的股份；卢森堡政府以28亿欧元收购了富通卢森堡的49.9%股份。富通被实质上拆分为三个部分，分别由',
