    id: 'case_207',
    category: '金融史',
    difficulty: 3,
    title: '2009年荷兰ING集团救助',
    description: '2009年10月26日，荷兰政府与ING集团达成协议，将其约350亿欧元的美国抵押贷款相关资产转移至单独实体，由政府承担80%的损失风险，同时ING获得100亿欧元的资本注入。这是荷兰政府在2008年金融危机中对银行业最大规模的救助行动之一，也标志着ING从综合金融集团向聚焦欧洲银行业务的战略转型。 ING的危机源于其美国子公司ING Direct的高风险抵押贷款业务。ING Direct是美国最',
    context: '大的在线银行之一，通过高利率存款吸引了大量客户，然后将资金投资于Alt-A和次级抵押贷款支持证券。2007年至2008年，这些证券的价值急剧下降，ING被迫大量减记。2008年第四季度，ING净亏损33亿欧元，是荷兰历史上最大的季度亏损。 2008年10月，荷兰政府向ING注资100亿欧元，获得了无投票权的优先股。然而，ING的资产质量继续恶化。2009年1月，ING宣布将拆分为银行和保险两个业务，以简化结构并满足欧盟的国家援助条件。10月，ING与荷兰政府达成了"坏银行"协议——将约350亿欧元的美国抵押贷款相关资产转移至单独实体，政府承担80%的损失风险（上限为80%），ING承担20%。 作为欧盟国家援助审批的条件，ING被要求进行大规模重组。2013年至2018年，ING逐步出售或分拆了其保险和资产管理业务——ING Insurance被分拆为独立公司（后更名为NN Group），',
