    title: '2015年希腊银行体系重组',
    description: '2015年，希腊银行体系经历了自欧元区危机以来最严峻的考验——资本管制、银行关闭和大规模资本重组。希腊银行体系的重组是欧债危机中最复杂的金融工程之一，涉及约430亿欧元的公共资金注入、约1400亿欧元的流动性支持和深层次的结构性改革。这一案例展示了银行体系与主权信用之间的深度关联，以及极端压力下银行重组的挑战。 2015年6月底，希腊与债权人的谈判破裂，齐普拉斯政府宣布举行公投。市场恐慌导致银行存',
    context: '款大规模外流——6月最后一周，约40亿欧元被提取。6月28日，希腊政府实施资本管制：银行关闭三周，每人每日取款限额60欧元，禁止向海外转账。欧洲央行冻结了对希腊银行的紧急流动性援助（ELA），银行完全依赖有限的现金储备运营。 7月公投后，希腊与债权人达成了第三轮救助协议。作为条件，希腊银行必须进行全面的压力测试和资本重组。2015年10月至11月，欧洲央行对希腊四大银行（希腊国家银行、比雷埃夫斯银行、欧元银行和阿尔法银行）进行了资产质量审查（AQR）和压力测试，发现资本缺口约145亿欧元。 资本重组采用了"自救"（bail-in）和"救助"（bail-out）相结合的方式。首先，银行对次级债券持有人实施减记（bail-in），约43亿欧元的次级债券被转换为股权。然后，希腊金融稳定基金（HFSF）——由救助资金资助——向银行注入约95亿欧元的股权资本。HFSF成为四大银行的主要股东，持股比例',
