    title: '2010年盎格鲁爱尔兰银行危机',
    description: '2010年，爱尔兰最大的银行之一盎格鲁爱尔兰银行（Anglo Irish Bank）因房地产贷款巨亏而崩溃，最终被国有化并清算，爱尔兰政府为此付出了约293亿欧元的代价——相当于每个爱尔兰公民约6500欧元。盎格鲁爱尔兰银行的倒闭是爱尔兰银行业危机的核心事件，也是全球金融危机中最昂贵的单一银行救助案例之一。 盎格鲁爱尔兰银行由肖恩·菲茨帕特里克（Seán FitzPatrick）于1980年代领导',
    context: '发展，以激进的商业房地产贷款策略闻名。2000年代爱尔兰房地产泡沫期间，盎格鲁爱尔兰银行大量向房地产开发商提供贷款，贷款增速远超同行——2003年至2008年间，其贷款组合从约250亿欧元膨胀至约720亿欧元。银行的商业模式高度依赖短期批发融资——通过发行担保债券从国际市场借款，然后贷给开发商。 2008年9月，全球金融危机爆发后，爱尔兰房地产泡沫破裂，开发商开始违约。12月，盎格鲁爱尔兰银行披露其董事长菲茨帕特里克在数年间隐瞒了从银行获得的约1.22亿欧元贷款——这些贷款被临时转移到另一家银行以规避披露要求。菲茨帕特里克被迫辞职，随后被逮捕并因欺诈罪被判处缓刑。 2009年1月，爱尔兰政府对盎格鲁爱尔兰银行实施国有化，注入了约40亿欧元的资本。然而，银行的亏损远超预期——2009年亏损约125亿欧元，2010年亏损约178亿欧元。政府被迫多次追加注资，最终总救助成本约293亿欧元。 盎格',
