    id: 'case_210',
    category: '银行',
    difficulty: 3,
    title: '2012年德克夏银行救助',
    description: '2012年，法比跨国银行德克夏银行（Dexia）因主权债务风险和流动性危机再次被政府救助——这是该银行在三年内第二次接受救助。德克夏的案例是欧元区危机中银行与主权信用"厄运循环"的典型体现，也暴露了跨国银行监管协调的困难。 德克夏银行成立于1996年，由法国和比利时的公共融资银行合并而成，专注于向法国和比利时的地方政府提供融资。德克夏的商业模式是：向地方政府提供长期贷款，然后通过发行短期债券融资—',
    context: '—这种严重的期限错配在正常时期可以盈利（长期利率高于短期利率），但在市场信心丧失时可能导致流动性危机。 2008年，德克夏因持有大量次贷相关证券而首次面临危机。比利时、法国和卢森堡政府联合向德克夏注资约60亿欧元，并为其约1200亿欧元的资产提供了国家担保。德克夏被拆分——其法国和比利时的零售银行业务被出售，剩余的"德克夏公共融资"实体继续持有地方政府贷款组合。 然而，2011年欧债危机恶化后，德克夏再次面临流动性危机。市场对法国和比利时主权信用的担忧导致德克夏的融资成本上升，短期债券市场几乎关闭。2011年10月，三国政府再次救助德克夏，提供了约450亿欧元的额外担保和资本注入。德克夏被进一步拆分——其剩余资产被转移至一个"坏银行"实体，由政府担保支持。 2012年，欧盟委员会批准了德克夏的重组计划，条件是德克夏必须有序清算，不再从事新的业务。德克夏的资产被逐步出售或到期收回，剩余的约8',
